    "q.m10#14.o2" to "天候が安定している証拠",
    "q.m10#14.o3" to "風とは無関係",
    "q.m10#14.e" to "地形性の雲は「風と湿り」の可視化です。雲が急速に流されていれば、尾根の風は限界を超えていると判断できます。",
    "q.m10#15.p" to "予報の「有効期間」が長いほど信頼できないのはなぜですか。",
    "q.m10#15.o0" to "大気はカオス系で、誤差は時間とともに指数関数的に拡大する",
    "q.m10#15.o1" to "モデルが粗いから",
    "q.m10#15.o2" to "データが不完全だから",
    "q.m10#15.o3" to "標高が高いから",
    "q.m10#15.e" to "3 日以内の傾向は比較的信頼でき、7 日以上は参考程度です。行程には「窓を待つ」時間を確保します。",
    "q.m10#16.p" to "山の観測所のデータと、これから行く標高との差は主に何から生じますか。",
    "q.m10#16.o0" to "標高差による気温、風速、降水形態の違い",
    "q.m10#16.o1" to "観測機器の誤差",
    "q.m10#16.o2" to "時間帯",
    "q.m10#16.o3" to "緯度",
    "q.m10#16.e" to "谷の観測点で「小雨」なら、5,000 m では「大雪＋強風」かもしれません。予報は標高に換算して読みます。",
    "q.m10#17.p" to "稲妻が見えてから 30 秒以内に雷鳴が聞こえたら、何を意味しますか。",
    "q.m10#17.o0" to "雷雨がすでに近く、露出した地形からただちに離れるべき",
    "q.m10#17.o1" to "雷雨は遠い",
    "q.m10#17.o2" to "安全",
    "q.m10#17.o3" to "ただの偶然",
    "q.m10#17.e" to "光速と音速の差から距離を推定できます。間隔が短いほど近く、「30 秒」はよく使われる行動の閾値です。",
    "q.m10#18.p" to "なぜアタックは未明に組むことが多いのですか。",
    "q.m10#18.o0" to "雪面が凍って安定し、午後は雲と風が強まることが多いから",
    "q.m10#18.o1" to "写真を撮るため",
    "q.m10#18.o2" to "人が少ないから",
    "q.m10#18.o3" to "ガイドの習慣だから",
    "q.m10#18.e" to "未明の硬い雪と安定した天候の窓が主な理由です。代償は低温と睡眠不足で、前もって準備が要ります。",
    "q.m10#19.p" to "天候の窓が狭くなったとき、最初に諦めるべきものは何ですか。",
    "q.m10#19.o0" to "登頂という目標であり、安全の余裕ではない",
    "q.m10#19.o1" to "防寒着",
    "q.m10#19.o2" to "予備装備",
    "q.m10#19.o3" to "通信機器",
    "q.m10#19.e" to "窓が足りないとき、削られるのはたいてい「余裕」のほうで、それこそが事故の始まりです。正しい取捨は目標を先に諦めることです。",
    "q.l43#0.p" to "高所での皮膚トラブルの主な原因三つはどれですか。",
    "q.l43#0.o0" to "乾燥、紫外線、風",
    "q.l43#0.o1" to "寒冷、湿気、摩擦",
    "q.l43#0.o2" to "低酸素、低気圧、低温",
    "q.l43#0.o3" to "食事、睡眠、ストレス",
    "q.l43#0.e" to "この三つが同時に働くと、皮膚のバリアはすぐに破れます。保湿と日焼け対策は「ぜいたく」ではなく、行動能力を保つためのものです。",
    "q.l43#1.p" to "カイロの正しい使い方はどれですか。",
    "q.l43#1.o0" to "腰の後ろ、腹部、ブーツの外側に貼り、皮膚には直接貼らない",
    "q.l43#1.o1" to "皮膚に直接貼る",
    "q.l43#1.o2" to "額に貼る",
    "q.l43#1.o3" to "寝るときに全身に貼る",
    "q.l43#1.e" to "皮膚に直接貼ると低温やけどを起こすことがあり、そのやけどは高所ではなかなか治りません。カイロが防ぐのは深部体温の低下です。",
    "q.l43#2.p" to "食器洗いの水の正しい処理はどれですか。",
    "q.l43#2.o0" to "残渣をこし取ってから分散して捨て、残渣は持ち帰る",
    "q.l43#2.o1" to "沢に流す",
    "q.l43#2.o2" to "テントの脇に捨てる",
    "q.l43#2.o3" to "トイレの穴に捨てる",
    "q.l43#2.e" to "残渣は汚染と動物を招く原因です。こし取って持ち帰り、水は分散して捨てるのが低影響のやり方です。",
    "q.l43#3.p" to "肌着を優先して洗うのはなぜですか。",
    "q.l43#3.o0" to "汗の塩分が皮膚を擦りむき、その傷が高所では治りにくいから",
    "q.l43#3.o1" to "見た目のため",
    "q.l43#3.o2" to "軽いから",
    "q.l43#3.o3" to "安いから",
    "q.l43#3.e" to "肌着の塩分と細菌は皮膚を刺激し続けます。乾燥と低温の環境では、小さな擦り傷が数週間治らないことがあります。",
    "q.l43#4.p" to "ダウンジャケットが汚れたり濡れたりしたとき、正しい対応はどれですか。",
    "q.l43#4.o0" to "洗わず、表面の雪を払って乾かす",
    "q.l43#4.o1" to "洗剤でもみ洗いする",
    "q.l43#4.o2" to "絞る",
    "q.l43#4.o3" to "火であぶって乾かす",
    "q.l43#4.e" to "ダウンは洗った後、野外でふくらみを取り戻すのが難しいものです。濡れたら干すだけで、火であぶらないこと。生地とダウンを傷めます。",
    "q.l43#5.p" to "キャンプの秩序三か条に含まれないものはどれですか。",
    "q.l43#5.o0" to "食べ物をテントに入れて一晩置く",
    "q.l43#5.o1" to "靴は前室に置く",
    "q.l43#5.o2" to "食べ物をテントに持ち込まない",
    "q.l43#5.o3" to "ごみはまとめて高い所に吊るす",
    "q.l43#5.e" to "食べ物をテントに入れると動物を睡眠区へ直接招き、においもシュラフに長く残ります。三か条は防湿・防動物・防汚染を同時に担います。",
    "q.l43#6.p" to "高所でリップケアが重要なのはなぜですか。",
    "q.l43#6.o0" to "唇にはメラニンの防御がなく、ひび割れると食事も会話も痛むから",
    "q.l43#6.o1" to "見た目のため",
    "q.l43#6.o2" to "日焼けして黒くなるから",
    "q.l43#6.o3" to "腫れるから",
    "q.l43#6.e" to "唇は最も見落としやすい日焼け対策の部位であり、「痛むと食事に響く」部位でもあります。リップクリームは携行します。",
    "q.l43#7.p" to "身だしなみの手入れの時間はどう組むべきですか。",
    "q.l43#7.o0" to "毎日の短い手順として固定する（朝晩それぞれ数分）。時間があるときに行うのではない",
    "q.l43#7.o1" to "日が出てから行う",
    "q.l43#7.o2" to "週に一度",
    "q.l43#7.o3" to "気分次第",
    "q.l43#7.e" to "手入れの価値は「続けること」から生まれます。固定した手順なら疲れていても実行でき、意志に頼ると飛ばしてしまいます。",
    "q.l43#8.p" to "キャンプ生活で「1 人 1 組・名前を書く」べきものはどれですか。",
    "q.l43#8.o0" to "食器",
    "q.l43#8.o1" to "洗面用具",
    "q.l43#8.o2" to "コップ",
    "q.l43#8.o3" to "テント",
    "q.l43#8.e" to "前の三つは口と皮膚に触れる物で、共用すると消化器や皮膚の問題が広がります。テントは人ごとに割り当てるもので、名前を書く必要はありません。",
    "q.l43#9.p" to "高所で毎日行うべき手入れはどれですか。",
    "q.l43#9.o0" to "日焼け止めを塗る（唇を含む）",
    "q.l43#9.o1" to "保湿する",
    "q.l43#9.o2" to "乾いた靴下に替え、靴を乾かす",
    "q.l43#9.o3" to "毎日シャワーを浴びる",
    "q.l43#9.e" to "前の三つは皮膚と足の状態に直結します。高所で毎日シャワーは現実的でも必要でもなく、部分的な清潔で足ります。",
    "q.l43#10.p" to "カイロの使用で避けるべきことはどれですか。",
    "q.l43#10.o0" to "皮膚に直接貼る",
    "q.l43#10.o1" to "寝るときに同じ場所へ長時間貼る",
    "q.l43#10.o2" to "すでに凍傷になった部位に貼る",
    "q.l43#10.o3" to "腰の後ろに貼る",
    "q.l43#10.e" to "前の三つは低温やけどを起こしたり、感覚が鈍いときに損傷を悪化させたりします。腰の後ろはよく使う位置です。",
    "q.l43#11.p" to "キャンプ到着後の生活の流れを順に並べてください。",
    "q.l43#11.o0" to "まず濡れた肌着を着替え、防寒着を重ねる",
    "q.l43#11.o1" to "テントを張り、マットを敷き、靴と靴下を干す",
    "q.l43#11.o2" to "湯を沸かし、食事と水分をとる",
    "q.l43#11.o3" to "手入れを固定手順で行う（日焼け対策・保湿・リップ・擦り傷の処置）",
    "q.l43#11.e" to "順序の核は「まず熱の喪失を止める」ことです。先に料理をして後で着替えるのが、最もよくある誤りです。",
    "q.l43#12.p" to "カイロは腰の後ろ、腹部、ブーツの外側に貼り、______ には直接貼らない。",
    "q.l43#12.a0" to "皮膚",
    "q.l43#12.a1" to "体",
    "q.l43#12.e" to "皮膚に直接貼ると低温やけどを起こすことがあり、そのやけどは高所では極めて治りにくいです。",
    "q.l43#13.p" to "キャンプの秩序では、食べ物を ______ に入れないことになっています。",
    "q.l43#13.a0" to "テント",
    "q.l43#13.a1" to "寝床",
    "q.l43#13.e" to "食べ物のにおいは動物を睡眠区へ招き、シュラフや衣類にも長く残ります。",
    "q.l43#14.p" to "手入れの動作と、それが防ぐ問題を対応させてください。",
    "q.l43#14.l0" to "日焼け対策とリップ",
    "q.l43#14.l1" to "保湿",
    "q.l43#14.l2" to "乾いた靴下に替える",
    "q.l43#14.l3" to "カイロ",
    "q.l43#14.r0" to "紫外線による灼傷（雪目のリスクを含む）",
    "q.l43#14.r1" to "皮膚のひび割れ、バリアの破綻",
    "q.l43#14.r2" to "水疱と浸軟",
    "q.l43#14.r3" to "深部体温の低下",
    "q.l43#14.e" to "四つの動作が四種類の問題に対応します。どれも難しくなく、難しいのは毎日続けることです。",
    "q.l43#15.p" to "高所で洗濯する、最も現実的な方法はどれですか。",
    "q.l43#15.o0" to "肌着だけを少量の洗剤で洗ってすすぎ、テント内に吊るして乾かす",
    "q.l43#15.o1" to "全部洗う",
    "q.l43#15.o2" to "洗わない",
    "q.l43#15.o3" to "雪でこする",
    "q.l43#15.e" to "水も燃料も貴重です。必ず洗う必要があるのは肌着だけで、他は干す・叩くで足ります。",
    "q.l43#16.p" to "高所での日焼け止めの塗り直しの目安はどれですか。",
    "q.l43#16.o0" to "2〜3 時間ごと。汗をかいた後や雪が融けた後にも塗り直す",
    "q.l43#16.o1" to "朝に一度",
    "q.l43#16.o2" to "1 日に一度",
    "q.l43#16.o3" to "塗り直さない",
    "q.l43#16.e" to "紫外線が強く、風が強く、雪面が反射するため、日焼け止めの膜はすぐに失效します。高い数値を選ぶより塗り直しのほうが重要です。",
    "q.l43#17.p" to "夜にキャンプの外へ出るとき、最も見落としやすいことは何ですか。",
    "q.l43#17.o0" to "靴かキャンプ用の靴を履く。靴下だけで雪を踏まない",
    "q.l43#17.o1" to "カメラを持つ",
    "q.l43#17.o2" to "水を持つ",
    "q.l43#17.o3" to "帽子をかぶる",
    "q.l43#17.e" to "靴下が濡れると一晩中冷たく、凍傷や低体温症のリスクも上がります。キャンプ用の靴は最も簡単で効果的な装備です。",
    "q.l43#18.p" to "ウェットティッシュや紙類の消耗品はどう計画すべきですか。",
    "q.l43#18.o0" to "日ごとに小分けし、予備を一つ残す。湿気を避ける",
    "q.l43#18.o1" to "袋ごと持つ",
    "q.l43#18.o2" to "多めに持つ",
    "q.l43#18.o3" to "持たない",
    "q.l43#18.e" to "袋ごとだと湿気やすく場所も取ります。日ごとに分ければ量を管理でき、濡れた後にも予備が残ります。",
    "q.l43#19.p" to "身の回りの用品で最も「2 個持つ」べきものはどれですか。",
    "q.l43#19.o0" to "リップクリームと日焼け止め",
    "q.l43#19.o1" to "シャンプー",
    "q.l43#19.o2" to "香水",
    "q.l43#19.o3" to "かみそり",
    "q.l43#19.e" to "この二つは小さく、失うと代えが効かず、食事と皮膚のバリアに直接影響します。",
    "q.m11#12.p" to "玉珠峰の南斜面が 6,000 m 級の最初の一歩に向くのはなぜですか。",
    "q.m11#12.o0" to "雪の斜面が比較的なだらかで、交通の便がよく、ルートが確立している",
    "q.m11#12.o1" to "最も高いから",
    "q.m11#12.o2" to "技術的に最も難しいから",
    "q.m11#12.o3" to "人が少ないから",
    "q.m11#12.e" to "「最初の 6,000 m」の目的は順応と体力の検証で、技術への挑戦ではありません。確立したルートは未知を減らします。",
    "q.m11#13.p" to "啓孜峰が属する山脈はどれですか。",
    "q.m11#13.o0" to "ニェンチェンタングラ山脈",
    "q.m11#13.o1" to "崑崙山脈",
    "q.m11#13.o2" to "ヒマラヤ山脈",
    "q.m11#13.o3" to "カラコルム山脈",
    "q.m11#13.e" to "啓孜峰はチベットのダムシュン（当雄）にあり、ニェンチェンタングラに属します。山脈は気候と季節の窓を決めるため、峰選びの重要な背景です。",
    "q.m11#14.p" to "ロブチェ東峰の最も典型的な用途はどれですか。",
    "q.m11#14.o0" to "6,000 m 級と 8,000 m 級の間の橋渡し、および技術訓練",
    "q.m11#14.o1" to "観光ルートとして",
    "q.m11#14.o2" to "スキー場として",
    "q.m11#14.o3" to "展望台として",
    "q.m11#14.e" to "エベレストのトレッキングルートのすぐ脇にあり、雪の斜面はやや急で交通も便利なため、よく使われる橋渡しの峰です。",
    "q.m11#15.p" to "島峰（イムジャ・ツェ）の技術的な特徴はどれですか。",
    "q.m11#15.o0" to "ロープで結ぶ行進とクレバスの通過が必要な、典型的な技術系 6,000 m",
    "q.m11#15.o1" to "純粋なトレッキング",
    "q.m11#15.o2" to "雪の斜面歩きだけで足りる",
    "q.m11#15.o3" to "一年中雪がない",
    "q.m11#15.e" to "島峰の「技術」は岩壁ではなく、氷河とクレバスにあります。結び行進とクレバス救助は必須の能力です。",
    "q.m11#16.p" to "6,000 m 級の峰を選ぶとき、標高より注目すべきはどれですか。",
    "q.m11#16.o0" to "ルートの形態（雪の斜面／氷河／岩壁）と撤退の難しさ",
    "q.m11#16.o1" to "名前の響き",
    "q.m11#16.o2" to "距離の遠近",
    "q.m11#16.o3" to "費用の高低",
    "q.m11#16.e" to "同じ 6,100 m でも、雪の斜面と氷河のルートでは要求が一桁違います。まず形態を見て、その後に標高を見ます。",
    "q.m11#17.p" to "6,000 m 級の許可とガイドの要件は、通常 5,000 m 級と比べてどうですか。",
    "q.m11#17.o0" to "より厳しく、届出やガイドの義務が多い",
    "q.m11#17.o1" to "より緩い",
    "q.m11#17.o2" to "まったく同じ",
    "q.m11#17.o3" to "要件はない",
    "q.m11#17.e" to "標高が高くルートが奥まるほど、管理は厳しくなります。出発前に規定を確認するほうが、山麓で聞くよりはるかに楽です。",
    "q.m11#18.p" to "6,000 m 級で「クレバスはあるものとして扱う」のはなぜですか。",
    "q.m11#18.o0" to "雪橋に覆われると目視で判断できず、クレバスがある前提で結ばなければならないから",
    "q.m11#18.o1" to "クレバスが必ずあるから",
    "q.m11#18.o2" to "ガイドが求めるから",
    "q.m11#18.o3" to "保険の規定だから",
    "q.m11#18.e" to "「見えない」は「ない」ではありません。結ぶ手間は小さく、クレバスへ落ちる代償はきわめて大きいのです。",
    "q.m11#19.p" to "6,000 m 級の順応の組み方は、通常 5,000 m 級と比べてどうですか。",
    "q.m11#19.o0" to "より長い。睡眠標高が高く、回復が遅いから",
    "q.m11#19.o1" to "より短い",
    "q.m11#19.o2" to "同じ",
    "q.m11#19.o3" to "順応は不要",
    "q.m11#19.e" to "標高が一段上がるごとに順応の時間は延びます。5,000 m のペースをそのまま 6,000 m に当てはめるのは、よくある過小評価です。",
    "q.m12#16.p" to "3:1 システムの理論的な機械的優位はどれですか。",
    "q.m12#16.o0" to "ロープを 1 m 引くと、荷重は約 1/3 m 上がる",
    "q.m12#16.o1" to "荷重が 1/2 になる",
    "q.m12#16.o2" to "速さが変わらない",
    "q.m12#16.o3" to "摩擦結びが不要",
    "q.m12#16.e" to "機械的優位＝荷重を支えるロープの本数です。3:1 は出力量が荷重の約三分の一（摩擦を除く）という意味です。",
    "q.m12#17.p" to "実際の救助で、5:1 システムの効率は通常どうなりますか。",
    "q.m12#17.o0" to "プーリーとロープの摩擦損失のため、理論値より低くなる",
    "q.m12#17.o1" to "理論値より高くなる",
    "q.m12#17.o2" to "理論値と完全に一致する",
    "q.m12#17.o3" to "摩擦とは関係ない",
    "q.m12#17.e" to "プーリーにはそれぞれ摩擦損失があり、実際の効率は理論値の六〜七割にとどまることが多いです。設計時には余裕を見ます。",
    "q.m12#18.p" to "プーリーの代わりにカラビナを「方向転換点」に使うとき、主な代償は何ですか。",
    "q.m12#18.o0" to "摩擦が大きく増え、効率が落ちる",
    "q.m12#18.o1" to "強度が足りない",
    "q.m12#18.o2" to "ハーネスが摩耗する",
    "q.m12#18.o3" to "ロックできない",
    "q.m12#18.e" to "カラビナは方向を変えられますが摩擦は減らさず、引く力の一部が摩擦に奪われます。プーリーがあるならプーリーを優先します。",
    "q.m12#19.p" to "救助システムにおける「一方向の摩擦結び」の役割は何ですか。",
    "q.m12#19.o0" to "引いた後にロックし、荷重が戻るのを防ぐ",
    "q.m12#19.o1" to "強度を増す",
    "q.m12#19.o2" to "摩擦を減らす",
    "q.m12#19.o3" to "ロープ 2 本をつなぐ",
    "q.m12#19.e" to "摩擦結びがなければ、手を離すたびに荷重が戻ってしまいます。摩擦結びは「断続的な引く力を移動量に変える」鍵です。",
    "q.m12#20.p" to "救助システムに「バックアップの摩擦結び」を設けるのはなぜですか。",
    "q.m12#20.o0" to "主の摩擦結びが滑ったり失效したりする可能性があり、バックアップが最後の保険になるから",
    "q.m12#20.o1" to "見た目のため",
    "q.m12#20.o2" to "引く力を増すため",
    "q.m12#20.o3" to "ロープを節約するため",
    "q.m12#20.e" to "摩擦結びの信頼性はロープ径の適合と状態に依存します。重要なシステムでは二重の摩擦結びが標準です。",
    "q.m12#21.p" to "要救助者を引っ張るとき、システムはできるだけどうすべきですか。",
    "q.m12#21.o0" to "地形に沿わせ、要救助者が岩壁や雪庇にぶつからないようにする",
    "q.m12#21.o1" to "できるだけ高く引く",
    "q.m12#21.o2" to "できるだけ速く",
    "q.m12#21.o3" to "垂直に引き上げる",
    "q.m12#21.e" to "引っ張りによる傷害は、引く力より衝突から生じることが多いです。ルートの計画と支点の位置も同じくらい重要です。",
    "q.m12#22.p" to "6:1 システム（複合システム）が 3:1 に対して払う代償はどれですか。",
    "q.m12#22.o0" to "器材が増え、設置が遅くなり、ロープの消費も大きい",
    "q.m12#22.o1" to "楽になるが速い",
    "q.m12#22.o2" to "代償はない",
    "q.m12#22.o3" to "回収できない",
    "q.m12#22.e" to "機械的優位が高いほど設置は複雑になり、必要なロープも長くなります。救助では「速い」ことのほうが「楽」より重要なことが多いのです。",
    "q.m12#23.p" to "システムの途中で「切り替え」が必要なとき、最も基本的な要件は何ですか。",
    "q.m12#23.o0" to "どの瞬間にも少なくとも一つの装置が荷重を受けており、無接続の空白が生じないこと",
    "q.m12#23.o1" to "動作が速いこと",
    "q.m12#23.o2" to "2 人で連携すること",
    "q.m12#23.o3" to "同じロープを使うこと",
    "q.m12#23.e" to "切り替えは救助事故の多発点です。「古いものを外して新しく組む」ときは、必ず先に新しい接続を作ります。",
    "q.m12#24.p" to "システムの中でロープが鋭い縁を回るときはどうすべきですか。",
    "q.m12#24.o0" to "プロテクションを付けるか走向を変え、ロープの皮膜が切られないようにする",
    "q.m12#24.o1" to "そのまま回す",
    "q.m12#24.o2" to "少し張る",
    "q.m12#24.o3" to "スリングで代用する",
    "q.m12#24.e" to "荷重のかかったロープは切傷が入ると強度が急落します。プロテクションの費用は小さく、代償はロープ 1 本か墜落 1 回かもしれません。",
    "q.m12#25.p" to "救助システムの支点に、通常のビレイステーションより高い要求が課されるのはなぜですか。",
    "q.m12#25.o0" to "静荷重に動的な変動が加わり、しかもシステムが一つしかないことが多いから",
    "q.m12#25.o1" to "より重要だから",
    "q.m12#25.o2" to "人数が多いから",
    "q.m12#25.o3" to "ロープが長いから",
    "q.m12#25.e" to "救助時には二つ目のビレイステーションが支えてくれません。支点が失效すれば「2 人が一緒に落ちる」ことになります。",
    "q.m12#26.p" to "引き上げに必要な力を推定するとき、機械的優位のほかに何を考えますか。",
    "q.m12#26.o0" to "要救助者と装備の重さ、ロープとプーリーの摩擦、地形の抵抗",
    "q.m12#26.o1" to "天候",
    "q.m12#26.o2" to "時間",
    "q.m12#26.o3" to "同行者の体重",
    "q.m12#26.e" to "「理論の引く力」は過小評価されがちです。摩擦と地形を加えると、実際に必要な力は理論値の二倍になることがあります。",
    "q.m12#27.p" to "システムを組み終えた後、最初にすべきことは何ですか。",
    "q.m12#27.o0" to "空荷で一度引いてみて、走向・摩擦結び・支点が正常か確認する",
    "q.m12#27.o1" to "すぐ人を引く",
    "q.m12#27.o2" to "写真を撮る",
    "q.m12#27.o3" to "ロープを巻く",
    "q.m12#27.e" to "空荷の試し引きで、組み立ての誤りの 8 割は見つかります。この十数秒が、システム失效 1 回を防ぐかもしれません。",
    "q.l32#0.p" to "固定ロープを用途で三つに分けると、どれが正しい組ですか。",
    "q.l32#0.o0" to "手すりロープ、短区間の固定ロープ、遠征のフィックス",
    "q.l32#0.o1" to "シングル、ハーフ、ツイン",
    "q.l32#0.o2" to "ダイナミック、スタティック、細引き",
    "q.l32#0.o3" to "上段、中段、下段",
    "q.l32#0.e" to "三種類は三つの場面と三つの標準的なやり方に対応します。場面を取り違えると、手すりロープのやり方でシーズン中使い続けるルートを整備することになります。",
    "q.l32#1.p" to "長い距離の固定ロープにはどのロープを使うべきですか。",
    "q.l32#1.o0" to "スタティックロープ（低伸度）",
    "q.l32#1.o1" to "ダイナミックロープ",
    "q.l32#1.o2" to "細引き",
    "q.l32#1.o3" to "スリング",
    "q.l32#1.e" to "ダイナミックロープの伸びはフォールのために設計されています。固定ロープに使うと、ロープの上で上下に跳ねるような動きが出て、摩耗も速くなります。",
    "q.l32#2.p" to "固定ロープに使うスタティックロープの一般的な直径はどれですか。",
    "q.l32#2.o0" to "9〜11 mm",
    "q.l32#2.o1" to "5〜6 mm",
    "q.l32#2.o2" to "7〜8 mm",
    "q.l32#2.o3" to "12〜14 mm",
    "q.l32#2.e" to "細すぎると耐摩耗性が悪く手触りも滑り、太すぎると重量と体積が増えます。9〜11 mm が遠征のフィックスの標準的な範囲です。",
    "q.l32#3.p" to "「二つの支点を 1 本のスリングに通す」ことの問題は何ですか。",
    "q.l32#3.o0" to "直列失效になり、冗長性がない",
    "q.l32#3.o1" to "スリングがもったいない",
    "q.l32#3.o2" to "見た目が悪い",
    "q.l32#3.o3" to "ロープの速度に影響する",
    "q.l32#3.e" to "直列の構造では、一つの支点が外れるとシステム全体が緩み、荷重が急変します。冗長性の前提は「それぞれ独立してメインカラビナに接続すること」です。",
    "q.l32#4.p" to "支点の五項目チェックのうち「独立」とは何を指しますか。",
    "q.l32#4.o0" to "二つの支点が別の岩体、別の木、別のボルトにあること",
    "q.l32#4.o1" to "二つの支点が近いこと",
    "q.l32#4.o2" to "同じスリングを使うこと",
    "q.l32#4.o3" to "同じクラックに入れた二つのナッツであること",
    "q.l32#4.e" to "同じクラックの二つのナッツは、同じ岩体が崩れれば一緒に抜けます。独立性が問うのは「破損の原因が同じかどうか」です。",
    "q.l32#5.p" to "支点の「方向」のチェックとは何を指しますか。",
    "q.l32#5.o0" to "実際の荷重方向に耐えられること。下向きだけでなくてよい",
    "q.l32#5.o1" to "支点が景色のほうを向いていること",
    "q.l32#5.o2" to "ロープの走向がまっすぐであること",
    "q.l32#5.o3" to "支点が上方にあること",
    "q.l32#5.e" to "フィックス中の横振れや登攀中の振り子は横向きの力を作ります。下向きだけを考えた支点は、横向きの荷重で失效します。",
    "q.l32#6.p" to "雪上の支点でとくに警戒すべきことは何ですか。",
    "q.l32#6.o0" to "雪層の強度と融解のリスク。雪が融けると全体が失效し得る",
    "q.l32#6.o1" to "雪が軟らかくて埋めにくい",
    "q.l32#6.o2" to "雪でロープが濡れる",
    "q.l32#6.o3" to "スノーバーが重い",
    "q.l32#6.e" to "雪上支点の信頼性は温度と時間に強く依存します。午後に雪が融けた支点は、早朝とはまったく別物かもしれません。",
    "q.l32#7.p" to "ロープの端に結び目を入れる目的は何ですか。",
    "q.l32#7.o0" to "端が器具から抜けるのを防ぐ",
    "q.l32#7.o1" to "回収しやすくする",
    "q.l32#7.o2" to "長さを示す",
    "q.l32#7.o3" to "摩擦を増やす",
    "q.l32#7.e" to "下降やフォロー中に端が器具から抜ければ、人は接続を失います。末端の結び目は最も安上がりで効果の高い保険です。",
    "q.l32#8.p" to "中間のリレイ（re-belay）の主な役割は何ですか。",
    "q.l32#8.o0" to "ロープを滑らかに通し、フォールと摩耗を 1 区間の中に抑える",
    "q.l32#8.o1" to "重量を増やす",
    "q.l32#8.o2" to "写真を撮りやすくする",
    "q.l32#8.o3" to "ビレイステーションの代わりになる",
    "q.l32#8.e" to "長いルートでリレイを取らないと、ロープが岩角で大きく折れ、引き抜きが困難になり、摩耗が集中し、フォール距離も長くなります。",
    "q.l32#9.p" to "フィックス作業中、下に人は立ってよいですか。",
    "q.l32#9.o0" to "だめ。作業者が上で作業している間、下は空けておく",
    "q.l32#9.o1" to "よい。道具を渡せる",
    "q.l32#9.o2" to "ヘルメットを被っていればよい",
    "q.l32#9.o3" to "ふざけなければよい",
    "q.l32#9.e" to "落石はフィックス作業で最も主要な傷害源です。下に人を置くのは、最も危険な位置を同行者に与えることです。",
    "q.l32#10.p" to "フィックスの計画段階で決めておくべき四つはどれですか。",
    "q.l32#10.o0" to "各区間の起点と終点、リレイと撤退点、ロープの長さ、固定方法",
    "q.l32#10.o1" to "色、ブランド、価格、重量",
    "q.l32#10.o2" to "誰が先に登るか、誰が写真を撮るか、誰が湯を沸かすか、誰が会計か",
    "q.l32#10.o3" to "天候、気分、予算、休暇",
    "q.l32#10.e" to "この四つが、その日のフィックスを安全に撤退できるかどうかを決めます。計画を飛ばしていきなりロープを出すのは、撤退案を運に任せるのと同じです。",
    "q.l32#11.p" to "固定ロープに「定期点検と記録」が必要なのはなぜですか。",
    "q.l32#11.o0" to "フィックスのルートはシーズン中使い続けられ、日射・摩耗・凍結融解で状態が変わるから",
    "q.l32#11.o1" to "監査のため",
    "q.l32#11.o2" to "責任を分担するため",
    "q.l32#11.o3" to "必要ない",
    "q.l32#11.e" to "ロープの皮膜の毛羽立ち、硬化、局所的な扁平は退役のサインです。記録がなければ、そのロープが何日ぶら下がっていたかを誰も説明できません。",
    "q.l32#12.p" to "支点の五項目チェックに含まれるものはどれですか。",
    "q.l32#12.o0" to "独立",
    "q.l32#12.o1" to "均等化",
    "q.l32#12.o2" to "方向",
    "q.l32#12.o3" to "鋭い縁の保護",
    "q.l32#12.e" to "五つ目は「バックアップ」です。五つの中で最も見落としやすいのが鋭い縁で、岩角で傷ついたスリングは強度がごく一部しか残らないことがあります。",
    "q.l32#13.p" to "固定ロープが退役すべき状態はどれですか。",
    "q.l32#13.o0" to "皮膜が毛羽立ち、芯が触れてしまう",
    "q.l32#13.o1" to "ロープが硬くなり、手触りが脆い",
    "q.l32#13.o2" to "局所が押しつぶされて変形している",
    "q.l32#13.o3" to "色があせた",
    "q.l32#13.e" to "前三者は構造的な損傷です。色あせは外観にすぎませんが、紫外線による劣化との相関には注意します。",
    "q.l32#14.p" to "フィックス作業での自己保護の要件はどれですか。",
    "q.l32#14.o0" to "どんなときも接続点を二つ以上持つ",
    "q.l32#14.o1" to "ヘルメットを被る",
    "q.l32#14.o2" to "上方に監視を置き、落石を防ぐ",
    "q.l32#14.o3" to "ロープバッグで余ったロープを管理する",
    "q.l32#14.e" to "四つで「作業面の安全」が構成されます。うち「接続点二つ」だけが絶対の原則で、例外はロープに直接結んでリードする場合だけです。",
    "q.l32#15.p" to "固定ロープシステムの冗長性は、どの層に表れますか。",
    "q.l32#15.o0" to "支点の冗長性（独立した二点）",
    "q.l32#15.o1" to "接続の冗長性（PAS／スリングのバックアップ）",
    "q.l32#15.o2" to "器具の冗長性（バックアップの摩擦結び）",
    "q.l32#15.o3" to "色の冗長性（色を何種類も買う）",
    "q.l32#15.e" to "三層の冗長性は「システムが失效しない、移行が途切れない、器具が単独で荷重を受けない」にそれぞれ対応します。色は安全と関係ありません。",
    "q.l32#16.p" to "1 区間の固定ロープを設置する順序を正しく並べてください。",
    "q.l32#16.o0" to "起点と終点、リレイの位置を決め、ロープの長さを見積もる",
    "q.l32#16.o1" to "支点を構築する（独立・均等化・バックアップ）",
    "q.l32#16.o2" to "ロープを這わせ、中間のリレイを設ける",
    "q.l32#16.o3" to "端に結び目を入れ、ロープの状態を記録する",
    "q.l32#16.e" to "ロープの長さは結び目と接続の余裕を見込み、短くならぬよう長めに取ります。末端の結び目は最後ですが、決して省けません。",
    "q.l32#17.p" to "支点の一つに疑わしい点があると分かったとき、正しい処置の順序はどれですか。",
    "q.l32#17.o0" to "その区間の使用を止め、人を安全な位置に移す",
    "q.l32#17.o1" to "独立したバックアップの支点を追加する",
    "q.l32#17.o2" to "荷重をかけ直して均等化する",
    "q.l32#17.o3" to "点検・記録したうえで、続行するか決める",
    "q.l32#17.e" to "まず人を安全な位置に移し、その後に技術的な処置を考えます。順序を逆にすると、処置そのものが事故現場になります。",
    "q.l32#18.p" to "固定ロープを長期運用する日常の流れとして正しいのはどれですか。",
    "q.l32#18.o0" to "出発前に支点とロープの状態を点検する",
    "q.l32#18.o1" to "通過時に接続が二つあることを確認する",
    "q.l32#18.o2" to "撤収時に摩耗と末端の結び目を確認する",
    "q.l32#18.o3" to "点検日と問題を記録する",
    "q.l32#18.e" to "この流れの価値は「点検を習慣にすること」にあります。シーズン中使う固定ロープを記憶で管理すれば、いつか必ず漏れます。",
    "q.l32#19.p" to "ダイナミックロープの規格番号は EN ______ です。",
    "q.l32#19.a0" to "892",
    "q.l32#19.e" to "ダイナミックロープは EN 892 / UIAA 101、スタティックロープは EN 1891 / UIAA 110。購入と点検では規格番号で照合します。",
    "q.l32#20.p" to "固定ロープには ______ ロープを選びます（「ダイナミック」か「スタティック」で）。",
    "q.l32#20.a0" to "スタティック",
    "q.l32#20.a1" to "スタティックロープ",
    "q.l32#20.e" to "スタティックロープは低伸度で耐摩耗性があり、長期間の固定に向きます。ダイナミックロープは伸びるため、固定ロープとして使うと上下に跳ね続けます。",
    "q.l32#21.p" to "フィックスでは、ロープの端を必ず ______、端が器具から抜けないようにします。",
    "q.l32#21.a0" to "結ぶ",
    "q.l32#21.a1" to "結び目を入れる",
    "q.l32#21.e" to "最も省かれやすい手順であり、結果が最も直接的な手順でもあります。",
    "q.l32#22.p" to "遠征のフィックスでよく使うスタティックロープの直径は ______〜11 mm です。",
    "q.l32#22.a0" to "9",
    "q.l32#22.e" to "9〜11 mm は耐摩耗性と重量のバランスが取れた範囲です。9 mm 未満は摩耗が速く、11 mm を超えると負担が明らかに増えます。",
    "q.l32#23.p" to "固定ロープの種類と、その典型的な場面を対応させてください。",
    "q.l32#23.l0" to "手すりロープ",
    "q.l32#23.l1" to "短区間の固定ロープ",
    "q.l32#23.l2" to "遠征のフィックス",
    "q.l32#23.l3" to "中間のリレイ",
    "q.l32#23.r0" to "短い露出区間を、手すりに掴まるように通過する",
    "q.l32#23.r1" to "急な斜面や 1 ピッチを、何度も上下する",
    "q.l32#23.r2" to "長いルート、複数ピッチ、荷物あり、シーズン中の使用",
    "q.l32#23.r3" to "長いロープを分割し、折れ角と摩耗を減らす",
    "q.l32#23.e" to "場面が基準を決めます。長期・荷物あり・露出が大きいほど、支点の冗長性とロープ状態の記録への要求が高くなります。",
    "q.l32#24.p" to "器材とその規格番号を対応させてください。",
    "q.l32#24.l0" to "スタティックロープ",
    "q.l32#24.l1" to "ダイナミックロープ",
    "q.l32#24.l2" to "アッセンダー",
    "q.l32#24.l3" to "ハーネス",
    "q.l32#24.r0" to "EN 1891 / UIAA 110",
    "q.l32#24.r1" to "EN 892 / UIAA 101",
    "q.l32#24.r2" to "EN 567",
    "q.l32#24.r3" to "EN 12277",
    "q.l32#24.e" to "規格番号は購入と点検の根拠であり、「この器材がもともとどの荷重のために設計されたか」を判断する材料でもあります。",
    "q.l32#25.p" to "支点の問題と、その結果を対応させてください。",
    "q.l32#25.l0" to "直列失效",
    "q.l32#25.l1" to "荷重方向が一方向だけ",
    "q.l32#25.l2" to "鋭い縁の保護なし",
    "q.l32#25.l3" to "単点でバックアップなし",
    "q.l32#25.r0" to "一つの支点が外れるとシステム全体が緩み、荷重が急変する",
    "q.l32#25.r1" to "横向きの荷重で支点が抜ける、または破断する",
    "q.l32#25.r2" to "スリングが切傷を受け、強度が大きく落ちる",
    "q.l32#25.r3" to "唯一の接続が失效すれば保護を完全に失う",
    "q.l32#25.e" to "四つの問題は四つの失效の仕方に対応します。しかも同時に存在することが多いので、点検は「見た目でよさそう」ではなく項目ごとに確認します。",
    "q.l32#26.p" to "同行者が「このロープはまだ 1 シーズンしか使っていないから点検不要」と言いました。最も妥当な返答はどれですか。",
    "q.l32#26.o0" to "固定ロープの損耗は露出と摩耗で決まり、シーズンの長短では決まらない",
    "q.l32#26.o1" to "確かに点検は不要",
    "q.l32#26.o2" to "色を変えればよい",
    "q.l32#26.o3" to "切れていなければ使える",
    "q.l32#26.e" to "日射、凍結融解、岩角との摩擦が損傷を積み重ねます。固定ロープの点検周期は使用の強度で決まり、カレンダーでは決まりません。",
    "q.l32#27.p" to "フィックスでロープの長さを見積もる原則はどれですか。",
    "q.l32#27.o0" to "結び目と接続の余裕を見込み、短くならぬよう長めに取る",
    "q.l32#27.o1" to "区間の長さとちょうど同じにする",
    "q.l32#27.o2" to "短くて軽いほどよい",
    "q.l32#27.o3" to "地図の直線距離で計算する",
    "q.l32#27.e" to "短ければ区間ごと無駄になり、長ければ少し重いだけです。結び目、接続、リレイはいずれも長さを食うので、見積もりに必ず入れます。",
    "q.l32#28.p" to "同行者が横振れのある固定ロープ区間を通過します。最も確認すべきことは何ですか。",
    "q.l32#28.o0" to "支点が横向きの荷重に耐えられるか、そして二つ目の接続点があるか",
    "q.l32#28.o1" to "ロープの色",
    "q.l32#28.o2" to "ロープの長さ",
    "q.l32#28.o3" to "本人の体重",
    "q.l32#28.e" to "横振れは「下向き」の支点を「横向き」の荷重に変えます。多くの支点はまさにこうして抜かれます。",
    "q.l32#29.p" to "固定ロープのルートに「撤退点」を設けるのはなぜですか。",
    "q.l32#29.o0" to "天候や人の状態が変わったとき、1 区間のうちに安全に抜けられるようにするため",
    "q.l32#29.o1" to "休むため",
    "q.l32#29.o2" to "装備を置くため",
    "q.l32#29.o3" to "写真を撮るため",
    "q.l32#29.e" to "長いルートを毎回最後まで行くことはできません。撤退点が「状況が悪化したとき、まだ選択肢があるかどうか」を決めます。",
    "q.l33#0.p" to "固定ロープを登るときの標準装備に含まれないものはどれですか。",
    "q.l33#0.o0" to "下降器（エイト環やチューブ型）",
    "q.l33#0.o1" to "ハンドル付きアッセンダー",
    "q.l33#0.o2" to "フットループ",
    "q.l33#0.o3" to "バックアップの摩擦結び",
    "q.l33#0.e" to "登攀の段階では下降器は不要で、切り替えと下降の場面で使います。装備の一覧は「いまの動作」で決めるもので、全部をぶら下げるのではありません。",
    "q.l33#1.p" to "登攀動作の合言葉はどれですか。",
    "q.l33#1.o0" to "立ち上がる、座る、押す",
    "q.l33#1.o1" to "引く、突っ張る、跳ぶ",
    "q.l33#1.o2" to "しゃがむ、跳ぶ、掴む",
    "q.l33#1.o3" to "押す、引く、座る",
    "q.l33#1.e" to "両足をフットループに掛けて立ち上がる→重心が上がる→チェストを押す→座る→ハンドルを押す。リズムが合えば体力の消費が半分になります。",
    "q.l33#2.p" to "登攀中の重心はどうあるべきですか。",
    "q.l33#2.o0" to "ロープに沿わせる",
    "q.l33#2.o1" to "できるだけ外へ",
    "q.l33#2.o2" to "左右に振る",
    "q.l33#2.o3" to "できるだけ後ろへ反る",
    "q.l33#2.e" to "重心が外へ振れるとアッセンダーに横向きの力がかかって外れやすく、体力の消耗も大きく増えます。ロープに沿わせるのは安全でもあり効率でもあります。",
    "q.l33#3.p" to "「二点接続」の原則の例外は何ですか。",
    "q.l33#3.o0" to "ロープに直接結んでリードする場合",
    "q.l33#3.o1" to "天気がよいとき",
    "q.l33#3.o2" to "日中",
    "q.l33#3.o3" to "短い距離のとき",
    "q.l33#3.e" to "リードでは本人がシステムの一部になるため、二つ目の点を掛けられません。それ以外では、どんなときも独立した接続を二つ持ちます。",
    "q.l33#4.p" to "結び目を越えるときの第一原則はどれですか。",
    "q.l33#4.o0" to "先に新しい接続を作り、その後に古い接続を外す",
    "q.l33#4.o1" to "先に古い接続を外し、その後に新しい接続を作る",
    "q.l33#4.o2" to "二つを同時に操作する",
    "q.l33#4.o3" to "結び目を飛ばす",
    "q.l33#4.e" to "順序を誤ると「一点だけ」あるいは「接続なし」の瞬間が生じます。結び目を越えるとは、制御されたシステムの移行のことです。",
    "q.l33#5.p" to "結び目を越える途中で、二つのアッセンダーが同時にロープから外れてよいですか。",
    "q.l33#5.o0" to "だめ。どの瞬間にも少なくとも一つがロープに掛かり荷重を受けている",
    "q.l33#5.o1" to "よい。動作が速ければ",
    "q.l33#5.o2" to "よい。誰かが見ていれば",
    "q.l33#5.o3" to "よい。短い結び目なら",
    "q.l33#5.e" to "二つ同時に外れれば、上方向の接続をすべて失います。1 分多くかけて組み直すほうが、一回の賭けより安いのです。",
    "q.l33#6.p" to "登攀から下降へ切り替える最初の一歩は何ですか。",
    "q.l33#6.o0" to "PAS かスリングで自分を支点に掛ける",
    "q.l33#6.o1" to "まずハンドル付きアッセンダーを外す",
    "q.l33#6.o2" to "まず下降器を付ける",
    "q.l33#6.o3" to "まずチェストを外す",
    "q.l33#6.e" to "まず登攀システムから独立した接続を得てから、古いシステムを外します。これがすべての切り替え動作に共通する出発点です。",
    "q.l33#7.p" to "下降器を付けた後、アッセンダーを外す前に必ず何をしますか。",
    "q.l33#7.o0" to "下降器に荷重をかけてテストする",
    "q.l33#7.o1" to "先にハーネスを外す",
    "q.l33#7.o2" to "先にロープを巻く",
    "q.l33#7.o3" to "先にヘルメットを脱ぐ",
    "q.l33#7.e" to "「荷重をかけてテストする」は、新しいシステムが本当に体重を支えられるかを確かめる唯一の方法です。この一手を飛ばして古いシステムを外すと、そのまま墜落します。",
    "q.l33#8.p" to "下降のとき、下降器の上に付ける摩擦結び（バックアップ）の役割は何ですか。",
    "q.l33#8.o0" to "手を離した瞬間に自動で噛み、独立したバックアップになる",
    "q.l33#8.o1" to "下降の速度を上げる",
    "q.l33#8.o2" to "ロープを保護する",
    "q.l33#8.o3" to "位置を示す",
    "q.l33#8.e" to "摩擦結びは制動手を緩めるとロープを噛みます。「手が離れる」という最も危険な瞬間の唯一の防線です。",
    "q.l33#9.p" to "下降の前にロープの端へ結び目を入れる目的は何ですか。",
    "q.l33#9.o0" to "端が下降器から抜けるのを防ぐ",
    "q.l33#9.o1" to "回収しやすくする",
    "q.l33#9.o2" to "ロープの長さを示す",
    "q.l33#9.o3" to "摩耗を減らす",
    "q.l33#9.e" to "ロープが足りないとき、端が抜ければ制動を一瞬で失います。末端の結び目は下降前の必須チェック項目です。",
    "q.l33#10.p" to "中間のリレイを通過するとき、正しい順序はどれですか。",
    "q.l33#10.o0" to "先にリレイの支点へ掛け、その後にアッセンダーを移し、最後に支点の接続を外す",
    "q.l33#10.o1" to "先にアッセンダーを移し、その後に支点へ掛ける",
    "q.l33#10.o2" to "掛けずにそのまま通過する",
    "q.l33#10.o3" to "先に支点を外し、その後に移る",
    "q.l33#10.e" to "リレイではロープがカラビナに拘束され、作業空間が狭く動作が崩れやすいです。先に独立した接続を作ってこそ、やり直しの余地が生まれます。",
    "q.l33#11.p" to "ロープが噛んだときはどう対処すべきですか。",
    "q.l33#11.o0" to "引く角度を変えるか横から引く。ロープの真下に立って力任せに引かない",
    "q.l33#11.o1" to "真下に立って強く引く",
    "q.l33#11.o2" to "体重をかけて思い切り引く",
    "q.l33#11.o3" to "そのまま切る",
    "q.l33#11.e" to "真下で強く引くと、跳ね返るロープや落石に当たることがあり、結び目がさらに噛み込むこともあります。角度を変えるのが最も有効な第一手です。",
    "q.l33#12.p" to "二本のロープを引き抜いて回収するとき、どちら側を引くべきですか。",
    "q.l33#12.o0" to "摩擦の小さい側",
    "q.l33#12.o1" to "摩擦の大きい側",
    "q.l33#12.o2" to "どちらでもよい",
    "q.l33#12.o3" to "両側を同時に",
    "q.l33#12.e" to "摩擦の小さい側のほうが抜きやすく、皮膜の摩耗も減ります。ただし端に結び目があり、引っかかりがないことが前提です。",
    "q.l33#13.p" to "固定ロープを登るとき、必ず携行する装備はどれですか。",
    "q.l33#13.o0" to "ハンドル付きとチェストのアッセンダー（または二つ目の摩擦結び）",
    "q.l33#13.o1" to "フットループ",
    "q.l33#13.o2" to "バックアップの摩擦結びと PAS",
    "q.l33#13.o3" to "ヘルメット",
    "q.l33#13.e" to "四つで登攀とバックアップのシステムが完成します。一つ欠けると、結び目越えや切り替えで「単点作業」を強いられます。",
    "q.l33#14.p" to "切り替えの場面で最も多い誤りはどれですか。",
    "q.l33#14.o0" to "先に古いシステムを外し、その後に新しいシステムを組む",
    "q.l33#14.o1" to "下降器に荷重をかけずにアッセンダーを外す",
    "q.l33#14.o2" to "二つのアッセンダーを同時に外す",
    "q.l33#14.o3" to "切り替えの前に支点へ掛ける",
    "q.l33#14.e" to "前三者はすべて「順序の誤り」です。最後の一つはむしろ正しいやり方で、前三者を避けるために先に支点へ掛けます。",
    "q.l33#15.p" to "下降の前に必ず終えるべき点検はどれですか。",
    "q.l33#15.o0" to "下降器のロープの通し方向が正しい",
    "q.l33#15.o1" to "バックアップの摩擦結びが付いていて有効",
    "q.l33#15.o2" to "ロープの端に結び目がある",
    "q.l33#15.o3" to "ロープが次の支点まで届く長さがある",
    "q.l33#15.e" to "四つのどれが欠けても制御を失う可能性があります。この点検は「保護を解除する前」にすべて終えます。",
    "q.l33#16.p" to "結び目を越えるとき、「新しい接続」として使える手段はどれですか。",
    "q.l33#16.o0" to "PAS かスリングを結び目の上に掛ける",
    "q.l33#16.o1" to "近くの支点に掛ける",
    "q.l33#16.o2" to "上に二つ目のアッセンダーを付ける",
    "q.l33#16.o3" to "手でロープを掴む",
    "q.l33#16.e" to "手で掴むのは接続ではなく、手を離せば終わりです。前の三つはいずれも「古いシステムから独立した」荷重点を作れます。",
    "q.l33#17.p" to "「登攀で結び目を越える」五つの手順を正しく並べてください。",
    "q.l33#17.o0" to "結び目に近づいたら速度を落とし、結び目の位置と上のロープを観察する",
    "q.l33#17.o1" to "PAS かスリングで、結び目の上か近くの支点に自分を接続する",
    "q.l33#17.o2" to "上に二つ目のアッセンダーか摩擦結びを付け、立ち上がって体重を移す",
    "q.l33#17.o3" to "下のアッセンダーを外し、結び目の上に付け直す",
    "q.l33#17.o4" to "新しい接続が荷重を受けているのを確認してから、PAS のバックアップを解除する",
    "q.l33#17.e" to "五つの核は「常に一つ多い点を持つ」ことです。どれか一つを飛ばすと、単点しか受けてない、あるいは接続のない空白が生じます。",
    "q.l33#18.p" to "「登攀から下降へ」の順序を並べてください。",
    "q.l33#18.o0" to "支点に掛ける（PAS かスリング）",
    "q.l33#18.o1" to "下降器を付け、ロープを正しく通す",
    "q.l33#18.o2" to "下降器に荷重をかけてテストする",
    "q.l33#18.o3" to "ハンドル付きアッセンダーを外し、チェストかバックアップの摩擦結びは残す",
    "q.l33#18.o4" to "もう一つのアッセンダーを外し、下降器とバックアップが正常か確認する",
    "q.l33#18.o5" to "PAS を解除して下降を始める",
    "q.l33#18.e" to "順序は固定で、その場での変更は許されません。どの段階でも「信頼できる接続が少なくとも一つ」を保ちます。",
    "q.l33#19.p" to "「下降から登攀へ」の順序を並べてください。",
    "q.l33#19.o0" to "下降器の上に摩擦結びかアッセンダーを付け、ハーネスに接続する",
    "q.l33#19.o1" to "立ち上がって、体重を摩擦結びへ移す",
    "q.l33#19.o2" to "二つ目のアッセンダーかフットループを付け、荷重を確認する",
    "q.l33#19.o3" to "下降器を外す",
    "q.l33#19.o4" to "登攀を始める",
    "q.l33#19.e" to "鍵は三番目です。新しいシステムがすでに荷重を受けていると確認できて初めて、下降器を外せます。",
    "q.l33#20.p" to "「結び目を越えて下降する」三つの手順を並べてください。",
    "q.l33#20.o0" to "結び目の上で PAS を結び目か支点に掛け、バックアップを作る",
    "q.l33#20.o1" to "下降器を結び目の下へ移し、張って荷重をテストする",
    "q.l33#20.o2" to "PAS を解除し、下降を続ける",
    "q.l33#20.e" to "太い結び目をそのまま通せないときは、まずバックアップの摩擦結びを結び目の下へ移し、次に下降器を移します。二回の移行の間、常に信頼できる接続を一つ保ちます。",
    "q.l33#21.p" to "固定ロープを登るときは、どんなときも ______ つの独立した接続点を保ちます。",
    "q.l33#21.a0" to "2",
    "q.l33#21.a1" to "二",
    "q.l33#21.e" to "二点接続は固定ロープ作業の絶対の原則です。唯一の例外はロープに直接結んでリードする場合です。",
    "q.l33#22.p" to "登攀から下降へ移るときは、アッセンダーを外す前に必ず ______ に掛けます。",
    "q.l33#22.a0" to "支点",
    "q.l33#22.a1" to "ビレイステーション",
    "q.l33#22.a2" to "リレイ",
    "q.l33#22.e" to "古いシステムに依存しない接続を先に得ることが、すべての切り替え動作の出発点です。",
    "q.l33#23.p" to "下降器の上に付けるバックアップの摩擦結びは、プルージックか ______ が一般的です。",
    "q.l33#23.a0" to "オートブロック",
    "q.l33#23.a1" to "フレンチプルージック",
    "q.l33#23.a2" to "摩擦結び",
    "q.l33#23.e" to "どちらも「手を離せば噛む」バックアップです。向きや長さが違うと効かないので、目を閉じても確認できるまで練習します。",
    "q.l33#24.p" to "操作の場面と、その鍵となる原則を対応させてください。",
    "q.l33#24.l0" to "結び目を越える",
    "q.l33#24.l1" to "リレイを通過する",
    "q.l33#24.l2" to "登攀から下降へ",
    "q.l33#24.l3" to "下降から登攀へ",
    "q.l33#24.r0" to "先に新しい接続を作り、その後に古い接続を外す",
    "q.l33#24.r1" to "先に支点へ掛け、その後に器具を移す",
    "q.l33#24.r2" to "支点へ掛ける → 下降器を付ける → テスト → アッセンダーを外す",
    "q.l33#24.r3" to "新しいシステムが荷重を受けてから、下降器を外す",
    "q.l33#24.e" to "四つの場面に共通する構造は「作る → 移す → 外す」です。手順より構造を覚えるほうが忘れにくいのです。",
    "q.l33#25.p" to "チェックリスト ABCDE とその内容を対応させてください。",
    "q.l33#25.l0" to "A アンカー",
    "q.l33#25.l1" to "B バックアップ",
    "q.l33#25.l2" to "C コネクション",
    "q.l33#25.l3" to "E エスケープ",
    "q.l33#25.r0" to "独立した二点、均等化、荷重方向が正しい、鋭い縁の保護",
    "q.l33#25.r1" to "PAS か摩擦結びが入り、器具それぞれに独立したバックアップ",
    "q.l33#25.r2" to "カラビナのゲートが閉じ、結び目が締まり、ロープの端に結び目",
    "q.l33#25.r3" to "最寄りの撤退点を知り、ロープが足り、連絡手段が明確",
    "q.l33#25.e" to "このチェックリストの価値は「ロープを出す前に毎回通す」ことにあります。判断の代わりにはなりませんが、初歩的な誤りの大半は止められます。",
    "q.l33#26.p" to "同行者が結び目越えで「一つ目のアッセンダーを外して、二つ目をすぐ付ける」と言っています。どう伝えますか。",
    "q.l33#26.o0" to "先に PAS か支点への接続を作る必要がある。接続のない空白は認められない",
    "q.l33#26.o1" to "動作が速ければ大丈夫",
    "q.l33#26.o2" to "日中なら大丈夫",
    "q.l33#26.o3" to "短い結び目なら大丈夫",
    "q.l33#26.e" to "「すぐ」は、手を滑らせた瞬間にはゼロの許容度です。結び目越えの余裕は、三つ目の接続で作るしかありません。",
    "q.l33#27.p" to "リレイでロープをカラビナから一度出して入れ直す必要があります。正しいやり方はどれですか。",
    "q.l33#27.o0" to "先に支点へ掛け、その後にロープを操作し、最後にバックアップを解除する",
    "q.l33#27.o1" to "先にロープを出し、その後に支点へ掛ける",
    "q.l33#27.o2" to "誰かにロープを持ってもらう",
    "q.l33#27.o3" to "カラビナを直接開ける",
    "q.l33#27.e" to "ロープを出す瞬間、人は古い接続だけに完全に依存する可能性があります。独立した接続を先に作ってこそ、その操作に意味が生まれます。",
    "q.l33#28.p" to "システムの切り替えが固定ロープ操作で最も事故が多い場面と呼ばれるのはなぜですか。",
    "q.l33#28.o0" to "古いシステムを外すことと新しいシステムを組むことの間で体重を移すため、許容度が最も小さいから",
    "q.l33#28.o1" to "器具が多いから",
    "q.l33#28.o2" to "とても疲れるから",
    "q.l33#28.o3" to "2 人が必要だから",
    "q.l33#28.e" to "結び目越えは「点を一つ足す」だけですが、切り替えは「システムごと入れ替える」ことです。順序を一つ誤れば、そのまま接続を失います。",
    "q.l34#0.p" to "氷河でも最も危険で、最も過小評価されやすい地形はどれですか。",
    "q.l34#0.o0" to "雪に覆われたクレバスと雪橋",
    "q.l34#0.o1" to "モレーンの丘",
    "q.l34#0.o2" to "平らな雪原",
    "q.l34#0.o3" to "氷河両側のガレ場",
    "q.l34#0.e" to "クレバスが新雪で覆われると、普通の雪面と見分けがつきません。氷河の事故ではクレバスへの墜落が最も大きな割合を占めます。",
    "q.l34#1.p" to "横断方向のクレバスは、どこに現れやすいですか。",
    "q.l34#1.o0" to "傾斜が変わる場所（斜面の上端、下端、氷の段を越えるところ）",
    "q.l34#1.o1" to "氷河の真ん中",
    "q.l34#1.o2" to "氷河の末端",
    "q.l34#1.o3" to "モレーンの上",
    "q.l34#1.e" to "傾斜が急に変わるところは伸張か圧縮が起き、そこにクレバスが開きます。登り始める前に斜面の上端付近を観察するのが、最も実用的な習慣です。",
    "q.l34#2.p" to "氷河の両側によく見られる縦方向のクレバスの成因はどれですか。",
    "q.l34#2.o0" to "氷河が流れるとき、両側が地形と摩擦して生じる伸張",
    "q.l34#2.o1" to "落石が穿ったもの",
    "q.l34#2.o2" to "登山者が踏んでできたもの",
    "q.l34#2.o3" to "融水が削ったもの",
    "q.l34#2.e" to "中央は流れが速く両側は遅いため、速度差がせん断と伸張を生みます。だから氷河の中央線を歩くほうが、縁に沿うより安全なのが普通です。",
    "q.l34#3.p" to "ロープ結び行進でのロープ間隔は通常どれくらいですか。",
    "q.l34#3.o0" to "8〜10 m",
    "q.l34#3.o1" to "2〜3 m",
    "q.l34#3.o2" to "20〜30 m",
    "q.l34#3.o3" to "近ければ近いほどよい",
    "q.l34#3.e" to "間隔が短すぎると、一人が落ちたときに同行者もそのまま引き込まれます。長すぎると制動距離も救助の難しさも増します。クレバス密集帯では詰めますが、6〜8 m を下回らないようにします。",
    "q.l34#4.p" to "結び行進でロープに結び目を入れるのはなぜですか。",
    "q.l34#4.o0" to "落ち込む深さを抑え、制動の摩擦を増し、救助時に掴みやすくする",
    "q.l34#4.o1" to "ロープのよじれを防ぐ",
    "q.l34#4.o2" to "長さを示す",
    "q.l34#4.o3" to "見た目のため",
    "q.l34#4.e" to "結び目はクレバスの口で余分な抵抗と引っかかりを作り、落ち込む深さを明らかに減らします。代わりにロープの繰り出しがやや面倒になりますが、その価値はあります。",
    "q.l34#5.p" to "三人結びが二人結びより優れている主な点はどれですか。",
    "q.l34#5.o0" to "一人が落ちたとき二人で制動し、一人が救助システムを準備できる。余裕が大きい",
    "q.l34#5.o1" to "歩くのが速い",
    "q.l34#5.o2" to "ロープが軽い",
    "q.l34#5.o3" to "結び目が不要",
    "q.l34#5.e" to "二人結びでは、制動している人はほぼ救助システムを操作できません。三人結びだからこそ「制動＋システム構築」の分担が生まれます。",
    "q.l34#6.p" to "雪橋が信頼できるか判断するとき、最初に見るべきはどれですか。",
    "q.l34#6.o0" to "色と凹み。暗い、青い、放射状の亀裂があると薄い",
    "q.l34#6.o1" to "足跡の数",
    "q.l34#6.o2" to "表面が平らかどうか",
    "q.l34#6.o3" to "風があるかどうか",
    "q.l34#6.e" to "雪橋の強度は跨度と雪層の厚さで決まります。色と凹みが最も直接的な手がかりで、足跡は「他の人も通った」ことしか示しません。",
    "q.l34#7.p" to "クレバス密集帯を越えるのに最も適した時間帯はどれですか。",
    "q.l34#7.o0" to "早朝、または夜間の低温の時間帯",
    "q.l34#7.o1" to "正午",
    "q.l34#7.o2" to "午後",
    "q.l34#7.o3" to "どの時間でも同じ",
    "q.l34#7.e" to "低温なら雪橋が最も強く、午後に雪が融けると強度は明らかに落ちます。行程はこの点を中心に、通過する時間を組み立てます。",
    "q.l34#8.p" to "アイスフォール帯（セラック帯）を通過する正しいやり方はどれですか。",
    "q.l34#8.o0" to "速やかに通過し、間隔を保ち、ヘルメットを被り、帯の中で立ち止まらない",
    "q.l34#8.o1" to "結んでゆっくり歩く",
    "q.l34#8.o2" to "帯の中で休む",
    "q.l34#8.o3" to "記念写真を撮る",
    "q.l34#8.e" to "アイスフォール帯の危険はセラックの崩落で、クレバスとは違います。落ちてくるのは塊です。滞在時間は短いほどよく、ここで結んで待つのも避けます。",
    "q.l34#9.p" to "氷河を歩くとき、ロープはどんな状態に保つべきですか。",
    "q.l34#9.o0" to "適度に張り、引きずらず、緩みすぎない",
    "q.l34#9.o1" to "完全に緩めて雪面を引きずる",
    "q.l34#9.o2" to "ぴんと張る",
    "q.l34#9.o3" to "巻いて手に持つ",
    "q.l34#9.e" to "緩んだロープは墜落の瞬間に衝撃荷重を生み、張りすぎたロープは互いに引っ張り合います。適度な張り＋結び目の組み合わせが最も安定します。",
    "q.l34#10.p" to "明瞭なクレバスに行き当たったとき、最優先の対応はどれですか。",
    "q.l34#10.o0" to "迂回し、より狭い場所か架橋されている場所を探して通過する",
    "q.l34#10.o1" to "そのまま跳び越える",
    "q.l34#10.o2" to "縁に立って深さを観察する",
    "q.l34#10.o3" to "ピッケルで広げる",
    "q.l34#10.e" to "氷河のルート選びの第一原則は「迂回」です。跳び越えることと縁に立って観察することが、最もよくある自傷の二パターンです。",
    "q.l34#11.p" to "「氷河の中央線を歩くほうが安全」と言われるのはなぜですか。",
    "q.l34#11.o0" to "両側の伸張帯はクレバスが多く、中央は荷重が比較的均一だから",
    "q.l34#11.o1" to "中央のほうが雪が厚いから",
    "q.l34#11.o2" to "中央のほうが短いから",
    "q.l34#11.o3" to "中央のほうが人が多いから",
    "q.l34#11.e" to "中央はクレバスが少なく、雪橋の跨度も小さいのが普通です。ただしアイスフォール帯や氷の段では別に判断します。機械的に当てはめてはいけません。",
    "q.l34#12.p" to "氷河ルートのリスク評価では何を考えるべきですか。",
    "q.l34#12.o0" to "クレバスの密度と雪橋の状態",
    "q.l34#12.o1" to "セラックと落氷のリスク",
    "q.l34#12.o2" to "その日の気温と日射（雪橋の強度に影響する）",
    "q.l34#12.o3" to "人数と結び方",
    "q.l34#12.e" to "四つは互いに影響します。温度が雪橋を決め、人数が結び方を決め、結び方が墜落の結果を決めます。リスク評価はこれらをまとめて見ることです。",
    "q.l34#13.p" to "雪橋が怪しいと分かる兆候はどれですか。",
    "q.l34#13.o0" to "橋面が明らかに凹んでいる",
    "q.l34#13.o1" to "色が暗い、青い",
    "q.l34#13.o2" to "橋の端に放射状の亀裂がある",
    "q.l34#13.o3" to "新雪に覆われているが、下に空洞の反響がある",
    "q.l34#13.e" to "四つとも「強度不足」の異なる現れです。空洞の反響が聞こえたら、もう一歩踏み出すのではなく、戻るべきです。",
    "q.l34#14.p" to "氷河の上でリスクを高める行動はどれですか。",
    "q.l34#14.o0" to "結び間隔が近すぎる",
    "q.l34#14.o1" to "ロープに結び目を入れない",
    "q.l34#14.o2" to "アイスフォール帯で立ち止まって休む",
    "q.l34#14.o3" to "氷河の縁に沿って歩く",
    "q.l34#14.e" to "四つはそれぞれ「連鎖墜落、深い埋没、落氷、側方のクレバス」のリスクを上げます。いずれも避けられる選択です。",
    "q.l34#15.p" to "クレバス密集帯に入る前に、隊で統一しておくべきことはどれですか。",
    "q.l34#15.o0" to "ロープ間隔と結び目の入れ方",
    "q.l34#15.o1" to "通過順序と間隔",
    "q.l34#15.o2" to "雪橋に出会ったときの原則（探る・迂回する・戻る）",
    "q.l34#15.o3" to "誰の荷物が最も重いか",
    "q.l34#15.e" to "前三者が「状況が出たときに全員がどう動くか」を決めます。事前に統一しておくほうが、クレバスの縁で相談するよりはるかに安全です。",
    "q.l34#16.p" to "怪しい雪橋を通過する流れを、正しい順序に並べてください。",
    "q.l34#16.o0" to "立ち止まり、色・凹み・周囲の亀裂を観察する",
    "q.l34#16.o1" to "ピッケルかプローブで橋面の厚さを探る",
    "q.l34#16.o2" to "迂回できないと確認してから、間隔を詰めて 1 人ずつ通過する",
    "q.l34#16.o3" to "全員が通過した後、最後の人が保護を解除して追いつく",
    "q.l34#16.e" to "探るのは人が乗る前でなければなりません。1 人ずつ通過するのは「一度に一人分の体重しか預けない」という意味で、これが最も重要な段取りです。",
    "q.l34#17.p" to "氷河の行程を組むとき、正しい順序はどれですか。",
    "q.l34#17.o0" to "まずルート図とクレバスの分布を見る",
    "q.l34#17.o1" to "クレバス帯を通過する時間帯（早朝／夜間）を決める",
    "q.l34#17.o2" to "結び方とロープ間隔を決める",
    "q.l34#17.o3" to "出発前に天候と気温をもう一度確認する",
    "q.l34#17.e" to "地形、次に時間、次に編成、最後に天候の再確認。順序を逆にすると「計画どおり歩いたが時間帯を間違えた」ということが起きます。",
    "q.l34#18.p" to "同行者がクレバスに落ちたと気づいたとき、最初の三つの順序はどれですか。",
    "q.l34#18.o0" to "ただちに制動し、ロープに荷重をかけたまま保つ",
    "q.l34#18.o1" to "自分の位置が安全か確認し、確保を取る",
    "q.l34#18.o2" to "同行者に救助システムの準備を指示する",
    "q.l34#18.o3" to "結び行進の救助手順に沿って操作する",
    "q.l34#18.e" to "制動だけは待てません。その後に確保と救助システムです。詳しい手順は「自救与結組救援」の課にあります。",
    "q.l34#19.p" to "氷河の結び行進でよく使うロープ間隔は ______〜10 m です。",
    "q.l34#19.a0" to "8",
    "q.l34#19.e" to "8〜10 m が標準的な範囲です。クレバスが密集すれば詰めますが、「一人の墜落で全員が引き込まれる」ほど短くはしません。",
    "q.l34#20.p" to "雪橋の強度を判断するには、色と凹みのほかに、ピッケルで ______ べきです。",
    "q.l34#20.a0" to "探る",
    "q.l34#20.a1" to "突く",
    "q.l34#20.a2" to "試す",
    "q.l34#20.e" to "探るのは人が橋に乗る前です。ピッケルの先を軽く刺し、雪層の厚さと下に空洞がないかを感じ取ります。",
    "q.l34#21.p" to "クレバス密集帯を越えるのは ______（時間帯）が最適で、そのとき雪橋が最も強い。",
    "q.l34#21.a0" to "早朝",
    "q.l34#21.a1" to "朝",
    "q.l34#21.a2" to "未明",
    "q.l34#21.e" to "低温だと雪橋は硬く丈夫になります。午後に雪が融けると強度は明らかに落ちます。",
    "q.l34#22.p" to "クレバスの種類と、その典型的な位置を対応させてください。",
    "q.l34#22.l0" to "横断方向のクレバス",
    "q.l34#22.l1" to "縦方向のクレバス",
    "q.l34#22.l2" to "斜め方向のクレバス",
    "q.l34#22.l3" to "セラック／アイスフォール帯",
    "q.l34#22.r0" to "傾斜が変わるところ（上端、下端、氷の段）",
    "q.l34#22.r1" to "氷河の両側、地形との摩擦による伸張帯",
    "q.l34#22.r2" to "氷河が曲がるところ、幅が変わるところ",
    "q.l34#22.r3" to "急なアイスフォールの直下、落氷のリスクが高い",
    "q.l34#22.e" to "クレバスの成因は「伸張」です。これを覚えておけば、次の区間のどこが裂けるかを予測できます。",
    "q.l34#23.p" to "雪橋の兆候と、その対応を対応させてください。",
    "q.l34#23.l0" to "橋面が凹んでいる",
    "q.l34#23.l1" to "色が暗い、青い",
    "q.l34#23.l2" to "放射状の亀裂",
    "q.l34#23.l3" to "空洞の反響",
    "q.l34#23.r0" to "通過の優先度を下げ、まず迂回する",
    "q.l34#23.r1" to "雪層が薄いということ。単独で探ってはいけない",
    "q.l34#23.r2" to "構造がすでに損傷している。通過禁止",
    "q.l34#23.r3" to "ただちに戻り、ルートを変える",
    "q.l34#23.e" to "四つの兆候は深刻さが段階的に進みます。どれか一つでも出たら、まず「迂回」を考え、「急いで渡る」とは考えません。",
    "q.l34#24.p" to "役割と担当を対応させてください（三人結び）。",
    "q.l34#24.l0" to "先頭（リード／ルート判断）",
    "q.l34#24.l1" to "中央",
    "q.l34#24.l2" to "最後尾",
    "q.l34#24.r0" to "ルートと雪橋を判断し、ペースを管理する",
    "q.l34#24.r1" to "前後を兼ね、指示を伝える",
    "q.l34#24.r2" to "ロープを巻き取り、後方と末端の状態を見る",
    "q.l34#24.e" to "三人結びの分担は出発前に言っておきます。中央は「最も安全な位置」ではなく、情報を伝える要です。",
    "q.l34#25.p" to "同行者が「雪橋が丈夫か一脚踏んで試そう」と言っています。どう対応しますか。",
    "q.l34#25.o0" to "止めさせ、ピッケルかプローブで探るか、そのまま迂回する",
    "q.l34#25.o1" to "結んでいるから試させてよい",
    "q.l34#25.o2" to "一人だけ先に渡らせる",
    "q.l34#25.o3" to "走って荷重時間を短くする",
    "q.l34#25.e" to "人は数十キロの集中荷重で、一脚で踏み抜くことがあります。探るのは道具で行い、体重では行いません。",
    "q.l34#26.p" to "昼になって気温が上がり、予定のクレバス帯までまだ 2 時間あります。どうすべきですか。",
    "q.l34#26.o0" to "評価し直す。夕方の降温を待つか、代替ルートに変える",
    "q.l34#26.o1" to "計画どおり進む",
    "q.l34#26.o2" to "速度を上げて一気に抜ける",
    "q.l34#26.o3" to "その場で明日まで待つ",
    "q.l34#26.e" to "雪橋の強度は時間の関数です。計画は「最も強い時間帯」を中心に組み、人が計画に合わせるのではありません。",
    "q.l34#27.p" to "アイスフォール帯を結んで待つ場所に適さないのはなぜですか。",
    "q.l34#27.o0" to "セラックの崩落は塊で落ちてくるので、待つほど露出時間が延びるから",
    "q.l34#27.o1" to "風が強いから",
    "q.l34#27.o2" to "地面が平らでないから",
    "q.l34#27.o3" to "電波が届かないから",
    "q.l34#27.e" to "クレバスのリスクは結んで分担できますが、落氷のリスクは「露出時間を減らす」しかありません。二種類のリスクは対処の方向がまったく違います。",
    "q.l34#28.p" to "氷河を歩く速度とリズムについて、正しい説明はどれですか。",
    "q.l34#28.o0" to "安定した一定の速さでロープ間隔を保つほうが、速くなったり遅くなったりするより安全",
    "q.l34#28.o1" to "速ければ速いほど安全",
    "q.l34#28.o2" to "遅ければ遅いほど安全",
    "q.l34#28.o3" to "体力に合わせて各自が歩く",
    "q.l34#28.e" to "速さがむらになるとロープが緩んだり張ったりを繰り返し、衝撃が生まれます。氷河では「リズムを揃える」ことが安全でもあり効率でもあります。",
    "q.l34#29.p" to "初めて氷河に上がる人が、まず練習すべきことは何ですか。",
    "q.l34#29.o0" to "安全な場所で結び行進、ロープ間隔の感覚、制動姿勢を練習する",
    "q.l34#29.o1" to "速く走る練習",
    "q.l34#29.o2" to "一人でクレバスを通過する練習",
    "q.l34#29.o3" to "高所での作業の練習",
    "q.l34#29.e" to "制動姿勢とロープ間隔の感覚は、安全な地形で体に覚え込ませる必要があります。本当に落ちてからでは間に合いません。",
    "q.m13#14.p" to "摩擦結びで自主的に登る（プルージック登攀）とき、正しい順序はどれですか。",
    "q.m13#14.o0" to "立ち上がる（上の摩擦結びを押し上げる）→ 座る（体重を移す）→ 下の摩擦結びを押し上げる → 繰り返す",
    "q.m13#14.o1" to "二つの摩擦結びを同時に押し上げる",
    "q.m13#14.o2" to "上の摩擦結びだけを押し上げる",
    "q.m13#14.o3" to "腕で引っ張る",
    "q.m13#14.e" to "「立ち上がる—座る—押し上げる」の循環で、体重を上下の摩擦結びの間で移します。二つを同時に押し上げると、そのまま滑り落ちます。",
    "q.m13#15.p" to "自主登攀でのフットループの役割は何ですか。",
    "q.m13#15.o0" to "体重を脚に移し、腕の負担を減らす",
    "q.m13#15.o1" to "摩擦を増やす",
    "q.m13#15.o2" to "ハーネスに接続する",
    "q.m13#15.o3" to "高さを示す",
    "q.m13#15.e" to "腕だけで引くと、数十メートルで力尽きます。フットループで脚を参加させられるかどうかが、這い出せるかどうかの分かれ目です。",
    "q.m13#16.p" to "結び行進の救助で、最初にすべきことは何ですか。",
    "q.m13#16.o0" to "制動して固定し、落ちた人がそれ以上滑るのを防ぐ",
    "q.m13#16.o1" to "すぐクレバスの中へ降りる",
    "q.m13#16.o2" to "救助を要請する",
    "q.m13#16.o3" to "写真に記録する",
    "q.m13#16.e" to "制動だけは待てません。固定した後に、連絡、システム、引き上げを考えます。",
    "q.m13#17.p" to "落ちた人がクレバスの中で宙吊りになっているとき、最も警戒すべき傷害はどれですか。",
    "q.m13#17.o0" to "低体温、ロープによる圧迫、衝突による外傷",
    "q.m13#17.o1" to "日焼け",
    "q.m13#17.o2" to "高山病",
    "q.m13#17.o3" to "脱水",
    "q.m13#17.e" to "クレバス内は極端に低温で、宙吊りは血流も妨げます。救助は「速く」あることが求められ、単に引き上げればよいわけではありません。",
    "q.m13#18.p" to "救助のとき、まず落ちた人に「自己固定」を取らせるのはなぜですか。",
    "q.m13#18.o0" to "メインロープに頼らない状態にして、救助者が手を空けてシステムを組めるようにするため",
    "q.m13#18.o1" to "ロープを信用していないから",
    "q.m13#18.o2" to "規則だから",
    "q.m13#18.o3" to "装備がないから",
    "q.m13#18.e" to "自己固定（摩擦結びかピッケル）は位置を安定させ、落ちた人にもやることができてパニックが減ります。",
    "q.m13#19.p" to "要救助者が自分で動けないとき、クレバスから引き出す正しい方法はどれですか。",
    "q.m13#19.o0" to "3:1 か 5:1 のシステムを組み、上から引き上げる",
    "q.m13#19.o1" to "手で直接ロープを引く",
    "q.m13#19.o2" to "本人に登らせる",
    "q.m13#19.o3" to "ロープを腰に巻く",
    "q.m13#19.e" to "手で引くのはほぼ不可能で、しかも制御を失います。システム化した引き上げだけが確実な方法です。",
    "q.m13#20.p" to "救助の時間的な圧力はどこから来ますか。",
    "q.m13#20.o0" to "低体温の進行、天候の変化、隊の体力の消耗",
    "q.m13#20.o1" to "体力だけ",
    "q.m13#20.o2" to "天候だけ",
    "q.m13#20.o3" to "低体温だけ",
    "q.m13#20.e" to "三つが同時に働きます。救助の計画は「できるか」だけでなく「どれくらいで終わるか」を考えます。",
    "q.m13#21.p" to "救助中のコミュニケーションで、最も頼りにならない手段はどれですか。",
    "q.m13#21.o0" to "小さな雪の起伏を隔てて叫ぶ",
    "q.m13#21.o1" to "無線機",
    "q.m13#21.o2" to "ロープの合図",
    "q.m13#21.o3" to "笛",
    "q.m13#21.e" to "風、ロープの長さ、地形が声を飲み込みます。ロープや笛の合図を事前に決めておくほうが、その場で叫ぶより確実です。",
    "q.m13#22.p" to "自救の技能を「安全な地形で無意識になるまで」練習すべきなのはなぜですか。",
    "q.m13#22.o0" to "実際の墜落では恐怖が注意を占め、自動化された動作しか出ないから",
    "q.m13#22.o1" to "試験のため",
    "q.m13#22.o2" to "速さのため",
    "q.m13#22.o3" to "見た目のため",
    "q.m13#22.e" to "これは救助訓練に共通する理屈です。考えなくても動けるところまで練習して初めて、観察と判断の余裕が残ります。",
    "q.m13#23.p" to "結び行進の救助で、二番目の人の主な役割は何ですか。",
    "q.m13#23.o0" to "制動を助け、システムを準備し、上方のリスクを観察する",
    "q.m13#23.o1" to "写真を撮る",
    "q.m13#23.o2" to "先へ進む",
    "q.m13#23.o3" to "ロープを巻く",
    "q.m13#23.e" to "三人結びの意味はここにあります。一人が制動、一人がシステム構築、一人が観察。二人結びなら兼ねるしかありません。",
    "q.m13#24.p" to "落ちた人に反応がない場合、救助の優先順位はどれですか。",
    "q.m13#24.o0" to "できるだけ早く出して急救を始め、同時に外部支援を要請する",
    "q.m13#24.o1" to "まず 5:1 システムを組む",
    "q.m13#24.o2" to "救助を待つ",
    "q.m13#24.o3" to "まず記録する",
    "q.m13#24.e" to "反応がないということは時間の窓が極端に短いということです。このときは「省力」より「速さ」が優先で、必要なら最も簡単なシステムを使います。",
    "q.m13#25.p" to "救助が終わった後、最も見落とされやすい手順は何ですか。",
    "q.m13#25.o0" to "システムと手順を振り返り、問題を書き留める",
    "q.m13#25.o1" to "ロープを巻く",
    "q.m13#25.o2" to "下山する",
    "q.m13#25.o3" to "食事をする",
    "q.m13#25.e" to "訓練と実戦の差は振り返りで見えます。どの段階が遅かったか、どの結び目を間違えたか、どの指示が聞き取れなかったか。",
    "q.m13#26.p" to "救助システムを「メインロープから独立」させるのはなぜですか。",
    "q.m13#26.o0" to "メインロープは氷屑や鋭い縁で傷んでいて、しかも荷重がかかったままのことがあるから",
    "q.m13#26.o1" to "規則だから",
    "q.m13#26.o2" to "より長いから",
    "q.m13#26.o3" to "より軽いから",
    "q.m13#26.e" to "傷んだうえに荷重のかかったメインロープへ救助システムを掛けるのは、二つのリスクを重ねることです。",
    "q.m13#27.p" to "クレバス帯で、隊が事前に決めておくべきことは何ですか。",
    "q.m13#27.o0" to "誰が制動し、誰がシステムを組み、どう連絡するか",
    "q.m13#27.o1" to "誰が先頭を歩くか",
    "q.m13#27.o2" to "誰が一番重い荷物を背負うか",
    "q.m13#27.o3" to "誰が写真を撮るか",
    "q.m13#27.e" to "分担は出発前に決めます。墜落してからの最初の 30 秒、誰も「誰が何をするか」を相談している時間はありません。",
    "q.l35#0.p" to "雪崩埋没の主な死因は何ですか。",
    "q.l35#0.o0" to "窒息（65〜100%）",
    "q.l35#0.o1" to "外傷",
    "q.l35#0.o2" to "低体温",
    "q.l35#0.o3" to "失血",
    "q.l35#0.e" to "この一点が処置の順序を決めます。まず気道と換気を確保し、その後に循環と復温を考えます。",
    "q.l35#1.p" to "完全埋没と部分埋没の生存率は、2023 年の集計でおおよそどれくらいですか。",
    "q.l35#1.o0" to "約 48% と 96%",
    "q.l35#1.o1" to "約 80% と 90%",
    "q.l35#1.o2" to "約 20% と 60%",
    "q.l35#1.o3" to "どちらも 50% 前後",
    "q.l35#1.e" to "二組の数字は二倍以上離れています。「頭が外に出ている」状況と「全身が埋まっている」状況は、まったく別物だということです。",
    "q.l35#2.p" to "生存曲線の「生存期」は、埋没後どれくらいを指しますか。",
    "q.l35#2.o0" to "最初の 18 分",
    "q.l35#2.o1" to "最初の 5 分",
    "q.l35#2.o2" to "18〜35 分",
    "q.l35#2.o3" to "90 分以降",
    "q.l35#2.e" to "生存期の死亡は主に外傷で、気道は多くの場合まだ通っています。これが「18 分」が繰り返し強調される理由です。",
    "q.l35#3.p" to "「窒息期」の曲線の特徴はどれですか。",
    "q.l35#3.o0" to "生存率が急落し、救助の窓が最も厳しい区間になる",
    "q.l35#3.o1" to "曲線がなだらか",
    "q.l35#3.o2" to "生存率が持ち直す",
    "q.l35#3.o3" to "低体温と関係しない",
    "q.l35#3.e" to "18〜35 分の急落は、気道が雪で塞がれることとエアポケットの酸素が尽きることから来ます。バディ救助の価値は、ほぼこの時間帯に集中しています。",
    "q.l35#4.p" to "「潜伏期」（約 35〜90 分）で生存率が比較的なだらかなのはなぜですか。",
    "q.l35#4.o0" to "エアポケットがあり気道が通っている人は低体温による保護状態に入り、代謝が下がるから",
    "q.l35#4.o1" to "雪が融けたから",
    "q.l35#4.o2" to "救助が到着したから",
    "q.l35#4.o3" to "外傷が回復したから",
    "q.l35#4.e" to "ここでは低体温が「脅威」ではなく「保護」として働きます。だから「長く埋まっていた」を、そのまま「助からない」と同一視してはいけないのです。",
    "q.l35#5.p" to "雪崩死における低体温死の割合はどれくらいですか。",
    "q.l35#5.o0" to "0〜4%",
    "q.l35#5.o1" to "20〜30%",
    "q.l35#5.o2" to "50%",
    "q.l35#5.o3" to "ほぼ全部",
    "q.l35#5.e" to "割合は低いですが、個別の症例は確かに存在します。まず換気、その後に復温という順序を逆にしてはいけないことを教えています。",
    "q.l35#6.p" to "雪崩発生から 0〜2 分で、最も優先すべき行動はどれですか。",
    "q.l35#6.o0" to "二次雪崩のリスクを確認し、安全監視役を指名し、時刻と最後の目撃点を記録する",
    "q.l35#6.o1" to "すぐ掘り始める",
    "q.l35#6.o2" to "写真に記録する",
    "q.l35#6.o3" to "家族に連絡する",
    "q.l35#6.e" to "監視役がいなければ、救助隊が二番目の埋没者になり得ます。時刻の記録がなければ、後の 60 分ルールを運用できません。",
    "q.l35#7.p" to "2〜10 分の段階の目標は何ですか。",
    "q.l35#7.o0" to "雪を全部どかすことではなく、できるだけ早く「人に接触する」こと",
    "q.l35#7.o1" to "標準的な通路を掘ること",
    "q.l35#7.o2" to "装備を片づけること",
    "q.l35#7.o3" to "専門隊を待つこと",
    "q.l35#7.e" to "顔に接触できれば換気を始められます。それは「完全に掘り出す」より数分早く、窒息期においてその数分が生死の差になります。",
    "q.l35#8.p" to "顔まで掘り着いてからの最初の 60 秒、正しい順序はどれですか。",
    "q.l35#8.o0" to "口と鼻の雪と氷片を取り除く → バイタルサインを確認する → 呼吸がなければただちに救援呼吸",
    "q.l35#8.o1" to "まず体を引き出す → その後に口と鼻を清掃",
    "q.l35#8.o2" to "まず写真を撮る → その後に処置",
    "q.l35#8.o3" to "まず温かい飲み物",
    "q.l35#8.e" to "まず気道を確保し、その後に他を考えます。人をそのまま引き出すのは脊椎損傷を悪化させ得るうえ、雪を口と鼻へ押し込みます。",
    "q.l35#9.p" to "「45 分で生存率 25% が、40 分の 18% より高い」の正しい理解はどれですか。",
    "q.l35#9.o0" to "標本が小さく、エアポケットのある人の割合が違うことによるばらつきで、曲線の反発ではない",
    "q.l35#9.o1" to "45 分のほうが安全だということ",
    "q.l35#9.o2" to "45 分まで待つべきだということ",
    "q.l35#9.o3" to "データが間違っている",
    "q.l35#9.e" to "教育では傾向を語り、単点の数字を絶対の約束にしません。ばらつきを法則と取り違えると、不合理な結論に至ります。",
    "q.l35#10.p" to "完全埋没者が掘り出された後、見た目が正常でもどうすべきですか。",
    "q.l35#10.o0" to "それでも医療機関へ搬送して観察する",
    "q.l35#10.o1" to "そのままキャンプへ戻る",
    "q.l35#10.o2" to "その日の行程を続ける",
    "q.l35#10.o3" to "自分で歩いて下山する",
    "q.l35#10.e" to "低酸素と低体温の影響は遅れて現れることがあります。観察と評価には設備と時間が必要で、キャンプでは対応できません。",
    "q.l35#11.p" to "雪崩の現場で必ず記録すべき情報はどれですか。",
    "q.l35#11.o0" to "目撃した時刻、または最後に確認した時刻",
    "q.l35#11.o1" to "最後に目撃した地点",
    "q.l35#11.o2" to "埋没した人数",
    "q.l35#11.o3" to "救助者の氏名",
    "q.l35#11.e" to "前の三つが捜索範囲と医学的な判断を直接決めます。救助者の氏名は事後の記録で、現場の判断には影響しません。",
    "q.l35#12.p" to "掘り出した後に同時に進めるべきことはどれですか。",
    "q.l35#12.o0" to "脊椎を保護し、乱暴に動かさない",
    "q.l35#12.o1" to "全身を保温し、濡れた衣類を脱がせ、地面から断熱する",
    "q.l35#12.o2" to "心拍と深部体温を継続的に監視する",
    "q.l35#12.o3" to "傷者本人に立って動いてもらう",
    "q.l35#12.e" to "前の三つが標準的な処置です。傷者に自分で動いてもらうのは、低体温と潜在的な脊椎損傷を悪化させます。",
    "q.l35#13.p" to "「助けるかどうかの判断に使うべきでない」要素はどれですか。",
    "q.l35#13.o0" to "埋没の深さ",
    "q.l35#13.o1" to "エアポケットの有無",
    "q.l35#13.o2" to "雪の密度",
    "q.l35#13.o3" to "気道が完全に埋まっているか",
    "q.l35#13.e" to "前三者は掘る時間に影響しますが、医学的な判断には影響しません。振り分けに関わるのは気道の状態、時間、温度だけです。",
    "q.l35#14.p" to "雪崩現場の最初の 10 分を正しい順序に並べてください。",
    "q.l35#14.o0" to "二次雪崩と落石のリスクを確認し、安全監視役を指名する",
    "q.l35#14.o1" to "時刻と最後の目撃点を記録し、救助を要請する",
    "q.l35#14.o2" to "ビーコンで捜索し、プローブで位置を定める",
    "q.l35#14.o3" to "掘削を始める。目標はできるだけ早く顔に接触すること",
    "q.l35#14.e" to "順序の背景にある論理は「まず救助を二件目の事故にしない」、次に「後の判断に根拠を持たせる」です。",
    "q.l35#15.p" to "顔まで掘り着いた後の処置の順序を並べてください。",
    "q.l35#15.o0" to "口と鼻の雪と氷片を取り除き、気道を評価する",
    "q.l35#15.o1" to "1 分以内にバイタルサインを確認する",
    "q.l35#15.o2" to "呼吸がなければただちに救援呼吸を行う",
    "q.l35#15.o3" to "60 分ルールで振り分け、搬送を手配する",
    "q.l35#15.e" to "換気は「完全に掘り出す」より早く、搬送より早くなければなりません。実践ではここが最も逆になりやすいところです。",
    "q.l35#16.p" to "雪崩埋没の主な死因は窒息で、全死亡の ______〜100% を占めます。",
    "q.l35#16.a0" to "65",
    "q.l35#16.e" to "65〜100% という範囲は九つの研究から来ています。これが「まず換気」を鉄則にしている理由です。",
    "q.l35#17.p" to "生存曲線で繰り返し強調される「黄金の ______ 分」は、窒息期が始まる前の時間窓を指します。",
    "q.l35#17.a0" to "18",
    "q.l35#17.a1" to "十八",
    "q.l35#17.e" to "18 分は統計上の急落点です。魔法の数字ではありませんが、訓練の目標としては十分に使えます。",
    "q.l35#18.p" to "低体温による死亡は、雪崩死の ______〜4% にすぎません。",
    "q.l35#18.a0" to "0",
    "q.l35#18.e" to "0〜4%。割合は低いものの、「長時間埋没でも助かる」少数例を説明します。",
    "q.l35#19.p" to "生存曲線の四段階と、その特徴を対応させてください。",
    "q.l35#19.l0" to "生存期（0〜18 分）",
    "q.l35#19.l1" to "窒息期（18〜35 分）",
    "q.l35#19.l2" to "潜伏期（35〜90 分）",
    "q.l35#19.l3" to "長期（90 分以上）",
    "q.l35#19.r0" to "死亡は主に外傷。気道は多くの場合通っている",
    "q.l35#19.r1" to "生存率が急落し、救助の窓が最も厳しい",
    "q.l35#19.r2" to "エアポケットがあると低体温の保護に入り、曲線はなだらか",
    "q.l35#19.r3" to "低体温が主体。極端に長い埋没からの生還が稀にある",
    "q.l35#19.e" to "四段階は四つの死因構造に対応します。曲線を四つの段階として語るほうが、個々のパーセントを覚えるより役に立ちます。",
    "q.l35#20.p" to "死因と、その割合を対応させてください。",
    "q.l35#20.l0" to "窒息",
    "q.l35#20.l1" to "外傷",
    "q.l35#20.l2" to "低体温",
    "q.l35#20.r0" to "65〜100%",
    "q.l35#20.r1" to "5〜29%",
    "q.l35#20.r2" to "0〜4%",
    "q.l35#20.e" to "この割合の組が処置の優先順位の出所です。換気 > 止血と固定 > 復温。",
    "q.l35#21.p" to "安全監視役を決めずに掘り始めた場合、最大のリスクは何ですか。",
    "q.l35#21.o0" to "二次雪崩が救助者も埋めてしまう",
    "q.l35#21.o1" to "掘るのが遅くなる",
    "q.l35#21.o2" to "ロープが足りない",
    "q.l35#21.o3" to "記録が残らない",
    "q.l35#21.e" to "雪崩は一度しか起きないことは稀です。監視役は、二度目が来たときに止められる唯一の存在です。",
    "q.l35#22.p" to "「人に触れたらすぐ引き出す」のがなぜだめなのですか。",
    "q.l35#22.o0" to "脊椎損傷を悪化させ得るし、雪を口と鼻へ押し込むこともあるから",
    "q.l35#22.o1" to "衣類が傷むから",
    "q.l35#22.o2" to "写真を撮るのが遅れるから",
    "q.l35#22.o3" to "傷者が驚くから",
    "q.l35#22.e" to "まず顔、次に気道、頭頸部の位置を確認してから胸と体を出す。順序を誤ると、助け出しても麻痺が残ることがあります。",
    "q.l35#23.p" to "現場に自分一人しかいない場合、掘るのと救助要請のどちらを先にしますか。",
    "q.l35#23.o0" to "まず掘る。救助の窓はどんな応答時間よりも短い。合図は機会があれば後で出す",
    "q.l35#23.o1" to "まず電話する",
    "q.l35#23.o2" to "まずキャンプへ人を呼びに戻る",
    "q.l35#23.o3" to "まず動画を撮る",
    "q.l35#23.e" to "一人のとき、救助を待つことはほぼ放棄と同じです。合図を出す時機は後で探せますが、掘削は待てません。",
    "q.l35#24.p" to "「埋没時間」の記録をなぜ分単位で正確に取る必要があるのですか。",
    "q.l35#24.o0" to "その後の蘇生の振り分けで、どのルールを使うかが決まるから",
    "q.l35#24.o1" to "報告書を書くため",
    "q.l35#24.o2" to "保険の請求のため",
    "q.l35#24.o3" to "統計のため",
    "q.l35#24.e" to "60 分が振り分けの分岐点で、現場では目撃時刻から推定するしかありません。10 分記録がずれれば、判断は別の経路に入ります。",
    "q.l35#25.p" to "「深く埋まっている」が「望みがない」ではないのはなぜですか。",
    "q.l35#25.o0" to "深さは掘る時間に影響するが、医学的な判断は時間・気道・温度で行うから",
    "q.l35#25.o1" to "雪が融けるから",
    "q.l35#25.o2" to "人が多いから",
    "q.l35#25.o3" to "深く埋まった人は冷たいから",
    "q.l35#25.e" to "深さを医学的な判断基準にすると、人が早めに諦めてしまいます。深さは「どれだけ掘るか」を変えるだけで、「何をすべきか」は変えません。",
    "q.l36#0.p" to "2023 年版 ICAR MedCom の、埋没時間による判断の線はどれですか。",
    "q.l36#0.o0" to "60 分",
    "q.l36#0.o1" to "35 分",
    "q.l36#0.o2" to "90 分",
    "q.l36#0.o3" to "120 分",
    "q.l36#0.e" to "2013 年版は 35 分で、2023 年に 60 分へ更新されました。教材には年と基準を明記しなければなりません。",
    "q.l36#1.p" to "埋没 25 分、バイタルサインなし、気道が緩い雪で一部塞がれている（完全には埋まっていない）。どうすべきですか。",
    "q.l36#1.o0" to "窒息として扱う。口と鼻を清掃し、できるだけ早く救援呼吸を行い、同時に胸骨圧迫を始める",
    "q.l36#1.o1" to "閉塞として扱い、蘇生を断念する",
    "q.l36#1.o2" to "まず復温する",
    "q.l36#1.o3" to "専門隊を待つ",
    "q.l36#1.e" to "60 分以下は気道が通っていてもいなくても窒息として扱います。緩い雪は閉塞ではありません。閉塞は「完全に埋まっている」ことを要求します。",
    "q.l36#2.p" to "埋没 70 分、バイタルサインなし、気道は通っている、深部体温は測れない。どうすべきですか。",
    "q.l36#2.o0" to "低体温性心停止として扱い、心肺蘇生を開始して搬送する",
    "q.l36#2.o1" to "窒息として扱い、蘇生しない",
    "q.l36#2.o2" to "体温が測れるまで待つ",
    "q.l36#2.o3" to "保温だけを行う",
    "q.l36#2.e" to "気道が通っていて 60 分を超えていれば、低体温性心停止の可能性が十分に高いので蘇生します。低温の心臓は「暖まっていないから死んでいる」わけではありません。",
    "q.l36#3.p" to "埋没 70 分、バイタルサインなし、口と鼻が締まった雪で完全に埋まっている、現場で体温は測れない。どうすべきですか。",
    "q.l36#3.o0" to "窒息性心停止として扱い、心肺蘇生を開始しない",
    "q.l36#3.o1" to "ただちに胸骨圧迫を始める",
    "q.l36#3.o2" to "まず掘り出してから判断する",
    "q.l36#3.o3" to "2 回呼吸を送ってから断念する",
    "q.l36#3.e" to "これは 2023 年版が明確に挙げた「蘇生を開始しなくてよい」状況です。体温が測れて 30 ℃ 未満なら、蘇生を試みる側に変わります。",
    "q.l36#4.p" to "深部体温 28 ℃、気道は通っている、バイタルサインなし、埋没 80 分。どうすべきですか。",
    "q.l36#4.o0" to "蘇生を試み、体外循環で復温できる病院へ搬送する",
    "q.l36#4.o1" to "蘇生を断念する",
    "q.l36#4.o2" to "保温だけを行う",
    "q.l36#4.o3" to "体温が上がるまで判断を待つ",
    "q.l36#4.e" to "30 ℃ 未満で気道が通っていれば、埋没時間に関わらず蘇生を試みます。こうした傷者には ECLS 相当の復温環境が必要です。",
    "q.l36#5.p" to "雪崩救助における「気道閉塞」の定義はどれですか。",
    "q.l36#5.o0" to "口と鼻が締まった雪や碎片で完全に埋まっていること",
    "q.l36#5.o1" to "口の中に少し雪があること",
    "q.l36#5.o2" to "痰があること",
    "q.l36#5.o3" to "鼻出血があること",
    "q.l36#5.e" to "定義を厳密にしないといけないのは、蘇生を始めるかどうかを直接決めるからです。判断がつかないときは通っているものとして扱う、これが助ける側に寄せた既定値です。",
    "q.l36#6.p" to "エアポケットについて、正しい説明はどれですか。",
    "q.l36#6.o0" to "エアポケットがあれば生存率は高いが、助けるかどうかの判断根拠にはならない",
    "q.l36#6.o1" to "エアポケットがなければ助ける必要はない",
    "q.l36#6.o2" to "エアポケットがあれば必ず助かる",
    "q.l36#6.o3" to "エアポケットが閉塞を決める",
    "q.l36#6.e" to "2023 年版は明確にしています。エアポケットの有無、雪の密度、埋没の深さはいずれも処置を変えない。それらが変えるのは時間であって、判断ではありません。",
    "q.l36#7.p" to "胸骨圧迫はいつ始めてよいですか。",
    "q.l36#7.o0" to "完全に掘り出すのを待たなくてよい。胸が露出すれば始められる",
    "q.l36#7.o1" to "全身を掘り出すまで待たなければならない",
    "q.l36#7.o2" to "病院に着くまで待たなければならない",
    "q.l36#7.o3" to "体温が測れるまで待たなければならない",
    "q.l36#7.e" to "「掘り出してから押す」と待つと、数分を無駄にします。2023 年版は、体勢が異常でも、まだ雪から出ていなくても有効な圧迫ができると明記しています。",
    "q.l36#8.p" to "救援呼吸をなぜ早く行う必要があるのですか。",
    "q.l36#8.o0" to "こうした傷者の大半は窒息で死に、低酸素が第一の問題だから",
    "q.l36#8.o1" to "手間がかからないから",
    "q.l36#8.o2" to "家族を安心させるため",
    "q.l36#8.o3" to "酸素を節約するため",
    "q.l36#8.e" to "まず換気、その後に循環です。これが「60 分以下なら気道の状態を問わない」というルールの生理的な根拠です。",
    "q.l36#9.p" to "蘇生を中止する指標には通常何が含まれますか。",
    "q.l36#9.o0" to "致命的な外傷、完全な凍結、気道閉塞かつ埋没 60 分超、血清カリウムの明らかな上昇",
    "q.l36#9.o1" to "家族の要望",
    "q.l36#9.o2" to "日が暮れたこと",
    "q.l36#9.o3" to "装備が足りないこと",
    "q.l36#9.e" to "この指標は 2023 年版と ICAR の中止勧告から来ています。判断するのは訓練を受けた者であり、掘っている人ではありません。",
    "q.l36#10.p" to "「まずどれだけ深く埋まったかを見て、助けるか決める」という言葉はどこが誤りですか。",
    "q.l36#10.o0" to "深さは掘る時間に影響するが、医学的な判断には関与しない",
    "q.l36#10.o1" to "深さは測れない",
    "q.l36#10.o2" to "深さはいつも浅い",
    "q.l36#10.o3" to "深さが生存率を決める",
    "q.l36#10.e" to "工学の問題を医学的な判断基準にすると、人が早めに諦めます。判断が見るのは時間、気道、温度だけです。",
    "q.l36#11.p" to "2023 年版で、振り分けの判断に関わる要素はどれですか。",
    "q.l36#11.o0" to "埋没時間",
    "q.l36#11.o1" to "気道が通っているか",
    "q.l36#11.o2" to "深部体温が測れるか、その値",
    "q.l36#11.o3" to "埋没の深さ",
    "q.l36#11.e" to "前三者で判断の樹が構成されます。四つ目は「どれだけ掘るか」に影響するだけで、振り分けは変えません。",
    "q.l36#12.p" to "低体温性心停止の処置の要点はどれですか。",
    "q.l36#12.o0" to "乱暴に動かさず、激しい揺れを避ける",
    "q.l36#12.o1" to "全身を断熱して保温する",
    "q.l36#12.o2" to "心拍と深部体温を継続的に監視する",
    "q.l36#12.o3" to "現場で 35 ℃ まで復温してから搬送する",
    "q.l36#12.e" to "現場で有効な復温はできず、「まず暖めてから運ぶ」はかえって遅れます。目標は ECLS のある施設へできるだけ早く運ぶことです。",
    "q.l36#13.p" to "気道と換気について、正しいやり方はどれですか。",
    "q.l36#13.o0" to "口と鼻の雪と氷片を取り除く",
    "q.l36#13.o1" to "閉塞かどうか判断がつかないときは通っているものとして扱う",
    "q.l36#13.o2" to "圧迫より先に換気を考える",
    "q.l36#13.o3" to "完全に掘り出してから気道を評価する",
    "q.l36#13.e" to "前三者はすべて「できるだけ早く換気する」に向かっています。最後の一つは最も重要な数分を遅らせます。",
    "q.l36#14.p" to "「60 分以下、バイタルサインなし」の処置の順序を並べてください。",
    "q.l36#14.o0" to "口と鼻を清掃し、気道を評価する",
    "q.l36#14.o1" to "ただちに救援呼吸を行う",
    "q.l36#14.o2" to "胸骨圧迫を始める",
    "q.l36#14.o3" to "保温と脊椎保護を行い、搬送を手配する",
    "q.l36#14.e" to "換気が圧迫より優先です。これが雪崩による窒息性心停止と、通常の心原性心停止の最も大きな違いです。",
    "q.l36#15.p" to "「60 分超」の場合の振り分け判断の順序を並べてください。",
    "q.l36#15.o0" to "埋没時間が確かに 60 分を超えていると確認する",
    "q.l36#15.o1" to "気道が完全に埋まっているか評価する",
    "q.l36#15.o2" to "深部体温の測定を試みる",
    "q.l36#15.o3" to "対応する分岐に従って蘇生を始めるか決める",
    "q.l36#15.e" to "順序は「まず時間、次に気道、最後に温度」を表します。三つのうちどれかの情報が欠けたら、助ける側に寄った分岐で扱います。",
    "q.l36#16.p" to "2023 年版 ICAR MedCom の蘇生の判断線は、埋没 ______ 分です。",
    "q.l36#16.a0" to "60",
    "q.l36#16.e" to "旧版の 35 分は廃止されました。教材と問題バンクは 60 分に統一しなければなりません。",
    "q.l36#17.p" to "深部体温が ______ ℃ 未満で気道が通っているなら、埋没時間に関わらず蘇生を試みます。",
    "q.l36#17.a0" to "30",
    "q.l36#17.e" to "30 ℃ は併存する判断基準です。「低体温による保護」の窓を判断に組み込んでいます。",
    "q.l36#18.p" to "雪崩の死因で低体温は 0〜4% にすぎないので、処置はまず ______、その後に復温という順序になります。",
    "q.l36#18.a0" to "換気",
    "q.l36#18.a1" to "気道",
    "q.l36#18.a2" to "気道の確保",
    "q.l36#18.e" to "先に換気、その後に復温。この順序は雪崩救助では、通常の低体温症よりも厳格です。",
    "q.l36#19.p" to "埋没の状況と処置を対応させてください（2023 年版）。",
    "q.l36#19.l0" to "60 分以下、バイタルサインなし",
    "q.l36#19.l1" to "60 分超、気道は通っている、体温は測れない",
    "q.l36#19.l2" to "60 分超、気道閉塞、体温は測れない",
    "q.l36#19.l3" to "体温が測れて 30 ℃ 未満、気道は通っている",
    "q.l36#19.r0" to "窒息として扱い、できるだけ早く救援呼吸を行う",
    "q.l36#19.r1" to "低体温性心停止として扱い、蘇生を開始する",
    "q.l36#19.r2" to "窒息性心停止として扱い、蘇生を開始しない",
    "q.l36#19.r3" to "時間に関わらず蘇生を試み、ECLS へ搬送する",
    "q.l36#19.e" to "四つの分岐で、現場のほとんどの状況を覆えます。結論を覚えるより、分岐の条件を覚えるほうが確実です。",
    "q.l36#20.p" to "「蘇生を中止してよい」指標と、その意味を対応させてください。",
    "q.l36#20.l0" to "致命的な外傷",
    "q.l36#20.l1" to "完全な凍結",
    "q.l36#20.l2" to "気道閉塞かつ 60 分超",
    "q.l36#20.l3" to "血清カリウムの明らかな上昇",
    "q.l36#20.r0" to "傷病そのものが救命できない",
    "q.l36#20.r1" to "体が凍結しており、復温に意味がない",
    "q.l36#20.r2" to "窒息性心停止として扱い、蘇生を開始しない",
    "q.l36#20.r3" to "長時間の低酸素を示し、予後がきわめて悪い",
    "q.l36#20.e" to "四つとも「医学的に逆転の見込みがない」証拠です。判断は訓練を受けた者が行い、根拠を記録します。",
    "q.l36#21.p" to "現場で「35 分を超えたら助けない」と言う人がいます。どう返しますか。",
    "q.l36#21.o0" to "それは 2013 年版の基準で、2023 年版は 60 分に変わり、温度の判断も加わっている",
    "q.l36#21.o1" to "そのとおりだ",
    "q.l36#21.o2" to "状況による",
    "q.l36#21.o3" to "本人に決めさせる",
    "q.l36#21.e" to "日本語・中国語の資料には 35 分が今も多数残っています。基準を更新することは、この種の講座で最も実用的な価値の一つです。",
    "q.l36#22.p" to "状況：埋没 20 分、掘り出したとき呼吸なし、口と鼻に緩い雪があるが完全には埋まっていない。最も優先すべきはどれですか。",
    "q.l36#22.o0" to "口と鼻を清掃し、救援呼吸を行い、胸骨圧迫を始めて速やかに搬送する",
    "q.l36#22.o1" to "閉塞と判定し、蘇生しない",
    "q.l36#22.o2" to "まず復温する",
    "q.l36#22.o3" to "専門隊の判断を待つ",
    "q.l36#22.e" to "60 分以下＋完全な閉塞ではない＝窒息として扱い、全力で蘇生します。緩い雪は閉塞になりません。",
    "q.l36#23.p" to "状況：埋没 70 分、気道は通っている、深部体温 28 ℃、バイタルサインなし。最も優先すべきはどれですか。",
    "q.l36#23.o0" to "蘇生を続け、乱暴に動かさず、全身を保温して、ECLS で復温できる病院へ搬送する",
    "q.l36#23.o1" to "蘇生を中止する",
    "q.l36#23.o2" to "保温して観察するだけにする",
    "q.l36#23.o3" to "35 ℃ まで復温してから搬送する",
    "q.l36#23.e" to "低体温性心停止の要点は「復温できる場所へ運ぶ」ことです。搬送中も蘇生を止めてはいけません。",
    "q.l36#24.p" to "「低温の心臓は敏感だ」と言われるのはなぜですか。",
    "q.l36#24.o0" to "乱暴に動かすと心室細動を誘発し得るので、静かに水平に運ぶ必要があるから",
    "q.l36#24.o1" to "寒がりだから",
    "q.l36#24.o2" to "心拍が遅いから",
    "q.l36#24.o3" to "血圧が低いから",
    "q.l36#24.e" to "これが低体温の傷者を「水平・静か・ゆっくり」運ぶ理由であり、雪崩救助で脊椎保護とは別にもう一段強調される理由です。",
    "q.l36#25.p" to "救助中に同行者が感情的になって蘇生を止めたいと言っています。リーダーはどうすべきですか。",
    "q.l36#25.o0" to "その人を操作から外し、蘇生は続ける。判断は訓練を受けた者が指標に沿って行う",
    "q.l36#25.o1" to "すぐ中止する",
    "q.l36#25.o2" to "叱る",
    "q.l36#25.o3" to "そのまま圧迫を続けさせる",
    "q.l36#25.e" to "感情は受け止める必要がありますが、医学的な判断を感情で決めてはいけません。手を止めるのではなく人を替えるのが、より責任ある対応です。",
    "q.l37#0.p" to "雪崩捜索の四段階の順序はどれですか。",
    "q.l37#0.o0" to "信号と手がかりの捜索 → 粗い捜索 → 細かい捜索 → ポイント探査",
    "q.l37#0.o1" to "粗い捜索 → 細かい捜索 → ポイント探査 → 信号の捜索",
    "q.l37#0.o2" to "ポイント探査 → 細かい捜索 → 粗い捜索",
    "q.l37#0.o3" to "捜索 → 掘削 → 探査",
    "q.l37#0.e" to "四段階は「段階的に絞り込む」過程です。斜面全体から数メートルへ、雪面上の一点へ、そして具体的な深さへ。どれか一段を飛ばすと時間を無駄にします。",
    "q.l37#1.p" to "ビーコン捜索の帯の間隔は通常どれくらいですか。",
    "q.l37#1.o0" to "約 40 m。デブリの縁からは約 20 m",
    "q.l37#1.o1" to "10 m",
    "q.l37#1.o2" to "80 m",
    "q.l37#1.o3" to "広ければ広いほどよい",
    "q.l37#1.e" to "40 m は教育上の既定値で、機器の上限ではありません。訓練の程度に自信がなければ 30 m に詰め、何往復か多く歩くほうが安全です。",
    "q.l37#2.p" to "捜索を始める前に、隊がまずすべきことは何ですか。",
    "q.l37#2.o0" to "全員のビーコンを受信モードに切り替え、携帯やカメラなど妨害源の電源を切る",
    "q.l37#2.o1" to "まず試し穴を掘る",
    "q.l37#2.o2" to "まず写真を撮る",
    "q.l37#2.o3" to "まずロープを片づける",
    "q.l37#2.e" to "誰かが送信モードのままだと捜索は成立せず、電子機器の妨害は有効距離を縮めます。この二つは最初の一歩で終えなければなりません。",
    "q.l37#3.p" to "信号と手がかりの捜索段階で、最初に注目するものはどれですか。",
    "q.l37#3.o0" to "雪面の目に見える手がかり（手袋、ストックの先、バックルのベルト）",
    "q.l37#3.o1" to "ビーコンの数値",
    "q.l37#3.o2" to "雪層の構造",
    "q.l37#3.o3" to "風向",
    "q.l37#3.e" to "表面の手がかりが、捜索範囲を数十メートルまで狭めてくれることがあります。下を向いてビーコンばかり見ていると、この手がかりを逃します。",
    "q.l37#4.p" to "粗い捜索の目標は、距離をどれくらいまで縮めることですか。",
    "q.l37#4.o0" to "3〜5 m",
    "q.l37#4.o1" to "20 m",
    "q.l37#4.o2" to "0.5 m",
    "q.l37#4.o3" to "10〜15 m",
    "q.l37#4.e" to "3〜5 m になってから細かい捜索に入ります。ここが「走る」から「歩く」に変わる地点であり、精度が効き始める場所です。",
    "q.l37#5.p" to "粗い捜索中に距離の数値が大きくなったら、何を意味しますか。",
    "q.l37#5.o0" to "方向が逆。来た道を戻る",
    "q.l37#5.o1" to "信号が強すぎる",
    "q.l37#5.o2" to "機器が故障している",
    "q.l37#5.o3" to "埋没者が動いた",
    "q.l37#5.e" to "ビーコンの数値は「距離」です。大きくなるのは逆方向へ進んでいる証拠で、この判断は速く行い、その場で何度も確かめ直さないことです。",
    "q.l37#6.p" to "細かい捜索段階の正しい動作はどれですか。",
    "q.l37#6.o0" to "ビーコンを雪面に近づけ、十字に交差させながら最小値の点を探して印を付ける",
    "q.l37#6.o1" to "立ったまま回る",
    "q.l37#6.o2" to "斜面を下へ直線的に歩く",
    "q.l37#6.o3" to "プローブをでたらめに刺す",
    "q.l37#6.e" to "雪面に近づけると、雪の中での信号の屈折による誤差が減ります。最小値に印を付けるのは、プローブに明確な起点を作るためです。",
    "q.l37#7.p" to "ポイント探査で、プローブは何に対して 90 度にしますか。",
    "q.l37#7.o0" to "雪面（斜面）に対して 90 度",
    "q.l37#7.o1" to "水平面に対して 90 度",
    "q.l37#7.o2" to "斜面に対して 45 度",
    "q.l37#7.o3" to "どの角度でもよい",
    "q.l37#7.e" to "斜面で「真下」に刺すと、プローブは雪層を斜めに通り、深さの読みが斜面の角度で膨らみます。バディ救助では雪面に対して 90 度に刺します。",
    "q.l37#8.p" to "一度刺して当たらなかったとき、次にどうしますか。",
    "q.l37#8.o0" to "25 cm 四方の格子で外側へ広げていく",
    "q.l37#8.o1" to "より長いプローブに替える",
    "q.l37#8.o2" to "すぐシャベルで掘る",
    "q.l37#8.o3" to "この点は諦める",
    "q.l37#8.e" to "25 cm（約 10 インチ）が標準の格子です。大きすぎれば見落とし、小さすぎれば時間を浪費します。",
    "q.l37#9.p" to "硬いものに当たった後、それが人かどうかをどう判断しますか。",
    "q.l37#9.o0" to "「軟らかく弾力があり体らしい」抵抗を探し、周囲の地面の深さと比べる",
    "q.l37#9.o1" to "硬ければ何でも掘る",
    "q.l37#9.o2" to "プローブに血が付いているか見る",
    "q.l37#9.o3" to "音を聞く",
    "q.l37#9.e" to "岩や氷は硬く脆い抵抗で、人体には弾力があります。また埋没者は周囲の地面より深い位置にいることは通常ありません。",
    "q.l37#10.p" to "当たった後、プローブはどう扱いますか。",
    "q.l37#10.o0" to "抜かずにその場に残し、位置と深さの目印にする",
    "q.l37#10.o1" to "すぐ抜く",
    "q.l37#10.o2" to "さらに深く刺す",
    "q.l37#10.o3" to "同行者に渡す",
    "q.l37#10.e" to "その場に残したプローブは掘削者の「的」であり、正しい位置まで掘れたかどうかの基準にもなります。",
    "q.l37#11.p" to "埋没深度がプローブの長さを超えるとき、正しいやり方はどれですか。",
    "q.l37#11.o0" to "まず約 1 m 掘り、ビーコンで再定位してから、もう一度探る",
    "q.l37#11.o1" to "そのまま力任せに刺す",
    "q.l37#11.o2" to "諦める",
    "q.l37#11.o3" to "人を替えて刺す",
    "q.l37#11.e" to "底に届かないのだから、無理に刺しても意味がありません。まず距離を縮めてから再定位する、これが唯一有効な手順です。",
    "q.l37#12.p" to "組織的な救助でプローブを（雪面に垂直ではなく）鉛直に保つのはなぜですか。",
    "q.l37#12.o0" to "隊員ごとの深さの読みを揃え、一貫した探査面を作るため",
    "q.l37#12.o1" to "楽だから",
    "q.l37#12.o2" to "速いから",
    "q.l37#12.o3" to "規格がそう定めているから",
    "q.l37#12.e" to "組織的な探査線は「面」であり、比較できる深さのデータが必要です。バディ救助は一点だけを狙うので、雪面に垂直なほうが正確になります。",
    "q.l37#13.p" to "出発前のビーコンの点検に含まれるものはどれですか。",
    "q.l37#13.o0" to "電池の残量が十分",
    "q.l37#13.o1" to "送信テストを一度行う",
    "q.l37#13.o2" to "受信への切り替え、マークとサプレッションができる",
    "q.l37#13.o3" to "体に密着させて装着し、ザックの底に入れない",
    "q.l37#13.e" to "四つのどれが欠けても、肝心なときに役に立ちません。最もよくある誤りはザックの底に入れることで、ザックが埋まるか落ちればビーコンも失います。",
    "q.l37#14.p" to "プローブの点検の要点はどれですか。",
    "q.l37#14.o0" to "現地の雪深に合わせた長さを選ぶ",
    "q.l37#14.o1" to "引き綱とロックが正常",
    "q.l37#14.o2" to "片手で展開して固定できる",
    "q.l37#14.o3" to "軽ければ軽いほどよい",
    "q.l37#14.e" to "救助隊用のプローブは 3 m 以上が推奨され（UIAA 157）、個人用は 240〜320 cm がよく使われます。軽さも大事ですが、強度とロックの確実さのほうが重要です。",
    "q.l37#15.p" to "複数人が同時に埋まったとき、正しい対応はどれですか。",
    "q.l37#15.o0" to "最初の信号にマークかサプレッションを掛ける",
    "q.l37#15.o1" to "その後に二つ目の信号を探す",
    "q.l37#15.o2" to "一つの信号で確認を繰り返し、他の区域を放棄しない",
    "q.l37#15.o3" to "最も近い人だけを助ける",
    "q.l37#15.e" to "複数埋没で最大のリスクは「一人しか見つからない」ことです。マークとサプレッションの機能は、まさにこのためにあります。",
    "q.l37#16.p" to "1 回の捜索全体を正しい順序に並べてください。",
    "q.l37#16.o0" to "全員が受信に切り替え、妨害源の電源を切る",
    "q.l37#16.o1" to "捜索帯に沿って信号を探す",
    "q.l37#16.o2" to "粗い捜索で 3〜5 m まで詰める",
    "q.l37#16.o3" to "細かい捜索で最小値の点を探して印を付ける",
    "q.l37#16.o4" to "ポイント探査を行い、プローブを残す",
    "q.l37#16.e" to "五つの段階は「面」から「点」への収束過程です。どこか一つを省こうとすると、次の段階で倍の代償を払います。",
    "q.l37#17.p" to "ポイント探査の操作の順序を並べてください。",
    "q.l37#17.o0" to "最小値の点から、プローブを雪面に対して 90 度で刺す",
    "q.l37#17.o1" to "当たらなければ 25 cm の格子で広げる",
    "q.l37#17.o2" to "弾力のある抵抗に当たったら止める",
    "q.l37#17.o3" to "プローブを残して印とし、掘削を始める",
    "q.l37#17.e" to "順序で最も誤りやすいのは最後です。当たった瞬間にプローブを抜いてしまい、掘削の基準を失う人が多いのです。",
    "q.l37#18.p" to "ビーコン捜索の帯の間隔は約 ______ m です。",
    "q.l37#18.a0" to "40",
    "q.l37#18.e" to "自信がなければ 30 m に詰めます。帯が広すぎると信号を取りこぼし、これが捜索失敗の最もよくある原因です。",
    "q.l37#19.p" to "ポイント探査の格子の一辺は ______ cm です。",
    "q.l37#19.a0" to "25",
    "q.l37#19.e" to "約 10 インチ。格子が大きすぎれば人体を見落とし、小さすぎれば時間を浪費します。",
    "q.l37#20.p" to "バディ救助のプローブは ______ に対して 90 度で刺します。",
    "q.l37#20.a0" to "雪面",
    "q.l37#20.a1" to "斜面",
    "q.l37#20.e" to "水平面に垂直にすると深さの読みが斜面の角度で膨らみます。初心者が最もよくやる幾何の誤りです。",
    "q.l37#21.p" to "捜索の段階と、その目標を対応させてください。",
    "q.l37#21.l0" to "信号と手がかりの捜索",
    "q.l37#21.l1" to "粗い捜索",
    "q.l37#21.l2" to "細かい捜索",
    "q.l37#21.l3" to "ポイント探査",
    "q.l37#21.r0" to "最初の信号を見つける",
    "q.l37#21.r1" to "距離を 3〜5 m まで詰める",
    "q.l37#21.r2" to "雪面上で埋没者に最も近い点を見つける",
    "q.l37#21.r3" to "プローブで位置と深さを確認する",
    "q.l37#21.e" to "四つの目標は段階的に収束します。動作ではなく目標を覚えておくほうが、地形が変わっても応用が効きます。",
    "q.l37#22.p" to "装備と、その要点を対応させてください。",
    "q.l37#22.l0" to "ビーコン",
    "q.l37#22.l1" to "プローブ",
    "q.l37#22.l2" to "シャベル",
    "q.l37#22.l3" to "ヘルメット",
    "q.l37#22.r0" to "3 アンテナのデジタル式。体に密着させ、マークとサプレッションができる",
    "q.l37#22.r1" to "雪深に合った長さで、片手でロックできる",
    "q.l37#22.r2" to "金属刃、確実なシャフト、すばやく取り出せる",
    "q.l37#22.r3" to "捜索と掘削の間ずっと着用する",
    "q.l37#22.e" to "四つで最も見落とされやすいのがヘルメットです。掘削中も上から雪塊や氷片が落ちてきます。",
    "q.l37#23.p" to "捜索中、ある人が最初の信号の所で立ち止まり確認を繰り返しています。どうすべきですか。",
    "q.l37#23.o0" to "まずマークかサプレッションを掛けさせ、残りの区域の捜索を続けさせる",
    "q.l37#23.o1" to "そのまま続けさせる",
    "q.l37#23.o2" to "一緒に立ち止まる",
    "q.l37#23.o3" to "捜索を諦める",
    "q.l37#23.e" to "複数埋没では、「すべての信号を先に拾う」ことが「一点を極限まで確かめる」ことより重要です。",
    "q.l37#24.p" to "捜索段階で「携帯とカメラの電源を切る」のはなぜですか。",
    "q.l37#24.o0" to "電子機器がビーコンの信号を妨害し、有効な捜索距離を縮めるから",
    "q.l37#24.o1" to "電池を節約するため",
    "q.l37#24.o2" to "静かにするため",
    "q.l37#24.o3" to "写真を撮らせないため",
    "q.l37#24.e" to "妨害は捜索帯の有効幅を狭め、間接的に見落としを招きます。実行時に最も省略されやすい項目です。",
    "q.l37#25.p" to "隊が二人しかいない場合、一人が捜索し一人が掘るという分担は妥当ですか。",
    "q.l37#25.o0" to "妥当。ただし当たった後は二人で交代しながら掘り、一人で無理をしない",
    "q.l37#25.o1" to "妥当でない。二人で一緒に捜索すべき",
    "q.l37#25.o2" to "妥当でない。救助を待つべき",
    "q.l37#25.o3" to "妥当。交代も不要",
    "q.l37#25.e" to "二人組の要点は「当たったら即交代」です。一人で掘り続けると数分で力尽き、かえって効率が落ちます。",
    "q.l37#26.p" to "捜索前にデブリ帯の上方に不安定な雪があると分かりました。どうすべきですか。",
    "q.l37#26.o0" to "まず監視役を指名し、安全な接近ルートを選んでから捜索を始める",
    "q.l37#26.o1" to "そのまま飛び込む",
    "q.l37#26.o2" to "雪がやむのを待つ",
    "q.l37#26.o3" to "捜索を諦める",
    "q.l37#26.e" to "救助者が二次雪崩に埋まる事故は実際にあります。監視役と接近ルートは、捜索の「追加手順」ではなく一部です。",
    "q.l37#27.p" to "「10 分で接触、18 分で掘り出す」という二つの目標の意味はどれですか。",
    "q.l37#27.o0" to "隊内の管理指標であり、訓練と振り返りに使うもので、保証ではない",
    "q.l37#27.o1" to "医学的な約束",
    "q.l37#27.o2" to "規格の定め",
    "q.l37#27.o3" to "機器の性能値",
    "q.l37#27.e" to "目標の役割は「どこで遅れたか」を隊が知ることです。約束と取り違えると、達成できなかったときに判断を失います。",
    "q.l38#0.p" to "掘削の第一原則はどれですか。",
    "q.l38#0.o0" to "常に斜面の下側から作業する",
    "q.l38#0.o1" to "真上から掘り下げる",
    "q.l38#0.o2" to "斜面の上側から掘り下げる",
    "q.l38#0.o3" to "真横から水平に掘る",
    "q.l38#0.e" to "下側からの作業には利点が三つあります。雪を下へ捨てられ、通路に勾配が付き、掘削者が埋没者の上に立たずに済みます。",
    "q.l38#1.p" to "従来の「埋没深の 1.5 倍」という合言葉は、何を表していますか。",
    "q.l38#1.o0" to "プローブから斜面に沿って下へ下がる距離",
    "q.l38#1.o1" to "通路の幅",
    "q.l38#1.o2" to "プローブの長さ",
    "q.l38#1.o3" to "掘削の時間",
    "q.l38#1.e" to "下がる距離は、雪を運び出す空間を確保するためのものです。経験則であり、新しい研究は別の選択肢を示しています。",
    "q.l38#2.p" to "2023 年の雪のコンベヤ研究は、掘り始める位置について何を主張していますか。",
    "q.l38#2.o0" to "3 人以上いて空間が十分なら、プローブの位置から落線に沿って真下へ掘る",
    "q.l38#2.o1" to "常に埋没深の 1.5 倍下がる",
    "q.l38#2.o2" to "真上から掘る",
    "q.l38#2.o3" to "真横から水平に掘る",
    "q.l38#2.e" to "ずらして掘り始めると、頭の位置に届くまでの時間が延びます。研究の前提は「人手が足りていること」で、無条件に当てはめてはいけません。",
    "q.l38#3.p" to "どういう場合に、掘り始めをずらすのが勧められますか。",
    "q.l38#3.o0" to "埋没がごく浅く、脚の落ち込みが埋没深に近い場合、または人手が足りず一人で対応する場合",
    "q.l38#3.o1" to "いつでも",
    "q.l38#3.o2" to "雪が硬いとき",
    "q.l38#3.o3" to "日が暮れたとき",
    "q.l38#3.e" to "この二つの状況では、ずらすことで無駄な運搬を減らせます。それ以外では、プローブの位置から掘るほうが速いのです。",
    "q.l38#4.p" to "コンベヤの通路の幅は通常どれくらいですか。",
    "q.l38#4.o0" to "1〜2 m",
    "q.l38#4.o1" to "0.3 m",
    "q.l38#4.o2" to "3〜4 m",
    "q.l38#4.o3" to "狭ければ狭いほどよい",
    "q.l38#4.e" to "狭すぎると排雪の効率が落ち、広すぎると掘る量が急増します。1〜2 m が効率と作業量の釣り合う点です。",
    "q.l38#5.p" to "通路の勾配が約何度を下回ると、雪がプローブの位置へ転がり戻りますか。",
    "q.l38#5.o0" to "26 度",
    "q.l38#5.o1" to "10 度",
    "q.l38#5.o2" to "45 度",
    "q.l38#5.o3" to "60 度",
    "q.l38#5.e" to "26 度は研究が示した臨界値です。勾配が足りないと、かき出した雪が滑り戻り、働いた分が無駄になります。",
    "q.l38#6.p" to "三つの雪の運び方のうち、最も効率がよいのはどれですか。",
    "q.l38#6.o0" to "パドリング（雪を掃き出す）",
    "q.l38#6.o1" to "スクープ（すくう）",
    "q.l38#6.o2" to "ブロックカット（切り出す）",
    "q.l38#6.o3" to "どれも同じ",
    "q.l38#6.e" to "パドリングは雪を「掃き出す」動作で、連続性があり頻度も高い。ブロックカットは硬い雪にしか向きません。",
    "q.l38#7.p" to "掘削で指揮役を一人指定するのは何のためですか。",
    "q.l38#7.o0" to "方向、上方の雪の状態、埋没者の位置を見るため。全員が下を向いて掘るのを避ける",
    "q.l38#7.o1" to "労働を監視するため",
    "q.l38#7.o2" to "写真を記録するため",
    "q.l38#7.o3" to "人手を節約するため",
    "q.l38#7.e" to "掘削班が全員下を向くと、方向がずれ、二次雪崩にも気づけません。指揮役は唯一「顔を上げている」人です。",
    "q.l38#8.p" to "顔まで掘り着いた後、動作の順序はどう変えるべきですか。",
    "q.l38#8.o0" to "まず口と鼻を清掃して気道を確認し、次に胸と腕、最後に脚と体",
    "q.l38#8.o1" to "まず脚から",
    "q.l38#8.o2" to "まず肩を引っ張る",
    "q.l38#8.o3" to "まずザックを片づける",
    "q.l38#8.e" to "胸郭が広がって初めて換気できます。脚から始めると換気が遅れ、肩を引っ張ると脊椎を傷めることがあります。",
    "q.l38#9.p" to "「一人でも助けられる」という言葉の根拠は何ですか。",
    "q.l38#9.o0" to "研究条件下で、一人が限られた資源でコンベヤ方式を用いれば、1.5 m の埋没でも 18 分で到達できる",
    "q.l38#9.o1" to "人間には潜在能力があるから",
    "q.l38#9.o2" to "雪が軽いから",
    "q.l38#9.o3" to "埋没者が自力で脱出するから",
    "q.l38#9.e" to "硬い雪で約 13.2 cm/分、軟らかい雪で約 25.3 cm/分という掘削速度は研究のデータで、一人法を練習する価値があることを示しています。",
    "q.l38#10.p" to "硬い雪と軟らかい雪の掘削速度は、おおよそどれくらいですか。",
    "q.l38#10.o0" to "硬い雪で約 13 cm/分、軟らかい雪で約 25 cm/分",
    "q.l38#10.o1" to "どちらも 5 cm/分",
    "q.l38#10.o2" to "どちらも 50 cm/分",
    "q.l38#10.o3" to "硬い雪のほうが速い",
    "q.l38#10.e" to "この差が、雪の状態によって救助時間の見込みが変わる理由であり、ブロックカットを硬い雪だけに使う理由でもあります。",
    "q.l38#11.p" to "複数人で掘るとき、最もよくある誤りはどれですか。",
    "q.l38#11.o0" to "全員が一箇所に集まり、交代やリレーがない",
    "q.l38#11.o1" to "掘りすぎて広くなる",
    "q.l38#11.o2" to "掘るのが速すぎる",
    "q.l38#11.o3" to "シャベルを使う",
    "q.l38#11.e" to "密集すると互いの妨げになり、持続もしません。交代のリズムのほうが「一人で踏ん張る」よりずっと速いのです。",
    "q.l38#12.p" to "組織的に掘る際に必ず置く役割はどれですか。",
    "q.l38#12.o0" to "指揮役",
    "q.l38#12.o1" to "掘削と排雪",
    "q.l38#12.o2" to "安全監視役",
    "q.l38#12.o3" to "時刻と位置を記録する人",
    "q.l38#12.e" to "四つの役割で「方向・体力・安全・時間」のそれぞれに担当が付きます。一つ欠けると、どこかで制御を失います。",
    "q.l38#13.p" to "掘り出した雪を再び戻してしまう行為はどれですか。",
    "q.l38#13.o0" to "真上か上側から掘る",
    "q.l38#13.o1" to "通路の勾配が緩い（約 26 度未満）",
    "q.l38#13.o2" to "雪をプローブの上に積む",
    "q.l38#13.o3" to "落線に沿って通路を作る",
    "q.l38#13.e" to "前三者は雪を戻してしまいます。四つ目はむしろ正しいやり方です。",
    "q.l38#14.p" to "「掘り始めの位置」について、正しい説明はどれですか。",
    "q.l38#14.o0" to "従来の合言葉は埋没深の 1.5 倍、下流側から横切る",
    "q.l38#14.o1" to "Avalanche.org の簡略版は、埋没 1 m 未満なら一歩、それより深ければ二歩下がる",
    "q.l38#14.o2" to "ISSW 2023 は、人手が足りていればプローブから落線に沿って掘るとする",
    "q.l38#14.o3" to "合言葉と研究結論は完全に矛盾するので、どちらか一方しか選べない",
    "q.l38#14.e" to "三つは「原則＋二世代の経験」です。原則 → 合言葉 → 更新の順で教えれば、学習者は合言葉を迷信にしません。",
    "q.l38#15.p" to "標準的な掘削の流れを正しい順序に並べてください。",
    "q.l38#15.o0" to "下側の作業面と二次雪崩のリスクを確認する",
    "q.l38#15.o1" to "掘り始めの位置から V 字の通路をプローブへ向けて作る",
    "q.l38#15.o2" to "リレーで排雪し、交代する",
    "q.l38#15.o3" to "顔に到達したら、まず口と鼻を清掃する",
    "q.l38#15.e" to "順序の核は「まず安全、次に効率、最後に気道優先」です。",
    "q.l38#16.p" to "「顔に到達した後」の順序を並べてください。",
    "q.l38#16.o0" to "口と鼻の雪と氷片を清掃し、気道を確認する",
    "q.l38#16.o1" to "胸と腕の周りの雪を除き、胸郭が広がるようにする",
    "q.l38#16.o2" to "脚と体の残りの部分を出す",
    "q.l38#16.o3" to "蘇生のルールに沿って処置し、搬送を手配する",
    "q.l38#16.e" to "この順序は「掘り終えてから助ける」の逆ですが、こちらが正しい。換気の窓は数分しかありません。",
    "q.l38#17.p" to "雪のコンベヤ通路の臨界勾配は約 ______ 度です。",
    "q.l38#17.a0" to "26",
    "q.l38#17.e" to "この角度を下回ると、雪塊がプローブの位置へ転がり戻り、排雪の効率が大きく落ちます。",
    "q.l38#18.p" to "従来の合言葉では、プローブから斜面に沿って約 ______ 倍の埋没深だけ下がって掘り始めます。",
    "q.l38#18.a0" to "1.5",
    "q.l38#18.a1" to "1,5",
    "q.l38#18.e" to "1.5 倍は経験則です。人手が十分なら、プローブの位置から落線に沿って掘り始めるほうを優先して考えます。",
    "q.l38#19.p" to "バディ救助の目標時間は ______ 分で接触、18 分で掘り出すことです。",
    "q.l38#19.a0" to "10",
    "q.l38#19.e" to "10 / 18 は訓練と振り返りのための内部指標で、「どこで遅れたか」を特定するために使います。",
    "q.l38#20.p" to "雪の運び方と、その適した条件を対応させてください。",
    "q.l38#20.l0" to "パドリング（掃き出す）",
    "q.l38#20.l1" to "スクープ（すくう）",
    "q.l38#20.l2" to "ブロックカット（切り出す）",
    "q.l38#20.l3" to "コンベヤ（リレー）",
    "q.l38#20.r0" to "最も効率的で、多くの緩い雪に向く",
    "q.l38#20.r1" to "その次。通路から雪を送り出すのに向く",
    "q.l38#20.r2" to "最も遅い。硬い雪でのみ使う",
    "q.l38#20.r3" to "複数人で協力するときの全体的な組織の仕方",
    "q.l38#20.e" to "効率の順序が「まずパドリング、次にスクープ、硬い雪だけブロック」を決めます。コンベヤは手法ではなく組織の仕方です。",
    "q.l38#21.p" to "よくある誤りと、その結果を対応させてください。",
    "q.l38#21.l0" to "上側から掘る",
    "q.l38#21.l1" to "通路の勾配が緩い",
    "q.l38#21.l2" to "人に当たってすぐ体を引っ張る",
    "q.l38#21.l3" to "当たった後にプローブを抜く",
    "q.l38#21.r0" to "雪塊が顔へ戻り、遅くて危険",
    "q.l38#21.r1" to "雪が戻り、同じ雪を何度も運ぶ",
    "q.l38#21.r2" to "脊椎損傷を悪化させ、口と鼻へ雪を押し込む",
    "q.l38#21.r3" to "位置と深さの基準を失う",
    "q.l38#21.e" to "四つの誤りはどれもよく起きますが、どれも「事前に練習しておく」ことで避けられます。",
    "q.l38#22.p" to "雪が硬く、隊が三人しかいません。掘り始めの位置はどう決めますか。",
    "q.l38#22.o0" to "プローブの位置から落線に沿って掘り始め、硬い雪の区間はブロックカットで切り開く",
    "q.l38#22.o1" to "埋没深の 3 倍下がる",
    "q.l38#22.o2" to "真上から掘る",
    "q.l38#22.o3" to "装備を待つ",
    "q.l38#22.e" to "人手が足りていれば落線に沿います。硬い雪が変えるのは手法（ブロックカット）だけで、原則は変わりません。",
    "q.l38#23.p" to "「全員で一斉に猛スピードで掘る」のが、かえって速くないのはなぜですか。",
    "q.l38#23.o0" to "密集して互いの妨げになり、持続せず、上方の雪の状態を見る人もいなくなるから",
    "q.l38#23.o1" to "人が多いと暑くなるから",
    "q.l38#23.o2" to "シャベルが足りないから",
    "q.l38#23.o3" to "指揮がないから",
    "q.l38#23.e" to "掘削はきわめて強度の高い運動で、数分で力尽きます。交代・指揮・リレーがあって初めて、人力が速度に変わります。",
    "q.l38#24.p" to "救助中、埋没者のそばに大きな硬い雪塊がありました。正しい対応はどれですか。",
    "q.l38#24.o0" to "まず気道への通路を空ける。大きな塊を動かすために換気を遅らせない",
    "q.l38#24.o1" to "まず大きな塊をどける",
    "q.l38#24.o2" to "ピッケルで砕く",
    "q.l38#24.o3" to "避けて通る",
    "q.l38#24.e" to "大きな塊は後で構いません。気道の窓は数分しかなく、「現場をきれいにすること」より優先されます。",
    "q.l38#25.p" to "現場にシャベルが一本しかないとき、最も優先すべきはどれですか。",
    "q.l38#25.o0" to "体力のある人が掘り、他の人は手やスノーボードで雪を押し出し、交代する",
    "q.l38#25.o1" to "一人で最後まで掘る",
    "q.l38#25.o2" to "二本目のシャベルを待つ",
    "q.l38#25.o3" to "ザックで代用する",
    "q.l38#25.e" to "一人掘りの正しいやり方が「限られた資源でのコンベヤ」です。一人が掘り、他の人が雪を外へ送り出します。",
    "q.l38#26.p" to "振り返りで「接触まで 14 分かかった」と分かりました。最も見直すべきはどの段階ですか。",
    "q.l38#26.o0" to "捜索と定位の段階。四段階のどこが遅かったか",
    "q.l38#26.o1" to "掘削の段階",
    "q.l38#26.o2" to "救助要請の段階",
    "q.l38#26.o3" to "装備の購入",
    "q.l38#26.e" to "接触までの時間は捜索と定位で決まり、掘削が決めるのは「掘り出しまでの時間」です。二つの指標は分けて見ます。",
    "q.m14#17.p" to "登山の判断における「サンクコスト」の典型的な現れはどれですか。",
    "q.m14#17.o0" to "これだけ金と時間を使ったのだから、無駄にはできない",
    "q.m14#17.o1" to "天気予報が当たらない",
    "q.m14#17.o2" to "装備が足りない",
    "q.m14#17.o3" to "同行者が遅い",
    "q.m14#17.e" to "投入した分だけ諦めにくくなります。しかし支払ったコストは続けることで回収されるわけではなく、新しいリスクが増えるだけです。",
    "q.m14#18.p" to "「集団思考（グループシンキング）」が最も起きやすいのはどんな状況ですか。",
    "q.m14#18.o0" to "結束が強く、反対意見が出ず、リーダーが早く立場を示したとき",
    "q.m14#18.o1" to "隊の意見が大きく分かれているとき",
    "q.m14#18.o2" to "人数が少ないとき",
    "q.m14#18.o3" to "天候が悪いとき",
    "q.m14#18.e" to "結束はよいことですが、異論を抑え込みます。最も若い人から先に発言させる、反対役を指名する、といった対処がよく使われます。",
    "q.m14#19.p" to "「確証バイアス」とは何ですか。",
    "q.m14#19.o0" to "自分の判断を支える情報だけを探し、反対の証拠を無視すること",
    "q.m14#19.o1" to "情報を覚えていられないこと",
    "q.m14#19.o2" to "慎重すぎること",
    "q.m14#19.o3" to "他人に依存すること",
    "q.m14#19.e" to "「今日は上がれる」と思えば、よい兆候ばかり目に入ります。進んで反例を探すことだけが解毒剤です。",
    "q.m14#20.p" to "重大な判断にチェックリストを使うのはなぜですか。",
    "q.m14#20.o0" to "疲労とプレッシャーの下では項目が抜ける。リストは「覚えている」を「一つずつ確認する」に変えるから",
    "q.m14#20.o1" to "記録を残すため",
    "q.m14#20.o2" to "専門家らしく見せるため",
    "q.m14#20.o3" to "規則だから",
    "q.m14#20.e" to "チェックリストの役割は判断の代替ではなく、判断に必要な情報が揃っていることの保証です。",
    "q.m14#21.p" to "行程における「アンカリング」の例はどれですか。",
    "q.m14#21.o0" to "「キャンプまで 6 時間」という計画を基準にしてしまい、実際の路面状況を無視する",
    "q.m14#21.o1" to "ガイドを信じる",
    "q.m14#21.o2" to "地図を見る",
    "q.m14#21.o3" to "体温を測る",
    "q.m14#21.e" to "一度アンカーができると、その後の判断はすべてそれを基準に調整されます。計画値ではなく実際の進み具合を根拠にします。",
    "q.m14#22.p" to "判断を記録する（時刻・根拠・結論）ことの価値は何ですか。",
    "q.m14#22.o0" to "振り返りに根拠が生まれ、隊が同じ事実を共有できる",
    "q.m14#22.o1" to "報告書のため",
    "q.m14#22.o2" to "保険のため",
    "q.m14#22.o3" to "本を書くため",
    "q.m14#22.e" to "記録がなければ、振り返りは「それぞれの言い分」になります。時間軸を書いておけば、どの時点でもっと早く決められたかが見えます。",
    "q.m14#23.p" to "「専門家ハロー」は具体的にどんなリスクを生みますか。",
    "q.m14#23.o0" to "明らかな誤りに誰も口を出せず、その誤りがそのまま実行される",
    "q.m14#23.o1" to "専門家が疲れる",
    "q.m14#23.o2" to "専門家の費用が高い",
    "q.m14#23.o3" to "専門家がルートを知らない",
    "q.m14#23.e" to "ハローが抑え込むのは「情報が上がってくること」です。隊で最も危険な状態は、誰も分かっていないことではなく、誰も言えないことです。",
    "q.m17#16.p" to "高所キャンプ間の「物資のローテーション」の目的は何ですか。",
    "q.m17#16.o0" to "各キャンプにちょうど足りる量を置き、どこかに溜まりどこかで切れるのを避ける",
    "q.m17#16.o1" to "重量を減らすため",
    "q.m17#16.o2" to "集計を楽にするため",
    "q.m17#16.o3" to "規則を満たすため",
    "q.m17#16.e" to "遠征の物資は「区間ごとの配給」です。ローテーション表がなければ、出発直前に高所キャンプのガスが足りないと気づくのが最もよくある結末です。",
    "q.m17#17.p" to "キャンプの燃料は何を基準に見積もりますか。",
    "q.m17#17.o0" to "人数 × 日数 × 1 人 1 日あたりの使用量（雪を溶かす分が最大）",
    "q.m17#17.o1" to "ガス缶の本数",
    "q.m17#17.o2" to "重量",
    "q.m17#17.o3" to "経験",
    "q.m17#17.e" to "雪を溶かしてお湯を沸かすのが、高所で最大の燃料消費です。見積もりは「理想的な状態」ではなく「最も寒い日」を基準にします。",
    "q.m17#18.p" to "強風下でテントを補強するときの要点はどれですか。",
    "q.m17#18.o0" to "ガイラインの角度、風上側の固定点、スカートの雪による埋設",
    "q.m17#18.o1" to "テントの色",
    "q.m17#18.o2" to "インナーのファスナー",
    "q.m17#18.o3" to "グラウンドシートの厚さ",
    "q.m17#18.e" to "テントが壊れるのは生地が破れる前の、どこかの固定点の脱落がほとんどです。風上側のラインを二重にし、スカートを雪塊で押さえるのが標準です。",
    "q.m17#19.p" to "雪の斜面にスノーコーブを掘る利点とリスクは、それぞれ何ですか。",
    "q.m17#19.o0" to "風に強く暖かい。ただし崩落と一酸化炭素のリスクがある",
    "q.m17#19.o1" to "テントが要らない。ただし寒い",
    "q.m17#19.o2" to "便利。ただし違法",
    "q.m17#19.o3" to "リスクはない",
    "q.m17#19.e" to "スノーコーブには換気口と天井の厚さの判断が必要です。密閉したコーブにストーブを入れるのは、一酸化炭素中毒の典型例です。",
    "q.m17#20.p" to "テント内でストーブを使うとき、最も警戒すべきは何ですか。",
    "q.m17#20.o0" to "一酸化炭素中毒と火災",
    "q.m17#20.o1" to "湿気",
    "q.m17#20.o2" to "酸素不足以外の低温",
    "q.m17#20.o3" to "テントの変形",
    "q.m17#20.e" to "一酸化炭素は無色無臭で、症状は高山病によく似ています。換気を保ち、できるだけ前室かテントの外で操作します。",
    "q.m17#21.p" to "高所キャンプのごみ処理の原則はどれですか。",
    "q.m17#21.o0" to "すべて下山時に持ち帰る。高所キャンプで埋めたり燃やしたりしない",
    "q.m17#21.o1" to "雪の中に埋める",
    "q.m17#21.o2" to "燃やす",
    "q.m17#21.o3" to "次の隊のために残す",
    "q.m17#21.e" to "高所では分解が極端に遅く、埋めても燃やしても雪解け後にすべて露出します。持ち帰るのが唯一の適切な方法です。",
    "q.m17#22.p" to "雪を溶かして水を作るとき、効率を上げる方法はどれですか。",
    "q.m17#22.o0" to "少量の水を先に入れてから雪を加え、強火で沸かす。空焚きを避ける",
    "q.m17#22.o1" to "雪をいっぱいに入れる",
    "q.m17#22.o2" to "弱火でゆっくり",
    "q.m17#22.o3" to "冷水で溶かす",
    "q.m17#22.e" to "空焚きは鍋底を焦がし、効率も極端に悪くなります。「水を少量入れてから強火」で、燃料と時間を大きく節約できます。",
    "q.m17#23.p" to "高所キャンプでの睡眠標高の組み方はどうすべきですか。",
    "q.m17#23.o0" to "計画どおりにローテーションし、高所キャンプで連続して何泊もしない",
    "q.m17#23.o1" to "高ければ高いほどよい",
    "q.m17#23.o2" to "ずっと最高所のキャンプで寝る",
    "q.m17#23.o3" to "任意でよい",
    "q.m17#23.e" to "ローテーションは順応と回復の両立を狙います。高所で連続して寝ると疲労が蓄積し、かえって全体のペースが落ちます。",
    "q.l39#0.p" to "リーダーシップの最も正確な定義はどれですか。",
    "q.l39#0.o0" to "他者に影響を与え、隊が目標を共に達成したくなるようにする行為",
    "q.l39#0.o1" to "肩書きのある人が言うこと",
    "q.l39#0.o2" to "体力が最もある人が先導すること",
    "q.l39#0.o3" to "最も年長の人が決めること",
    "q.l39#0.e" to "リーダーシップを役職ではなく行為と見れば、隊には「声を上げる人」が増えます。それが安全上の余裕の一部になります。",
    "q.l39#1.p" to "ハードスキルとソフトスキルの役割分担はどれですか。",
    "q.l39#1.o0" to "ハードスキルはできるかどうかを、ソフトスキルは隊が一緒にやりたいかを決める",
    "q.l39#1.o1" to "ハードスキルのほうが重要",
    "q.l39#1.o2" to "ソフトスキルは社交辞令にすぎない",
    "q.l39#1.o3" to "両者は無関係",
    "q.l39#1.e" to "技術的にはできても隊が実行しなければ、やっていないのと同じです。高所では実行率をソフトスキルが決めることが多いのです。",
    "q.l39#2.p" to "「責任の三層」とは何を指しますか。",
    "q.l39#2.o0" to "行動、思考、感情",
    "q.l39#2.o1" to "計画、実行、振り返り",
    "q.l39#2.o2" to "リーダー、サブリーダー、隊員",
    "q.l39#2.o3" to "登攀、登頂、下山",
    "q.l39#2.e" to "行動だけを見ていると、判断の仕方と感情の状態を取りこぼします。繰り返し起きる問題の根は、第二・第三層にあることが多いのです。",
    "q.l39#3.p" to "対立の「氷山モデル」が説明しているのは何ですか。",
    "q.l39#3.o0" to "水面より上は立場、水面より下はニーズ",
    "q.l39#3.o1" to "対立はすべて性格から来る",
    "q.l39#3.o2" to "対立は解決できない",
    "q.l39#3.o3" to "沈黙は対立がないこと",
    "q.l39#3.e" to "「絶対に登頂する」は立場で、その下には「仲間に失望されたくない」があるかもしれません。ニーズに応えれば、立場に余地が生まれます。",
    "q.l39#4.p" to "「専門家ハロー」のリスクはどれですか。",
    "q.l39#4.o0" to "自信と装備の専門性を能力と取り違え、明らかな誤りに誰も口を出せなくなる",
    "q.l39#4.o1" to "専門家の費用が高い",
    "q.l39#4.o2" to "専門家が言うことを聞かない",
    "q.l39#4.o3" to "専門家の体力が低い",
    "q.l39#4.e" to "ハローは疑問を抑え込みます。隊で最も危険な状態は、誰も分かっていないことではなく、誰も「待って、ここは違う」と言えないことです。",
    "q.l39#5.p" to "フォロワーの最も重要な役割は何ですか。",
    "q.l39#5.o0" to "質問し、フィードバックし、止めるべきときに明確に止めると言う",
    "q.l39#5.o1" to "完全に従う",
    "q.l39#5.o2" to "迷惑をかけない",
    "q.l39#5.o3" to "沈黙を保つ",
    "q.l39#5.e" to "「止める」をリーダーの特権ではなく全員の権限にします。この点は出発前に明確に与えておきます。",
    "q.l39#6.p" to "ターンアラウンドタイム（折り返し時刻）はいつ決めるべきですか。",
    "q.l39#6.o0" to "出発前に決め、全員に知らせておく",
    "q.l39#6.o1" to "頂上の手前で決める",
    "q.l39#6.o2" to "気分で決める",
    "q.l39#6.o3" to "最も速い人が決める",
    "q.l39#6.e" to "山の上で、疲労と目標へのプレッシャーの下で決めた締め切りは、ほぼ必ず先延ばしされます。出発前に決めてこそ拘束力を持ちます。",
    "q.l39#7.p" to "リーダーが「役割を濫用する」典型はどれですか。",
    "q.l39#7.o0" to "役職で判断を押し切り、疑問を不服従とみなす",
    "q.l39#7.o1" to "意見を聞く",
    "q.l39#7.o2" to "判断の根拠を公開する",
    "q.l39#7.o3" to "自分が不確かだと認める",
    "q.l39#7.e" to "抑え込んだ直接の結果は、情報が上がってこなくなることです。リーダーにとって最も重要な入力は、まさに「言える人」から来ます。",
    "q.l39#8.p" to "隊である人がずっと黙っています。最もありそうな理由はどれですか。",
    "q.l39#8.o0" to "言っても意味がないと思っている、または関係が悪くなるのを恐れている",
    "q.l39#8.o1" to "考えがない",
    "q.l39#8.o2" to "体力が足りない",
    "q.l39#8.o3" to "話が理解できない",
    "q.l39#8.e" to "沈黙はたいてい「表明のコストが高すぎる」結果です。リーダーはそのコストを下げる側に動きます。たとえば最も若い人から先に聞く、などです。",
    "q.l39#9.p" to "対立を解く最初の一歩は通常どれですか。",
    "q.l39#9.o0" to "信頼を作る。まず相手に「聞いてもらえた」と感じてもらう",
    "q.l39#9.o1" to "理屈で説得する",
    "q.l39#9.o2" to "投票する",
    "q.l39#9.o3" to "人を替える",
    "q.l39#9.e" to "信頼がなければ、理屈は責め言葉として聞こえます。まず感情を受け止め、その後に事実と案を話します。",
    "q.l39#10.p" to "「隊の目標を達成する」ことと「全員の安全」が衝突したとき、優先順位はどれですか。",
    "q.l39#10.o0" to "安全が優先。目標は次回にできる",
    "q.l39#10.o1" to "目標が優先",
    "q.l39#10.o2" to "投票で決める",
    "q.l39#10.o3" to "費用を出した人が決める",
    "q.l39#10.e" to "目標はやり直せますが、人はやり直せません。商業隊では利益の圧力でこの順序が歪みやすいので、とくに注意が要ります。",
    "q.l39#11.p" to "ソフトスキルの表れに当たるものはどれですか。",
    "q.l39#11.o0" to "判断の根拠を明確に伝える",
    "q.l39#11.o1" to "プレッシャーの下でも対話を保つ",
    "q.l39#11.o2" to "黙っている人に自分から意見を聞く",
    "q.l39#11.o3" to "最も速く登頂する",
    "q.l39#11.e" to "前三者はすべて「情報を流すこと」に関わります。速さは能力であって、リーダーシップではありません。",
    "q.l39#12.p" to "「専門家ハロー」のリスクを下げる方法はどれですか。",
    "q.l39#12.o0" to "新人が質問しやすいようにする",
    "q.l39#12.o1" to "判断のときに理由を説明する",
    "q.l39#12.o2" to "反対役を一人指名する",
    "q.l39#12.o3" to "最も経験のある人だけに発言させる",
    "q.l39#12.e" to "前三者は「疑問を出すことの正当性」を作ります。最後の一つはむしろハローを増幅します。",
    "q.l39#13.p" to "フォロワーの正当な行動はどれですか。",
    "q.l39#13.o0" to "違う意見を出す",
    "q.l39#13.o1" to "判断の説明を求める",
    "q.l39#13.o2" to "危険だと考えるとき前進を拒む",
    "q.l39#13.o3" to "陰で不満を言い、表では言わない",
    "q.l39#13.e" to "陰口は判断を変えず、不信だけを積み上げます。前の三つが「建設的な不服従」です。",
    "q.l39#14.p" to "1 回の対立の処理を正しい順序に並べてください。",
    "q.l39#14.o0" to "まず相手に最後まで話させ、自分が何を聞いたかを確認する",
    "q.l39#14.o1" to "立場とニーズを切り分ける",
    "q.l39#14.o2" to "選べる案を示し、それぞれの代償を伝える",
    "q.l39#14.o3" to "合意し、復唱して確認する",
    "q.l39#14.e" to "順序で最も重要なのは二番目です。ニーズを捉え損ねると、案は「お互い少しずつ譲る」だけになり、すぐ再発します。",
    "q.l39#15.p" to "高リスクの判断の流れを並べてください。",
    "q.l39#15.o0" to "目標と譲れない線を明確にする",
    "q.l39#15.o1" to "選択肢とそれぞれの代償を挙げる",
    "q.l39#15.o2" to "起こりやすさと結果の積で評価する",
    "q.l39#15.o3" to "締め切りを決めて実行する",
    "q.l39#15.o4" to "新しい情報に応じて修正する",
    "q.l39#15.e" to "これは九段階の手順の骨格です。本当の価値は四番目にあり、「いつ必ず引き返すか」を事前の数字に変えます。",
    "q.l39#16.p" to "判断の前に決めておく折り返し時刻は、英語で ______ time とよく呼ばれます。",
    "q.l39#16.a0" to "turnaround",
    "q.l39#16.e" to "「決意」を「規則」に変える道具です。書き出し、口に出して初めて拘束力を持ちます。",
    "q.l39#17.p" to "責任の三層は、行動、思考、そして ______ です。",
    "q.l39#17.a0" to "感情",
    "q.l39#17.a1" to "気持ち",
    "q.l39#17.e" to "三層で最も見落とされやすいのが「感情」で、しかも最初に異変が出る信号でもあります。",
    "q.l39#18.p" to "役割と、その中核の責務を対応させてください。",
    "q.l39#18.l0" to "リーダー",
    "q.l39#18.l1" to "サブリーダー／ガイド",
    "q.l39#18.l2" to "隊員",
    "q.l39#18.l3" to "安全監視役",
    "q.l39#18.r0" to "目標と譲れない線を定め、判断が理解できる形にする",
    "q.l39#18.r1" to "技術的な操作を実行し、現場の情報を返す",
    "q.l39#18.r2" to "質問し、フィードバックし、必要なら止めると言う",
    "q.l39#18.r3" to "環境のリスク監視に専念し、操作には加わらない",
    "q.l39#18.e" to "四つの役割で「情報・実行・均衡」が構成されます。均衡を欠くと、判断は一人の独断になります。",
    "q.l39#19.p" to "対立の表れと、その水面下のニーズを対応させてください。",
    "q.l39#19.l0" to "「絶対に登頂する」",
    "q.l39#19.l1" to "「なんでもいい、任せる」",
    "q.l39#19.l2" to "「私は大丈夫」",
    "q.l39#19.l3" to "「あいつはいつも足を引っ張る」",
    "q.l39#19.r0" to "仲間に軽く見られたくない。認められたい",
    "q.l39#19.r1" to "判断の責任を負いたくない。守られたい",
    "q.l39#19.r2" to "足手まといになりたくない。気にかけてほしい",
    "q.l39#19.r3" to "進行に不安がある。確かさがほしい",
    "q.l39#19.e" to "四つの表れは四つのニーズに対応します。ニーズに応えて初めて、行動が変わり得ます。",
    "q.l39#20.p" to "隊で最も経験のある人が「この道は歩いた、問題ない」と言いましたが、地図では前方がアイスフォール帯です。どうすべきですか。",
    "q.l39#20.o0" to "一緒に地図と地形を照合し、事実で経験を校正する",
    "q.l39#20.o1" to "そのまま信じる",
    "q.l39#20.o2" to "その場で否定する",
    "q.l39#20.o3" to "別行動にする",
    "q.l39#20.e" to "経験は価値ある入力であって結論ではありません。地図と現場の地形で校正すれば、相手を尊重しつつ盲従も避けられます。",
    "q.l39#21.p" to "ある隊員が何度も「どれでもいいです」と言います。最も妥当な対応はどれですか。",
    "q.l39#21.o0" to "開かれた質問ではなく、具体的な選択肢を示して選ばせる",
    "q.l39#21.o1" to "本当にどれでもよいと受け取る",
    "q.l39#21.o2" to "もう聞かない",
    "q.l39#21.o3" to "代わりに決めて事後に知らせる",
    "q.l39#21.e" to "「どれでもいい」はたいてい「選択の結果を負いたくない」です。具体的な選択肢は表明のコストを下げ、情報が出てきます。",
    "q.l39#22.p" to "リーダーが撤退を決めた後、最も明確にすべきことは何ですか。",
    "q.l39#22.o0" to "根拠（何を見たか）、境界（どんな条件なら再評価するか）、次の段取り",
    "q.l39#22.o1" to "撤退しないとだめだ、とだけ言う",
    "q.l39#22.o2" to "感情だけを語る",
    "q.l39#22.o3" to "説明しない",
    "q.l39#22.e" to "根拠を説明すれば、隊は「従う」を「理解する」に変えられます。理解した人だけが、次に自分から情報を出します。",
    "q.l39#23.p" to "「上昇を続けるかを投票で決める」が技術的に頼りにならないのはなぜですか。",
    "q.l39#23.o0" to "多くの人が判断に必要な情報を持っておらず、プレッシャーが表明を歪めるから",
    "q.l39#23.o1" to "投票は時間がかかるから",
    "q.l39#23.o2" to "人数が足りないから",
    "q.l39#23.o3" to "リーダーが反対するから",
    "q.l39#23.e" to "投票は判断を「意見の分布」に変えますが、高所の判断は情報と基準に依存します。意見を集めるのはよいとしても、判断には根拠が要ります。",
    "q.l39#24.p" to "隊に「誰も悪者になりたがらない」沈黙が生まれました。最も有効な打開策はどれですか。",
    "q.l39#24.o0" to "リーダーがまず自分の懸念を口に出し、議論できる話題にする",
    "q.l39#24.o1" to "名指しで叱る",
    "q.l39#24.o2" to "待ち続ける",
    "q.l39#24.o3" to "説明せずに撤退する",
    "q.l39#24.e" to "最初に懸念を口にする人が出ると、他の人の表明コストが大きく下がります。リーダーはその役に最も適しています。",
    "q.l39#25.p" to "リーダー自身の判断の誤りが危険を招いた場合、最も優先すべきはどれですか。",
    "q.l39#25.o0" to "誤りを公開して振り返り、何を変えたかを説明する。曖昧にしない",
    "q.l39#25.o1" to "触れない",
    "q.l39#25.o2" to "天候のせいにする",
    "q.l39#25.o3" to "話題を変える",
    "q.l39#25.e" to "誤りを認めることは信頼を下げるのではなく上げます。曖昧にすれば、隊は「隠すこと」を学びます。それこそが本当の危険です。",
    "q.l40#0.p" to "高所での食事の第一原則はどれですか。",
    "q.l40#0.o0" to "炭水化物の摂取を確保する。食べられること自体が最優先",
    "q.l40#0.o1" to "高タンパクを優先する",
    "q.l40#0.o2" to "高脂肪を優先する",
    "q.l40#0.o3" to "食べる量を減らして負担を軽くする",
    "q.l40#0.e" to "炭水化物は供給が速く酸素消費も少ない、高所で最も「割のよい」エネルギー源です。食べられないときは、まず炭水化物をどう入れるかを考えます。",
    "q.l40#1.p" to "三大栄養素のうち、エネルギー密度が最も高いのはどれですか。",
    "q.l40#1.o0" to "脂肪",
    "q.l40#1.o1" to "炭水化物",
    "q.l40#1.o2" to "タンパク質",
    "q.l40#1.o3" to "三つとも同じ",
    "q.l40#1.e" to "脂肪は約 9 kcal/g で、炭水化物やタンパク質の二倍以上です。高所の行動食がナッツや油脂を好む理由でもあります。",
    "q.l40#2.p" to "「山に上がってから脂肪燃焼に切り替える」という考えの問題は何ですか。",
    "q.l40#2.o0" to "脂肪を使う割合は長期的な訓練でしか上がらず、短期間では切り替わらない",
    "q.l40#2.o1" to "脂肪はおいしくない",
    "q.l40#2.o2" to "脂肪は重い",
    "q.l40#2.o3" to "脂肪は体を冷やす",
    "q.l40#2.e" to "代謝の適応は週・月単位です。事前の訓練で脂肪利用は高められますが、山の上でその場で起きることは期待できません。",
    "q.l40#3.p" to "高所で食欲が落ちたとき、最も有効な戦略はどれですか。",
    "q.l40#3.o0" to "少量を頻回に、エネルギー密度が高く口に入れやすいものを選ぶ",
    "q.l40#3.o1" to "三度の食事を無理にでも詰め込む",
    "q.l40#3.o2" to "スポーツドリンクだけで済ませる",
    "q.l40#3.o3" to "空腹になるまで待つ",
    "q.l40#3.e" to "食欲が落ちているとき「一度に多く」はほぼ不可能です。総量を何回にも分けるのが、唯一続けられる方法です。",
    "q.l40#4.p" to "行動食のうち「歩きながら食べられる」ものの主な役割は何ですか。",
    "q.l40#4.o0" to "止まらずに補給してリズムを保つ",
    "q.l40#4.o1" to "満腹感を与える",
    "q.l40#4.o2" to "タンパク質を補う",
    "q.l40#4.o3" to "食事の代わりにする",
    "q.l40#4.e" to "止まらないと食べられないものは、リズムを切ります。ジェルやグミ、エナジーバーの価値は「移動を中断させない」ことにあります。",
    "q.l40#5.p" to "脱水は食事にどう影響しますか。",
    "q.l40#5.o0" to "食欲と判断力の両方を弱め、エネルギーの不足を埋めにくくする",
    "q.l40#5.o1" to "影響しない",
    "q.l40#5.o2" to "食欲が増す",
    "q.l40#5.o3" to "喉の渇きだけに影響する",
    "q.l40#5.e" to "水が足りないと食べる気が起きず、「あとどれくらい足りないか」の判断も狂います。補水と補給は一緒に組みます。",
    "q.l40#6.p" to "BCAA（分岐鎖アミノ酸）について、正しい姿勢はどれですか。",
    "q.l40#6.o0" to "アンモニア代謝との関連を示す研究はあるが証拠は限られ、総カロリーの代わりにはならない",
    "q.l40#6.o1" to "食事を完全に代替できる",
    "q.l40#6.o2" to "多ければ多いほどよい",
    "q.l40#6.o3" to "まったく無意味",
    "q.l40#6.e" to "サプリメントの位置づけは「限界的な最適化」です。総カロリーが足りなければ、どんな補剤も埋め合わせはできません。",
    "q.l40#7.p" to "高所で1日の必要エネルギーがかえって増えるのはなぜですか。",
    "q.l40#7.o0" to "寒冷、荷物、低酸素によって安静時の消費と呼吸仕事量が増えるから",
    "q.l40#7.o1" to "標高が高いと重力が大きいから",
    "q.l40#7.o2" to "よく眠れないから",
    "q.l40#7.o3" to "緊張しているから",
    "q.l40#7.e" to "需要が増えるのに食欲は落ちる。これが高所のエネルギー不足の出所です。戦略はこの矛盾を中心に組み立てます。",
    "q.l40#8.p" to "アタック日の補給として妥当なのはどれですか。",
    "q.l40#8.o0" to "出発前に炭水化物中心の温かい食事をとり、行動中は 45〜60 分ごとに補給する",
    "q.l40#8.o1" to "負担を減らすため出発前は食べない",
    "q.l40#8.o2" to "登頂してから食べる",
    "q.l40#8.o3" to "コーヒーだけで一日をしのぐ",
    "q.l40#8.e" to "空腹で出発すると、最初の 2 時間でグリコーゲンを使い切ります。少量頻回だけが 10 時間以上を持たせられます。",
    "q.l40#9.p" to "高所での温かい食事の意味はどれですか。",
    "q.l40#9.o0" to "熱量・水分・精神的な支えを同時に与え、しかも受け入れやすい",
    "q.l40#9.o1" to "単なる儀式",
    "q.l40#9.o2" to "タンパク質の補給",
    "q.l40#9.o3" to "食物繊維の消化を助ける",
    "q.l40#9.e" to "温かい食事は三つの問題を同時に解きます。エネルギー、水分、士気。キャンプの炊事が「乾き物だけ」で代替できない理由です。",
    "q.l40#10.p" to "隊員が二日続けて食べられないとき、最も警戒すべきは何ですか。",
    "q.l40#10.o0" to "エネルギー枯渇による低体温と判断力の低下、そして高山病悪化のサインかもしれないこと",
    "q.l40#10.o1" to "痩せること",
    "q.l40#10.o2" to "便秘になること",
    "q.l40#10.o3" to "ビタミンが不足すること",
    "q.l40#10.e" to "「食べられない」は高所では原因でもあり症状でもあります。改善しなければ高山病として評価し、ただ「もっと食べろ」と言うだけでは済みません。",
    "q.l40#11.p" to "高所の行動食を選ぶ基準はどれですか。",
    "q.l40#11.o0" to "エネルギー密度が高い",
    "q.l40#11.o1" to "低温でも硬くならず、噛みやすい",
    "q.l40#11.o2" to "大量の水がなくても飲み込める",
    "q.l40#11.o3" to "体積が大きいほどよい",
    "q.l40#11.e" to "低温でチョコレートやエナジーバーは硬くなり、-20 ℃ ではほとんど噛めません。体積が大きいと荷物を占め、食べ切れずにもなります。",
    "q.l40#12.p" to "補水と補給について、正しいやり方はどれですか。",
    "q.l40#12.o0" to "出発前に十分に飲む",
    "q.l40#12.o1" to "行動中は少量ずつ頻回に飲む",
    "q.l40#12.o2" to "経口補水液とエネルギー補給を組み合わせる",
    "q.l40#12.o3" to "キャンプに着いてから一度に補う",
    "q.l40#12.e" to "一度に大量の水を飲むと胃腸の負担が増え、一日の不足も埋まりません。分けて補うことが有効です。",
    "q.l40#13.p" to "山上での摂取量を実際に増やせる方法はどれですか。",
    "q.l40#13.o0" to "普段から好きな味を持って行く",
    "q.l40#13.o1" to "小分けにして、すぐ取り出せる位置に置く",
    "q.l40#13.o2" to "食感の違うものをいくつか用意して交代させる",
    "q.l40#13.o3" to "最も高カロリーの単一品だけを持って行く",
    "q.l40#13.e" to "高所では「食べ物嫌悪」がよく起きます。同じ味を数日続けると喉を通らなくなります。多様性と慣れた味は実用的な戦略です。",
    "q.l40#14.p" to "一日の補給のリズムを妥当な順序に並べてください。",
    "q.l40#14.o0" to "起床後にまず水分をとり、朝食は炭水化物中心",
    "q.l40#14.o1" to "出発後は 45〜60 分ごとに少量補給",
    "q.l40#14.o2" to "長い登攀の前に一度多めに補給",
    "q.l40#14.o3" to "キャンプ到着後に温かい食事と水分を補う",
    "q.l40#14.e" to "リズムの要点は「空腹を待たない」ことです。腹が減った時点でグリコーゲンは底を突いており、そこから補っても効くまで 20〜30 分かかります。",
    "q.l40#15.p" to "「食べられない」への対応の順序として正しいのはどれですか。",
    "q.l40#15.o0" to "まず補水し、脱水かどうかを確認する",
    "q.l40#15.o1" to "口に入れやすい高エネルギーの食べ物に変え、少量頻回にする",
    "q.l40#15.o2" to "高山病の症状がないか評価する",
    "q.l40#15.o3" to "改善しなければ下山を検討する",
    "q.l40#15.e" to "脱水は可逆な第一段階です。脱水を除外しても食べられないなら、説得を続けるのではなく病状として評価します。",
    "q.l40#16.p" to "脂肪のエネルギー密度は約 ______ kcal/g です。",
    "q.l40#16.a0" to "9",
    "q.l40#16.e" to "炭水化物とタンパク質は約 4 kcal/g。この差が、高所でナッツや油脂、チョコレートが好まれる理由です。",
    "q.l40#17.p" to "行動中は ______ 分ごとに補給するのが勧められます（数を一つ）。",
    "q.l40#17.a0" to "45〜60",
    "q.l40#17.a1" to "45-60",
    "q.l40#17.a2" to "45",
    "q.l40#17.a3" to "60",
    "q.l40#17.a4" to "50",
    "q.l40#17.e" to "少量頻回は大量をまとめてとるより有効で、胃腸の不快も起こりにくいです。",
    "q.l40#18.p" to "栄養素とその役割を対応させてください。",
    "q.l40#18.l0" to "炭水化物",
    "q.l40#18.l1" to "脂肪",
    "q.l40#18.l2" to "タンパク質",
    "q.l40#18.l3" to "水と電解質",
    "q.l40#18.r0" to "最も速く使え、高所での第一選択",
    "q.l40#18.r1" to "エネルギー密度が最も高く、長期の供給に向く",
    "q.l40#18.r2" to "修復と維持が主で、エネルギー供給の主体ではない",
    "q.l40#18.r3" to "循環と体温調節を支える",
    "q.l40#18.e" to "四者の比率は調整できますが、炭水化物の基礎的な位置は代替できません。",
    "q.l40#19.p" to "補給の場面と、適した選択を対応させてください。",
    "q.l40#19.l0" to "長い登攀",
    "q.l40#19.l1" to "極寒での待機",
    "q.l40#19.l2" to "アタック 2 時間前",
    "q.l40#19.l3" to "キャンプに戻った後",
    "q.l40#19.r0" to "ジェルやグミなど、歩きながら食べられる炭水化物",
    "q.l40#19.r1" to "高脂肪・高カロリーで、凍りにくいもの",
    "q.l40#19.r2" to "炭水化物中心の温かい食事",
    "q.l40#19.r3" to "温かい食事＋補水＋電解質",
    "q.l40#19.e" to "同じ食料でも場面によって効果が変わります。場面ごとに組み合わせるほうが、「エナジーバーを大量に買う」より有効です。",
    "q.l40#20.p" to "隊員が軽量化のためプロテインだけを持ってきました。どう判断しますか。",
    "q.l40#20.o0" to "だめ。タンパク質は主なエネルギー源ではなく、高所では炭水化物が要る",
    "q.l40#20.o1" to "よい。タンパク質のほうが純粋",
    "q.l40#20.o2" to "よい。タンパク質のほうが軽い",
    "q.l40#20.o3" to "味次第",
    "q.l40#20.e" to "タンパク質はエネルギー供給としては「効率の悪い経路」で、腎臓の負担と脱水のリスクも増やします。高所の主力は炭水化物と脂肪です。",
    "q.l40#21.p" to "低温で食べ物が凍って硬くなったとき、最も実用的な対応はどれですか。",
    "q.l40#21.o0" to "食べる分を体に密着させて、体温で保温する",
    "q.l40#21.o1" to "お湯に浸す",
    "q.l40#21.o2" to "歯で噛む",
    "q.l40#21.o3" to "諦めて食べない",
    "q.l40#21.e" to "体に密着させるのが最も簡単で有効です。ザックの中のエナジーバーは -20 ℃ では石と変わりません。",
    "q.l40#22.p" to "「食べること自体が高所での能力だ」と言われるのはなぜですか。",
    "q.l40#22.o0" to "低酸素と食欲低下の中で摂取を維持できるかが、体力と判断力を直接決めるから",
    "q.l40#22.o1" to "食べられるのは幸せだから",
    "q.l40#22.o2" to "食料が高いから",
    "q.l40#22.o3" to "写真を撮るから",
    "q.l40#22.e" to "エネルギーの不足はすぐに「空腹」として現れるのではなく、動作の鈍り、寒さ、判断の乱れとして現れます。食べ続けられることは訓練の結果です。",
    "q.l40#23.p" to "高所でのカフェインの使い方として正しいのはどれですか。",
    "q.l40#23.o0" to "適量なら使えるが、休息と補水の代わりにはならない",
    "q.l40#23.o1" to "多ければ多いほどよい",
    "q.l40#23.o2" to "まったく禁止",
    "q.l40#23.o3" to "歩き続けるためにだけ使う",
    "q.l40#23.e" to "カフェインは頭痛に多少効きますが、疲労を隠すために使うと、問題をより危険な時点へ押しやることになります。",
    "q.m18#16.p" to "ムスターグ・アタ（慕士塔格峰）の標高と位置はどれですか。",
    "q.m18#16.o0" to "7,509 m、新疆アクト、パミール高原の東縁",
    "q.m18#16.o1" to "6,812 m、ネパール",
    "q.m18#16.o2" to "7,134 m、キルギス",
    "q.m18#16.o3" to "8,163 m、ネパール",
    "q.m18#16.e" to "「氷山の父」と呼ばれ、国内 7,000 m 級の第一候補の一つです。雪の斜面が長く、順応と体力への要求が高い山です。",
    "q.m18#17.p" to "ムスターグ・アタの主な難所はどこにありますか。",
    "q.m18#17.o0" to "高所の順応と長い雪の斜面による体力消耗。技術的な難しさではない",
    "q.m18#17.o1" to "垂直な岩壁",
    "q.m18#17.o2" to "密集したクレバス",
    "q.m18#17.o3" to "技術的なアイスクライミング",
    "q.m18#17.e" to "技術的には比較的穏やかですが、「長い・高い・寒い」の三つが、体力と順応の不足を増幅します。",
    "q.m18#18.p" to "レーニン峰がある国・地域はどこですか。",
    "q.m18#18.o0" to "キルギスとタジキスタンの国境",
    "q.m18#18.o1" to "ネパール",
    "q.m18#18.o2" to "中国新疆",
    "q.m18#18.o3" to "パキスタン",
    "q.m18#18.e" to "パミール高原のレーニン峰は最初の 7,000 m としてよく選ばれますが、高所と氷河地形への対応は依然として必要です。",
    "q.m18#19.p" to "アマ・ダブラムの標高はどれですか。",
    "q.m18#19.o0" to "6,812 m",
    "q.m18#19.o1" to "7,509 m",
    "q.m18#19.o2" to "7,126 m",
    "q.m18#19.o3" to "6,189 m",
    "q.m18#19.e" to "7,000 m には届きませんが、切り立った岩と雪の混合地形と強い露出感のため、技術的な難しさは 7,000 m 以上に匹敵します。",
    "q.m18#20.p" to "アマ・ダブラムは何の「試金石」とされることが多いですか。",
    "q.m18#20.o0" to "8,000 m 級への技術的・心理的な準備",
    "q.m18#20.o1" to "最初の雪山",
    "q.m18#20.o2" to "スキーのルート",
    "q.m18#20.o3" to "トレッキングのルート",
    "q.m18#20.e" to "露出感と技術の組み合わせが、「プレッシャーの下でも正しい動作ができるか」を試します。",
    "q.m18#21.p" to "7,000 m 級の山の季節の窓は通常どうですか。",
    "q.m18#21.o0" to "5,000／6,000 m 級より狭く、上空の風と降雪が窓を決める",
    "q.m18#21.o1" to "一年中開いている",
    "q.m18#21.o2" to "冬だけ",
    "q.m18#21.o3" to "低山と同じ",
    "q.m18#21.e" to "標高が上がるほど、窓は上空の風とモンスーンに左右されます。窓が狭いということは、「待つ」も「撤退する」もより果断に、ということです。",
    "q.m18#22.p" to "7,000 m 級の目標を選ぶとき、まず確認すべき能力はどれですか。",
    "q.m18#22.o0" to "6,000 m 級で、長い雪の斜面の行進と自己管理を何度も安定してこなしていること",
    "q.m18#22.o1" to "フリークライミングのグレード",
    "q.m18#22.o2" to "マラソンの記録",
    "q.m18#22.o3" to "装備の数",
    "q.m18#22.e" to "7,000 m の関門は「耐えることと自持」であり、特定の技術動作ではありません。まず自分の 6,000 m の記録を見ます。",
    "q.m18#23.p" to "これらの山の許可と後方支援は、通常どうする必要がありますか。",
    "q.m18#23.o0" to "数週間前から許可を申請し、ガイド、ポーター、キャンプ物資を手配する",
    "q.m18#23.o1" to "現地で申請する",
    "q.m18#23.o2" to "許可は不要",
    "q.m18#23.o3" to "チケットを買うだけ",
    "q.m18#23.e" to "ルートが奥まるほど後方支援の連鎖は長くなります。許可と物流を「技術準備の一部」として扱うほうが、場当たりで埋め合わせるよりずっと安く済みます。",
    "q.m19#19.p" to "「デスゾーン（死の領域）」は通常、標高何 m 以上を指しますか。",
    "q.m19#19.o0" to "8,000 m",
    "q.m19#19.o1" to "6,000 m",
    "q.m19#19.o2" to "7,000 m",
    "q.m19#19.o3" to "5,000 m",
    "q.m19#19.e" to "8,000 m 以上では気圧が海面の約三分の一になり、人体は長期的に均衡を保てず、消耗し続けるだけになります。",
    "q.m19#20.p" to "8,000 m では、なぜ「休んでも」本当には回復しないのですか。",
    "q.m19#20.o0" to "酸素供給が修復を支えられず、体が正味の消耗状態にあるから",
    "q.m19#20.o1" to "寒すぎるから",
    "q.m19#20.o2" to "よく眠れないから",
    "q.m19#20.o3" to "脱水するから",
    "q.m19#20.e" to "これが「滞在時間は短いほどよい」という生理的な根拠です。すべての戦術が「露出を短くする」ことを中心に組み立てられます。",
    "q.m19#21.p" to "高所で認知能力が落ちるとき、最も危険な現れ方はどれですか。",
    "q.m19#21.o0" to "自分では判断力が落ちていることに気づけない",
    "q.m19#21.o1" to "記憶力が悪い",
    "q.m19#21.o2" to "反応が遅い",
    "q.m19#21.o3" to "注意力が散る",
    "q.m19#21.e" to "低酸素はまず「自己評価」の能力を削ります。だから判断を外に出す——チェックリストを書く、他人に確認してもらう——必要があるのです。",
    "q.m20#20.p" to "酸素ボンベの「使用可能容量」と「公称容量」が違うのはなぜですか。",
    "q.m20#20.o0" to "ボンベ内の残圧で最後の一部が使えず、低温で圧力も下がるから",
    "q.m20#20.o1" to "漏れているから",
    "q.m20#20.o2" to "表示が間違っているから",
    "q.m20#20.o3" to "マスクが消耗するから",
    "q.m20#20.e" to "計画は「使用可能量」で計算します。公称値をそのまま使える量とみなすのが、アタック日に「酸素が早く尽きた」となるよくある原因です。",
    "q.m20#21.p" to "酸素流量を上げると、どんな代償がありますか。",
    "q.m20#21.o0" to "持続時間が比例して短くなり、予備ボンベがより多く必要になる",
    "q.m20#21.o1" to "代償はない",
    "q.m20#21.o2" to "マスクが壊れる",
    "q.m20#21.o3" to "ボンベが凍る",
    "q.m20#21.e" to "流量と持続時間は反比例します。流量を上げるなら、総需要と予備を計算し直さなければなりません。",
    "q.m21#18.p" to "エベレストの最新の公式標高はどれですか。",
    "q.m21#18.o0" to "8,848.86 m（2020 年の中国・ネパール共同測定）",
    "q.m21#18.o1" to "8,848 m",
    "q.m21#18.o2" to "8,850 m",
    "q.m21#18.o3" to "8,846 m",
    "q.m21#18.e" to "8,848.86 m は 2020 年の共同公表値です。旧い教材の 8,848 m は古典的な値で、どちらもよく見かけます。",
    "q.m21#19.p" to "ローツェとエベレストの位置関係はどれですか。",
    "q.m21#19.o0" to "エベレストのすぐ南に隣接し、しばしば同じルートで登られる",
    "q.m21#19.o1" to "エベレストの北側",
    "q.m21#19.o2" to "ネパール西部",
    "q.m21#19.o3" to "カラコルム",
    "q.m21#19.e" to "二峰はサウスコルのルートの一部を共有するため、「エベレスト＋ローツェ」が同じ遠征で組まれることがよくあります。",
    "q.m21#20.p" to "カンチェンジュンガはどこにありますか。",
    "q.m21#20.o0" to "ネパールとインドの国境",
    "q.m21#20.o1" to "中国とネパールの国境",
    "q.m21#20.o2" to "パキスタン",
    "q.m21#20.o3" to "ブータン",
    "q.m21#20.e" to "世界第 3 峰で、ネパールとインド（シッキム）の国境にあります。入山許可と後方支援は比較的複雑です。",
    "q.m21#21.p" to "アンナプルナ I 峰の特徴はどれですか。",
    "q.m21#21.o0" to "死亡率が比較的高く、ルートが急で雪崩と落石のリスクが際立つ",
    "q.m21#21.o1" to "最も易しい",
    "q.m21#21.o2" to "最も高い",
    "q.m21#21.o3" to "一年中登れる",
    "q.m21#21.e" to "8,000 m 級で最もリスクの高い山の一つです。この数字は「標高の順位は難易度の順位ではない」ことを教えてくれます。",
    "q.m22#17.p" to "K2 の公式の高さと別名はどれですか。",
    "q.m22#17.o0" to "8,611 m、「野蛮な巨峰」",
    "q.m22#17.o1" to "8,586 m、「雪豹」",
    "q.m22#17.o2" to "8,126 m、「裸の山」",
    "q.m22#17.o3" to "8,080 m、「隠れた峰」",
    "q.m22#17.e" to "K2 は世界第 2 峰で、技術的難度と死亡率は 8,000 m 級の中で長く上位にあります。",
    "q.m22#18.p" to "ナンガ・パルバットの別名と主なリスクはどれですか。",
    "q.m22#18.o0" to "「裸の山」。巨大な標高差が雪崩と落石のリスクを生む",
    "q.m22#18.o1" to "「氷山の父」",
    "q.m22#18.o2" to "「隠れた峰」",
    "q.m22#18.o3" to "「人喰いの峰」",
    "q.m22#18.e" to "その南壁は世界最大級の岩壁の落差の一つです。ルートは露出し、天候は変わりやすく、撤退も難しい山です。",
    "q.m22#19.p" to "ガッシャーブルム I と II の高さは、それぞれどれですか。",
    "q.m22#19.o0" to "8,080 m と 8,035 m",
    "q.m22#19.o1" to "8,051 m と 8,080 m",
    "q.m22#19.o2" to "8,611 m と 8,586 m",
    "q.m22#19.o3" to "8,188 m と 8,167 m",
    "q.m22#19.e" to "GI 8,080、GII 8,035。二つはよく並べて語られますが、ルートも難易度も大きく違います。",
    "q.m22#20.p" to "ブロード・ピークの高さはどれですか。",
    "q.m22#20.o0" to "8,051 m",
    "q.m22#20.o1" to "8,035 m",
    "q.m22#20.o2" to "8,080 m",
    "q.m22#20.o3" to "8,126 m",
    "q.m22#20.e" to "ブロード・ピークは 8,051 m で、8,000 m 級の中では技術的難度が低い選択肢とされますが、長い雪の斜面と高所のリスクは残ります。",
    "q.m22#21.p" to "パキスタン国内には 8,000 m 級の山がいくつありますか。",
    "q.m22#21.o0" to "五つ",
    "q.m22#21.o1" to "三つ",
    "q.m22#21.o2" to "四つ",
    "q.m22#21.o3" to "二つ",
    "q.m22#21.e" to "K2、ナンガ・パルバット、ガッシャーブルム I／II、ブロード・ピークの五つです。",
    "q.l19#16.p" to "実行できる登山計画に必ず入れるべき「ネガティブな情報」はどれですか。",
    "q.l19#16.o0" to "どんな条件で諦めるか、どこから撤退するか、どこまで下がるか",
    "q.l19#16.o1" to "登頂ルートだけ",
    "q.l19#16.o2" to "装備リストだけ",
    "q.l19#16.o3" to "予算だけ",
    "q.l19#16.e" to "「どう成功するか」しか書かれていない計画は、プレッシャーの下で拘束力を失います。撤退の条件は事前に明記します。",
    "q.l19#17.p" to "計画における「代替ルート」の役割は何ですか。",
    "q.l19#17.o0" to "本命のルートが使えないとき、実行できる選択肢が残っていること",
    "q.l19#17.o1" to "見栄えのため",
    "q.l19#17.o2" to "費用を抑えるため",
    "q.l19#17.o3" to "規定を満たすため",
    "q.l19#17.e" to "代替ルートがあれば、「計画が崩れた」ときに無理に押し込まなくて済みます。B プランがなければ、A プランが唯一の賭けになります。",
    "q.l19#18.p" to "撤退の判断に「あらかじめ引き金を決めておく」のはなぜですか。",
    "q.l19#18.o0" to "疲労と目標へのプレッシャーの下では、人は基準をどんどん緩めてしまうから",
    "q.l19#18.o1" to "覚えていられないから",
    "q.l19#18.o2" to "規定だから",
    "q.l19#18.o3" to "ガイドが求めるから",
    "q.l19#18.e" to "引き金は具体的にします。何時、風速いくつ、視程いくつ、誰のどんな症状。曖昧な条件は、条件がないのと同じです。",
    "q.l19#19.p" to "隊で「撤退したい人」と「上がりたい人」が分かれたとき、最も妥当な扱いはどれですか。",
    "q.l19#19.o0" to "あらかじめ決めた引き金に戻り、意欲ではなく事実で判断する",
    "q.l19#19.o1" to "投票する",
    "q.l19#19.o2" to "リーダーに任せる",
    "q.l19#19.o3" to "別行動にする",
    "q.l19#19.e" to "意見の対立を「基準との照合」に置き換えれば、人間関係の衝突になりません。基準は出発前に決めたもので、現場で作るものではありません。",
    "q.l19#20.p" to "撤退ルートはどこまで事前に確認しておくべきですか。",
    "q.l19#20.o0" to "主要な曲がり角、懸垂下降点、予備キャンプ地の位置まで",
    "q.l19#20.o1" to "おおよその方向だけでよい",
    "q.l19#20.o2" to "不要",
    "q.l19#20.o3" to "現場で見てから決める",
    "q.l19#20.e" to "撤退は悪天候の中で行われることが多いのです。視界が悪ければ「おおよその方向」は情報がないのとほぼ同じです。",
    "q.l19#21.p" to "計画の「時間の余裕」は通常どう取りますか。",
    "q.l19#21.o0" to "各区間に 20〜30% の余裕を見込み、天候の遅れ用に別枠で 1 日を取る",
    "q.l19#21.o1" to "余裕は取らない",
    "q.l19#21.o2" to "1 日だけ取る",
    "q.l19#21.o3" to "最速で組む",
    "q.l19#21.e" to "余裕は「不測の事態」への予算です。詰め切った計画は、最初の変化で全体が崩れます。",
    "q.l20#16.p" to "救助要請で最も言い漏らしやすいのはどれですか。",
    "q.l20#16.o0" to "座標と「最後に確認できた位置」の違い",
    "q.l20#16.o1" to "氏名",
    "q.l20#16.o2" to "隊の人数",
    "q.l20#16.o3" to "天候",
    "q.l20#16.e" to "「いまどこにいるか」と「最後に自分がどこにいると確認できたか」は別の情報で、後者が捜索範囲を決めます。",
    "q.l20#17.p" to "高所でヘリ救助が実施しにくいのはなぜですか。",
    "q.l20#17.o0" to "空気が薄く揚力と搭載量が落ち、天候の窓も短いから",
    "q.l20#17.o1" to "費用が高いから",
    "q.l20#17.o2" to "航路がないから",
    "q.l20#17.o3" to "パイロットが嫌がるから",
    "q.l20#17.e" to "「ヘリを前提にしない」理由はここにあります。地上での自救と、救助を待つ能力を自分たちで持つ必要があります。",
    "q.l20#18.p" to "救助要請は誰が出すべきですか。",
    "q.l20#18.o0" to "あらかじめ決めた連絡担当者が、計画に沿って時間超過後に出す",
    "q.l20#18.o1" to "見た人が誰でも",
    "q.l20#18.o2" to "傷者本人",
    "q.l20#18.o3" to "翌日まで待つ",
    "q.l20#18.e" to "担当を決めておけば「みんな他人が出したと思っている」を避けられます。計画には「何時・誰が・誰へ」を書きます。",
    "q.l20#19.p" to "現場での急救の優先順位は通常どうなりますか。",
    "q.l20#19.o0" to "止血と気道 → 保温 → 固定 → 搬送",
    "q.l20#19.o1" to "搬送が優先",
    "q.l20#19.o2" to "固定が優先",
    "q.l20#19.o3" to "鎮痛が優先",
    "q.l20#19.e" to "まず「数分で致命的になる」問題を処理し、その後に「数時間で悪化する」ものを扱います。高所では保温を前倒しします。",
    "q.l20#20.p" to "救助を待つ間、隊が最も優先すべきことは何ですか。",
    "q.l20#20.o0" to "シェルターを作り、保温し、位置を示し、体力を残す",
    "q.l20#20.o1" to "道を探し続ける",
    "q.l20#20.o2" to "分かれて人を探す",
    "q.l20#20.o3" to "装備を使い切る",
    "q.l20#20.e" to "待機期の目標は「救助が来るまで持たせる」ことで、「自分たちで解決する」ことではありません。体力が最も貴重な資源です。",
    "q.l20#21.p" to "救助の引き継ぎで最も伝えるべき情報はどれですか。",
    "q.l20#21.o0" to "時間軸、症状の変化、行った処置、残っている物資",
    "q.l20#21.o1" to "感想",
    "q.l20#21.o2" to "ルートの景色",
    "q.l20#21.o3" to "装備のブランド",
    "q.l20#21.e" to "時間軸と処置の記録が、その後の医療判断を決めます。口頭で説明するより、書いて渡すほうが確実です。",
    "q.m23#18.p" to "総合シナリオ：同行者が 7,500 m で運動失調を示し、酸素の残量は 2 時間分しかありません。まず何をしますか。",
    "q.m23#18.o0" to "ただちに下降し酸素を投与する。同時にベースキャンプへ連絡して受け入れ準備をさせる",
    "q.m23#18.o1" to "まず休んで観察する",
    "q.m23#18.o2" to "まず薬を飲ませる",
    "q.m23#18.o3" to "キャンプまで行ってから対応する",
    "q.m23#18.e" to "運動失調は HACE を示します。下降だけが確実に効く手段で、酸素は時間を稼ぐために使います。",
    "q.m23#19.p" to "総合シナリオ：アタック日に、固定ロープが先行パーティーで毛羽立っているのを見つけました。正しい対応はどれですか。",
    "q.m23#19.o0" to "その区間は使わず、ルートを変えるか撤退する",
    "q.m23#19.o1" to "注意しながら使い続ける",
    "q.m23#19.o2" to "後続の人に伝えるだけにする",
    "q.m23#19.o3" to "記録してから使い続ける",
    "q.m23#19.e" to "摩耗したロープの強度は見積もれません。固定ロープは「全員の命綱」であり、「注意する」で相殺できるものではありません。",
    "q.m23#20.p" to "総合シナリオ：6,500 m で暴風雪に遭い、視程は 5 m です。最も妥当な選択はどれですか。",
    "q.m23#20.o0" to "その場にシェルターを作って待つ。または GPS で記録済みの軌跡をたどって戻る",
    "q.m23#20.o1" to "道を探し続ける",
    "q.m23#20.o2" to "分かれて探す",
    "q.m23#20.o3" to "その場に座って晴れるのを待つ",
    "q.m23#20.e" to "ホワイトアウトの中で「道を探す」と、ほぼ必ずコースを外れます。シェルターを作って止まるか、記録した軌跡を戻るかの二択です。",
    "q.m23#21.p" to "総合シナリオ：隊は全員が続行に賛成で、自分だけが違和感を持っていますが、理由が言葉になりません。どうすべきですか。",
    "q.m23#21.o0" to "「違和感がある」と明確に言い、隊で重要な情報を一緒に確認するよう求める",
    "q.m23#21.o1" to "多数に従う",
    "q.m23#21.o2" to "黙ってついていく",
    "q.m23#21.o3" to "一人で戻る",
    "q.m23#21.e" to "直感はたいてい「気づいたが言葉になっていない」信号です。口に出して、事実を隊で確認します。",
    "q.m24#18.p" to "総合シナリオ：アタック日に計画より 4 時間遅れ、風速が上がり、ある隊員の動作が鈍くなっています。最も妥当な判断はどれですか。",
    "q.m24#18.o0" to "あらかじめ決めた折り返し条件に従って撤退し、引き金の根拠を記録する",
    "q.m24#18.o1" to "頂上まで行ってから考える",
    "q.m24#18.o2" to "遅い人だけ帰らせる",
    "q.m24#18.o3" to "時間を取り戻すために加速する",
    "q.m24#18.e" to "三つの信号が同時に出ているとき、「続行」の理由はたいてい目標へのプレッシャーで、事実ではありません。折り返し条件はそのためにあります。",
    "q.m24#19.p" to "総合シナリオ：同行者に安静時の呼吸困難が出ていますが、酸素飽和度はまだ 80% あります。どうすべきですか。",
    "q.m24#19.o0" to "HAPE として扱う。安静、酸素投与、下降の準備",
    "q.m24#19.o1" to "もう少し観察する",
    "q.m24#19.o2" to "水を多く飲ませる",
    "q.m24#19.o3" to "鎮痛薬を飲ませる",
    "q.m24#19.e" to "症状が数字より優先です。安静時の呼吸困難は HAPE の中核的なサインで、下降が最も確実な処置です。",
    "q.m24#20.p" to "総合シナリオ：固定ロープ区間で一つの支点が怪しいと分かりましたが、隊はすでに半分通過しています。どうすべきですか。",
    "q.m24#20.o0" to "その区間の使用を止め、バックアップを追加するかルートを変える。まず人を安全な位置に移す",
    "q.m24#20.o1" to "急いで通過する",
    "q.m24#20.o2" to "後続に伝えるだけにする",
    "q.m24#20.o3" to "そのまま使い続ける",
    "q.m24#20.e" to "「もう半分過ぎた」は続行の理由になりません。支点の失效は個人ではなくシステム全体に及ぶ結果を生みます。",
    "q.m24#21.p" to "総合シナリオ：行程がすべて終わりました。最も残す価値があるものは何ですか。",
    "q.m24#21.o0" to "時間軸、判断の根拠、誤った点を書き出した振り返り",
    "q.m24#21.o1" to "写真",
    "q.m24#21.o2" to "装備リスト",
    "q.m24#21.o3" to "請求書",
    "q.m24#21.e" to "振り返りは「経験したこと」を「経験」に変えます。「どの時点でもっと早く決められたか」を書けば、次はより早く決められます。",
    "q.l41#0.p" to "遠征の後方支援の本質は何ですか。",
    "q.l41#0.o0" to "多段階の輸送で、各区間ごとに重量制限・時間・リスクが独立していること",
    "q.l41#0.o1" to "一度に山麓まで荷を送ること",
    "q.l41#0.o2" to "最も高い装備を買うこと",
    "q.l41#0.o3" to "最高のガイドを探すこと",
    "q.l41#0.e" to "後方支援を点ではなく鎖として捉えて初めて、各区間で正しい取捨ができます。どこか一段が切れれば、後ろすべてに影響します。",
    "q.l41#1.p" to "物資の梱包の正しい考え方はどれですか。",
    "q.l41#1.o0" to "到着順に分けて包み、先に着くものから取り出す",
    "q.l41#1.o1" to "種類ごとに分ける",
    "q.l41#1.o2" to "価格ごとに分ける",
    "q.l41#1.o3" to "全部混ぜる",
    "q.l41#1.e" to "高所キャンプは狭く天候も悪く、箱を探るコストが極端に高いのです。到着順の梱包が露出時間を大きく減らします。",
    "q.l41#2.p" to "登山許可には通常、何が紐づいていますか。",
    "q.l41#2.o0" to "リエゾンオフィサー、ルート、有効期限",
    "q.l41#2.o1" to "費用だけ",
    "q.l41#2.o2" to "人数だけ",
    "q.l41#2.o3" to "季節だけ",
    "q.l41#2.e" to "三つとも許可に紐づきます。ルート変更、期限超過、人の入れ替えは再届出が必要になり、追加費用が生じることもあります。",
    "q.l41#3.p" to "ゴミのデポジットの一般的な規則はどれですか。",
    "q.l41#3.o0" to "ゴミをすべて持ち出して初めて返還される",
    "q.l41#3.o1" to "先に払って返ってこない",
    "q.l41#3.o2" to "重量に応じて罰金",
    "q.l41#3.o3" to "任意で納める",
    "q.l41#3.e" to "この規則の目的は徴収ではなく、「ゴミを下山させる」ことを経済的な制約に変えることです。計画には人手も見込みます。",
    "q.l41#4.p" to "ポーターや協力スタッフの荷を勝手に増やせないのはなぜですか。",
    "q.l41#4.o0" to "法定または業界の上限があり、超過はリスクを相手に移し、隊全体も遅くするから",
    "q.l41#4.o1" to "文句を言うから",
    "q.l41#4.o2" to "装備が壊れるから",
    "q.l41#4.o3" to "保険が下りないから",
    "q.l41#4.e" to "超過は自分の効率を他人の損傷の上に築くことであり、輸送の鎖全体も遅くします。倫理の問題であり、管理の問題でもあります。",
    "q.l41#5.p" to "補給計画の「消費速度」とは何を指しますか。",
    "q.l41#5.o0" to "人数 × 日数 × 1 日あたりの使用量。総量と補給点を推算する",
    "q.l41#5.o1" to "1 日にどれだけ歩くか",
    "q.l41#5.o2" to "1 日にどれだけ登るか",
    "q.l41#5.o3" to "1 人がどれだけ背負うか",
    "q.l41#5.e" to "燃料、ガス、食料はすべて速度で計算します。感覚で見積もると、たいてい最も寒い数日でガスが足りなくなります。",
    "q.l41#6.p" to "許可の期限が近いのに天候の窓が来ないとき、最も妥当なのはどれですか。",
    "q.l41#6.o0" to "延長の費用と手続きを事前に評価し、必要なら延長や日程変更を申請する",
    "q.l41#6.o1" to "期限を超えて登り続ける",
    "q.l41#6.o2" to "届け出ずに別ルートへ変える",
    "q.l41#6.o3" to "リエゾンオフィサーに融通してもらう",
    "q.l41#6.e" to "期限超過の登山は、許可・保険・救助を同時に無効にします。延長は高くつきますが、「事故の後に救助できない」よりは安いのです。",
    "q.l41#7.p" to "補給に「予備量」を残すのはなぜですか。",
    "q.l41#7.o0" to "天候の遅れ、装備の消耗、隊の状態が消費を増やすから",
    "q.l41#7.o1" to "他人に売るため",
    "q.l41#7.o2" to "重量を減らすため",
    "q.l41#7.o3" to "規定を満たすため",
    "q.l41#7.e" to "遠征の消費は決して線形ではありません。予備量は「計画外に数日長引く」ための余地です。",
    "q.l41#8.p" to "高所キャンプの物資管理の核は何ですか。",
    "q.l41#8.o0" to "明確な配給表とローテーション。「あるキャンプに積まれ、別のキャンプで欠ける」を避ける",
    "q.l41#8.o1" to "多ければ多いほどよい",
    "q.l41#8.o2" to "先に着いた人が取る",
    "q.l41#8.o3" to "均等に分ける",
    "q.l41#8.e" to "配給表があれば、各キャンプが「自分に何があり、いつ補給されるか」を知っています。表がなければ物資は誤ったキャンプに溜まります。",
    "q.l41#9.p" to "登頂の認定には通常何が必要ですか。",
    "q.l41#9.o0" to "登頂の写真か動画、宣誓書、許可証と身分証明",
    "q.l41#9.o1" to "写真だけ",
    "q.l41#9.o2" to "同行者の証言だけ",
    "q.l41#9.o3" to "不要",
    "q.l41#9.e" to "山ごとに要件は違いますが、「写真＋宣誓書＋許可証」はほぼ共通です。帰ってから手続きするほうが、出発前に用意するよりずっと難しくなります。",
    "q.l41#10.p" to "荷物が同じ飛行機で届かなかったとき、まず守るべきは何ですか。",
    "q.l41#10.o0" to "登山靴と個人の技術装備。これらは現地で代替できない",
    "q.l41#10.o1" to "着替え",
    "q.l41#10.o2" to "お菓子",
    "q.l41#10.o3" to "お土産",
    "q.l41#10.e" to "靴が合わなければ歩けず、技術装備は安全に関わります。多くの隊がこの二類を機内持ち込みにしています。",
    "q.l41#11.p" to "遠征の後方支援計画で、区間ごとに確認すべき内容はどれですか。",
    "q.l41#11.o0" to "交通手段と代替案",
    "q.l41#11.o1" to "ポーター輸送の負重と費用",
    "q.l41#11.o2" to "各区間の時間とチェックポイント",
    "q.l41#11.o3" to "隊員の SNS アカウント",
    "q.l41#11.e" to "前三者が「計画どおり進めるかどうか」を決めます。四つ目は後方支援と関係ありません。",
    "q.l41#12.p" to "許可とコンプライアンスに関わる費用には通常何が含まれますか。",
    "q.l41#12.o0" to "許可料とリエゾンオフィサー費用",
    "q.l41#12.o1" to "ゴミのデポジット",
    "q.l41#12.o2" to "延長費用",
    "q.l41#12.o3" to "装備の減価償却",
    "q.l41#12.e" to "前三者は「コンプライアンス費用」で、予算に独立して計上します。装備の減価償却は個人の費用です。",
    "q.l41#13.p" to "キャンプの物資管理で避けるべき状況はどれですか。",
    "q.l41#13.o0" to "あるキャンプで余り、別のキャンプで食料が尽きる",
    "q.l41#13.o1" to "燃料と食品を混載して汚染する",
    "q.l41#13.o2" to "配給表がなく記憶に頼る",
    "q.l41#13.o3" to "計画どおりにローテーションする",
    "q.l41#13.e" to "前三者は管理の欠如の表れです。四つ目はむしろ正しいやり方です。",
    "q.l41#14.p" to "遠征の後方支援計画の順序を並べてください。",
    "q.l41#14.o0" to "ルート、許可、期限を確認する",
    "q.l41#14.o1" to "各区間の輸送手段と期限を決める",
    "q.l41#14.o2" to "到着順に梱包し、配給表を作る",
    "q.l41#14.o3" to "予備と延長の予算を確保する",
    "q.l41#14.e" to "順序は「まずコンプライアンス、次に物流、最後に細部」を表します。許可が固まる前に輸送を押さえると、日程変更の費用が倍になります。",
    "q.l41#15.p" to "物資が高所キャンプに届く順序を並べてください。",
    "q.l41#15.o0" to "車両でベースキャンプまで運ぶ",
    "q.l41#15.o1" to "ポーターか人力で中間キャンプへ運ぶ",
    "q.l41#15.o2" to "配給表に従って各高所キャンプへ配る",
    "q.l41#15.o3" to "アタック前に重要物資（ガス、食料、電池）を点検する",
    "q.l41#15.e" to "最後の一段が最も省かれやすいところです。アタック前の点検をしないと、「高所キャンプでガスが足りない」という結末になりがちです。",
    "q.l41#16.p" to "補給の総量は通常「人数 × 日数 × ______」で推算します。",
    "q.l41#16.a0" to "1 日あたりの使用量",
    "q.l41#16.a1" to "日量",
    "q.l41#16.a2" to "使用量",
    "q.l41#16.e" to "「速度」を計画に書き込んで初めて、補給点と予備量を計算できます。",
    "q.l41#17.p" to "多くの山では、ゴミをすべて持ち出して初めて ______ が返還されます。",
    "q.l41#17.a0" to "デポジット",
    "q.l41#17.a1" to "保証金",
    "q.l41#17.e" to "デポジットを費用項目として見ておけば、最終日に「ゴミを背負う人手がない」と気づく事態を避けられます。",
    "q.l41#18.p" to "後方支援の段階と、その主なリスクを対応させてください。",
    "q.l41#18.l0" to "道路輸送",
    "q.l41#18.l1" to "ポーター輸送",
    "q.l41#18.l2" to "高所キャンプの配給",
    "q.l41#18.l3" to "許可の期限",
    "q.l41#18.r0" to "道路の遮断、崩落、車両の遅延",
    "q.l41#18.r1" to "負重超過、人員の状態、天候",
    "q.l41#18.r2" to "物資の誤配、食料やガスの枯渇",
    "q.l41#18.r3" to "超過で許可と救助が無効になる",
    "q.l41#18.e" to "四つの段階はリスクの種類がまったく違うので、対策も分けて書きます。",
    "q.l41#19.p" to "書類とその用途を対応させてください。",
    "q.l41#19.l0" to "許可証とリエゾンオフィサーの書類",
    "q.l41#19.l1" to "ゴミのデポジットの控え",
    "q.l41#19.l2" to "登頂写真／宣誓書",
    "q.l41#19.l3" to "保険と救助の連絡先",
    "q.l41#19.r0" to "入山とコンプライアンスの確認",
    "q.l41#19.r1" to "下山時にデポジットを返還してもらう根拠",
    "q.l41#19.r2" to "登頂認定の申請",
    "q.l41#19.r3" to "事故のときの連絡と請求",
    "q.l41#19.e" to "四つの書類は四つの時点に対応します。入山、下山、認定、事故。一つ欠けると、その時点で止まります。",
    "q.l41#20.p" to "隊が許可の範囲外に固定ロープを延長したいと考えています。まず何をすべきですか。",
    "q.l41#20.o0" to "許可や保護区の規則に反しないか確認し、必要なら届け出る",
    "q.l41#20.o1" to "まず設置してから考える",
    "q.l41#20.o2" to "夜にこっそり設置する",
    "q.l41#20.o3" to "他人に設置させる",
    "q.l41#20.e" to "固定ロープは保護区では「恒久的な施設」とみなされることが多く、無許可なら違反になり得ます。まず確認し、その後に動きます。",
    "q.l41#21.p" to "協力スタッフが契約を超える作業量を申し出てきました。最も妥当な対応はどれですか。",
    "q.l41#21.o0" to "契約と実際の作業量に基づいて再交渉し、変更を記録する",
    "q.l41#21.o1" to "話し合いを拒む",
    "q.l41#21.o2" to "無理に完遂させる",
    "q.l41#21.o3" to "記録せずに私下で金を渡す",
    "q.l41#21.e" to "遠征では人手の変更がよく起きます。再交渉して記録を残すことは、相手も自分も守ります。",
    "q.l41#22.p" to "遠征で「延長」の予算を別枠で確保するのはなぜですか。",
    "q.l41#22.o0" to "天候の窓と物流の遅れは常態で、延長は宿泊・人手・許可の追加支出を伴うから",
    "q.l41#22.o1" to "買い物のため",
    "q.l41#22.o2" to "チップのため",
    "q.l41#22.o3" to "為替のため",
    "q.l41#22.e" to "延長予算は無駄ではなく、「金の理由で危険な判断をする」ことを避けるためのものです。",
    "q.l41#23.p" to "下山時のゴミ処理として正しいのはどれですか。",
    "q.l41#23.o0" to "許可の要件に従ってすべて分別して持ち出し、控えを保管する",
    "q.l41#23.o1" to "雪の中に埋める",
    "q.l41#23.o2" to "燃やす",
    "q.l41#23.o3" to "次の隊に渡す",
    "q.l41#23.e" to "埋めるのも燃やすのも規則違反で、水源も汚します。持ち出し＋控えだけが、デポジットを返してもらえる方法です。",
    "q.l41#24.p" to "遠征物資の輸送保険で、最も手厚くすべきはどこですか。",
    "q.l41#24.o0" to "装備の紛失や遅延による行程中断のコスト",
    "q.l41#24.o1" to "運賃だけ",
    "q.l41#24.o2" to "対人だけ",
    "q.l41#24.o3" to "不要",
    "q.l41#24.e" to "装備の遅延は行程そのものを終わらせ得ます。保険は「紛失」だけでなく「遅延と中断」をカバーさせます。",
    "q.l41#25.p" to "協力スタッフと作業量を話すとき、最も有効な方法はどれですか。",
    "q.l41#25.o0" to "出発前に負重・回数・費用を書面で確認し、変更時にはその都度記録する",
    "q.l41#25.o1" to "口約束で済ませる",
    "q.l41#25.o2" to "着いてから相談する",
    "q.l41#25.o3" to "相手に決めさせる",
    "q.l41#25.e" to "遠征では変更が常態です。書面の確認と変更記録があれば、最終日の費用をめぐる争いを避けられます。",
    "q.l41#26.p" to "ベースキャンプの「在庫表」に含めるべきものはどれですか。",
    "q.l41#26.o0" to "品名、数量、置いてあるキャンプ、開封日、担当者",
    "q.l41#26.o1" to "総量だけ",
    "q.l41#26.o2" to "品目だけ",
    "q.l41#26.o3" to "書かない",
    "q.l41#26.e" to "「どこに・あとどれだけ・誰が使っているか」が在庫表の三要素です。これがなければ、物資は必ず誤った場所に溜まります。",
    "q.l41#27.p" to "許可が「ゴミをすべて持ち出す」ことを求める場合、計画に追加で組み込むべきは何ですか。",
    "q.l41#27.o0" to "下山時の人手とポーター輸送の能力、そして重量の計測と控え",
    "q.l41#27.o1" to "ゴミ袋だけ",
    "q.l41#27.o2" to "罰金の予算だけ",
    "q.l41#27.o3" to "組み込む必要はない",
    "q.l41#27.e" to "下山時は隊の体力が最も落ち、時間も最も厳しく、しかもゴミは最も重い。輸送計画に書き込んでこそ、最終日が崩れません。",
    "q.t01#0.p" to "トレッキングルートの難易度を判断するとき、最も役に立つ情報の組はどれですか。",
    "q.t01#0.o0" to "距離だけ",
    "q.t01#0.o1" to "距離＋累積標高差＋路面＋補給とエスケープポイント",
    "q.t01#0.o2" to "最高標高だけ",
    "q.t01#0.o3" to "他の人がどれくらいかかったか",
    "q.t01#0.e" to "距離は要素の一つにすぎません。同じ 10 km でも、累積標高差が 80 m と 800 m では所要時間が二〜三倍違います。路面が土か、砂利か、濡れた岩かでも、足をひねるリスクが変わります。",
    "q.t01#1.p" to "A と B はどちらも 10 km で、A の累積標高差は 80 m、B は 800 m です。最も大きな違いは何ですか。",
    "q.t01#1.o0" to "景色のよしあし",
    "q.t01#1.o1" to "所要時間と体力の消耗。B は A のおよそ二〜三倍",
    "q.t01#1.o2" to "標高の高低",
    "q.t01#1.o3" to "ほとんど差はない",
    "q.t01#1.e" to "登攀量は最も見落とされやすい変数です。経験則では、100 m 登るのは平地 500 m を歩くのにほぼ相当し、800 m の登攀は 4 km 分が丸ごと増える計算になります。",
    "q.t01#2.p" to "初めてのトレッキングで選ぶルートが満たすべき条件はどれですか。",
    "q.t01#2.o0" to "3 時間以内で歩き切れる",
    "q.t01#2.o1" to "累積標高差が 300 m 以内",
    "q.t01#2.o2" to "途中に道路か集落があり、途中で下山できる",
    "q.t01#2.o3" to "全行程で携帯の電波が満タン",
    "q.t01#2.e" to "前三者はリスクを管理できる範囲です。電波は運で、計画の一部にはできません。もともと電波のない谷はたくさんあります。",
    "q.t01#3.p" to "「エスケープポイント」を景色より先に確認すべきなのはなぜですか。",
    "q.t01#3.o0" to "たいていトイレがあるから",
    "q.t01#3.o1" to "天候や体力に問題が出たとき、無理に全行程を歩かずに済むから",
    "q.t01#3.o2" to "写真を撮りやすいから",
    "q.t01#3.o3" to "保険の条項が要求するから",
    "q.t01#3.e" to "エスケープポイントは「歩き切らなければならない」を「止まる選択ができる」に変えるものです。計画では各区間で、最寄りの下山口と、そこまでの所要時間を知っておきます。",
    "q.t01#4.p" to "同じルートでも雨の後に難易度が明らかに上がる主な理由は何ですか。",
    "q.t01#4.o0" to "気温が下がるから",
    "q.t01#4.o1" to "路面が滑り泥濘み、徒渉が必要になることもあり、所要時間と捻挫のリスクが同時に上がるから",
    "q.t01#4.o2" to "景色が悪くなるから",
    "q.t01#4.o3" to "人が減るから",
    "q.t01#4.e" to "濡れて滑ると、所要時間が延び、転倒と捻挫の確率も上がります。4 時間のルートなら雨後は 5〜6 時間で見積もり、急な下りの数か所を歩けるか判断し直します。",
    "q.t01#5.p" to "同行者が「このルート、4 時間で歩けたよ」と言いました。正しい理解はどれですか。",
    "q.t01#5.o0" to "自分も必ず 4 時間で歩ける",
    "q.t01#5.o1" to "それは経験者の速さで、隊は最も遅い人を基準に 1.3〜1.5 倍を見込む",
    "q.t01#5.o2" to "ルートが簡単だということ",
    "q.t01#5.o3" to "まったく参考にならない",
    "q.t01#5.e" to "他人の所要時間は、体力・荷物・慣れの上に成り立ちます。隊は最も遅い人で総時間を出し、休憩・写真・道探しの時間を足して初めて現実に近づきます。",
    "q.t01#6.p" to "トレッキングの所要時間の粗い見積もり方として、よく使われるのはどれですか。",
    "q.t01#6.o0" to "距離で基本時間を出し、300〜500 m 登るごとに 30 分を足す",
    "q.t01#6.o1" to "距離だけで出す",
    "q.t01#6.o2" to "登攀量だけで出す",
    "q.t01#6.o3" to "体重から出す",
    "q.t01#6.e" to "距離だけでは登攀の消耗を過小評価します。「距離の時間＋登攀の時間」を分けて出し、隊の係数を掛ければ誤差はかなり小さくなります。",
    "q.t01#7.p" to "出発前に「エスケープポイント」を確認するのはなぜですか。",
    "q.t01#7.o0" to "途中で下山できてこそ、安全も調整も成り立つから",
    "q.t01#7.o1" to "写真のため",
    "q.t01#7.o2" to "入山料を節約するため",
    "q.t01#7.o3" to "荷物を軽くするため",
    "q.t01#7.e" to "エスケープポイントは行程の「安全弁」です。それがなければ、一本道を最後まで行くしかありません。",
    "q.t02#0.p" to "トレッキングシューズの最も重要なフィットの基準は何ですか。",
    "q.t02#0.o0" to "きついほど安定する",
    "q.t02#0.o1" to "かかとが上下に動かず、下りでつま先が靴の先に当たらない",
    "q.t02#0.o2" to "大きいほど楽",
    "q.t02#0.o3" to "ブランドと価格で決める",
    "q.t02#0.e" to "試し履きは午後に、トレッキング用の靴下を履いて、下りを少し歩いて行います。靴の中で足が前後に滑ると、登りではアキレス腱を擦り、下りではつま先が当たり、どちらでも靴ずれになります。",
    "q.t02#1.p" to "靴ずれ（マメ）の最も直接的な原因は何ですか。",
    "q.t02#1.o0" to "靴が新しいこと",
    "q.t02#1.o1" to "湿気・摩擦・局所的な圧力の三つが重なること",
    "q.t02#1.o2" to "歩く時間が長すぎること",
    "q.t02#1.o3" to "靴下の色",
    "q.t02#1.e" to "単一の要因だけで起きることはまれです。砂が入って局所的に圧がかかり、汗で皮膚がふやけ、そのまま 30 分も歩けばマメになります。",
    "q.t02#2.p" to "マメを防ぐのに最も効果的な組み合わせはどれですか。",
    "q.t02#2.o0" to "出発前に擦れやすい所へ保護パッドを貼り、靴下を乾いた状態に保ち、途中で履き替える",
    "q.t02#2.o1" to "綿の靴下を二枚重ねる",
    "q.t02#2.o2" to "出発前に足を湯に浸す",
    "q.t02#2.o3" to "履き脱ぎを減らすため休まず歩く",
    "q.t02#2.e" to "保護パッドは摩擦を皮膚から貼り物へ移し、靴下の履き替えは湿気を解消します。この二つで大半のマメは防げます。",
    "q.t02#3.p" to "長い下りでは靴ひもをどうすべきですか。",
    "q.t02#3.o0" to "きつく結び、靴の中で足が前に出ないようにする",
    "q.t02#3.o1" to "完全に緩める",
    "q.t02#3.o2" to "登りと同じままにする",
    "q.t02#3.o3" to "足首の部分だけ結ぶ",
    "q.t02#3.e" to "下りでは足がつま先側へ滑ります。中段と足首を締め、甲の部分をやや緩めると、かかとを固定しつつ甲を圧迫しません。",
    "q.t02#4.p" to "足に「ホットスポット」——局所が赤く熱を持ち、押すと少し痛む——ができました。どうすべきですか。",
    "q.t02#4.o0" to "すぐ止まって処置する",
    "q.t02#4.o1" to "保護パッドかテープを貼る",
    "q.t02#4.o2" to "靴や靴下にしわや砂が入っていないか確認する",
    "q.t02#4.o3" to "そのまま歩き、皮がむけてから考える",
    "q.t02#4.e" to "ホットスポットはまだ戻せる段階で、処置は 2 分で済みます。皮がむけると皮膚が欠け、その後の一歩ごとに傷が広がり、感染もあり得ます。",
    "q.t02#5.p" to "長距離で綿の靴下が勧められないのはなぜですか。",
    "q.t02#5.o0" to "綿は汗を吸っても乾かず、濡れると摩擦が増し保温性も失うから",
    "q.t02#5.o1" to "綿の靴下は高いから",
    "q.t02#5.o2" to "通気性が悪く臭うから",
    "q.t02#5.o3" to "色落ちしやすいから",
    "q.t02#5.e" to "綿繊維は水を吸うと皮膚に貼り付き、摩擦係数が上がります。気温が下がれば、濡れた靴下は体温を急速に奪います。ウールや化学繊維は湿気を逃がし、濡れても保温性がいくらか残ります。",
    "q.t02#6.p" to "靴ひもの「ヒールロック」結びの目的は何ですか。",
    "q.t02#6.o0" to "かかとを靴の後部に固定し、下りでのつま先の突き当たりを減らす",
    "q.t02#6.o1" to "靴をきつくする",
    "q.t02#6.o2" to "脱ぎ履きを速くする",
    "q.t02#6.o3" to "摩耗を減らす",
    "q.t02#6.e" to "下りで足が前に滑り、つま先が繰り返し当たるのが、爪の内出血とマメの主な原因です。かかとを固定すれば直接解決できます。",
    "q.t02#7.p" to "トレッキングシューズを買うとき、通常どれくらいの余裕を見ますか。",
    "q.t02#7.o0" to "つま先の前に指一本分。長時間歩くと足がむくむ",
    "q.t02#7.o1" to "ぴったり合わせる",
    "q.t02#7.o2" to "1 サイズ上",
    "q.t02#7.o3" to "2 サイズ上",
    "q.t02#7.e" to "長時間歩くと足は軽くむくみます。指一本分の余裕があれば、下りでつま先が当たらず、緩すぎて擦れることもありません。",
    "q.t03#0.p" to "トレッキングの荷物の上限は通常どれくらいですか。",
    "q.t03#0.o0" to "体重の 10〜20%。初心者は下限側",
    "q.t03#0.o1" to "重いほど安全",
    "q.t03#0.o2" to "体重の 30%",
    "q.t03#0.o3" to "上限はない",
    "q.t03#0.e" to "重量はそのまま関節の負担と酸素消費に変わります。初めての数泊トレッキングなら、体重の 12〜15% に抑え、歩き切ってまだ余力があるくらいが適量です。",
    "q.t03#1.p" to "パッキングで重い物はどこに置くべきですか。",
    "q.t03#1.o0" to "背中に近い、肩甲骨の下から腰のあいだ",
    "q.t03#1.o1" to "ザックの最下部",
    "q.t03#1.o2" to "ザックの最も外側",
    "q.t03#1.o3" to "トップリッドの中",
    "q.t03#1.e" to "重い物を体に近づけ、重心の高さに置くと、歩行中の揺れが最小になります。最下部だと下に引っ張られて腰を圧迫し、外側だと重心が離れて首肩が代償します。",
    "q.t03#2.p" to "ショルダーハーネスとヒップベルトの正しい分担はどれですか。",
    "q.t03#2.o0" to "ショルダーで重さを支える",
    "q.t03#2.o1" to "ヒップベルトが大部分の重さを受け、ショルダーはフィットと安定を担う",
    "q.t03#2.o2" to "ヒップベルトは飾り",
    "q.t03#2.o3" to "どちらでもよい",
    "q.t03#2.e" to "ヒップベルトは重さを骨盤へ伝えます。骨盤は体で最も荷重に強い場所です。ショルダーを締めすぎると肩の血管を圧迫し、やがて腕がしびれます。",
    "q.t03#3.p" to "トップリッドや外付けに向くものはどれですか。",
    "q.t03#3.o0" to "レインウェア、地図、ヘッドランプ",
    "q.t03#3.o1" to "1 日分の水と行動食",
    "q.t03#3.o2" to "テントのポールをザックの外に横付けする",
    "q.t03#3.o3" to "最も重い水筒",
    "q.t03#3.e" to "トップリッドと外付けには「いつでも使うもの」か「形が特殊なもの」だけを置きます。重い物を外に付けると重心が崩れ、狭い道で枝や岩壁に引っかかります。",
    "q.t03#4.p" to "ザックが背中に密着していないと、どんな結果になりますか。",
    "q.t03#4.o0" to "重心が後ろにずれ、首肩が代償し、下りでより不安定になる",
    "q.t03#4.o1" to "見た目が悪いだけ",
    "q.t03#4.o2" to "容量が小さくなる",
    "q.t03#4.o3" to "影響はない",
    "q.t03#4.e" to "背板と背中のあいだに隙間があると、ザックは歩くたびに揺れます。それを抑えようと無意識に前傾し肩を上げるため、数時間で腰と背中が先に疲れます。",
    "q.t03#5.p" to "出発前にザックの重さを量ることが勧められるのはなぜですか。",
    "q.t03#5.o0" to "基準の重さを知って初めて、何が余分か判断できるから",
    "q.t03#5.o1" to "空港で検査されるから",
    "q.t03#5.o2" to "SNS に上げられるから",
    "q.t03#5.o3" to "実際の意味はない",
    "q.t03#5.e" to "計量は「少し重い気がする」を数字に変えます。同じザックでも、重複した食器、余分な衣類、満タンの水筒を外せば、たいてい 2〜3 kg 軽くなります。",
    "q.t03#6.p" to "トレッキングザックの重量上限として、よく挙げられるのは体重のどれくらいですか。",
    "q.t03#6.o0" to "20〜25%",
    "q.t03#6.o1" to "10%",
    "q.t03#6.o2" to "40%",
    "q.t03#6.o3" to "上限はない",
    "q.t03#6.e" to "この比率を超えると、登攀のエネルギー消費も受傷リスクも明らかに上がります。軽量化は「持って行かない装備」から始まります。",
    "q.t03#7.p" to "下りでのトレッキングポールの主な役割は何ですか。",
    "q.t03#7.o0" to "膝関節の負担を分担し、支点を一つ増やす",
    "q.t03#7.o1" to "速度を上げる",
    "q.t03#7.o2" to "ザックを軽くする",
    "q.t03#7.o3" to "身を守る",
    "q.t03#7.e" to "下りで膝にかかる衝撃は登りの数倍です。ポールは負担の一部を上肢へ移し、三つ目の支点にもなります。",
    "q.t04#0.p" to "登りで持続できるペースを保つ、正しいやり方はどれですか。",
    "q.t04#0.o0" to "「完全な文で話せる」強度で歩き、疲れる前に休む",
    "q.t04#0.o1" to "一気に頂上まで登ってから休む",
    "q.t04#0.o2" to "最も速い人に合わせる",
    "q.t04#0.o3" to "ずっととても遅く歩く",
    "q.t04#0.e" to "「トークテスト」が最も簡単な強度のものさしです。完全な文で話せなくなったら速度を落とします。息が上がってから止まると、回復にずっと時間がかかります。",
    "q.t04#1.p" to "水分補給の正しいリズムはどれですか。",
    "q.t04#1.o0" to "喉が渇いてから飲む",
    "q.t04#1.o1" to "20〜30 分ごとに少量ずつ飲み、暑い日は電解質も補う",
    "q.t04#1.o2" to "一度に 1 L 飲む",
    "q.t04#1.o3" to "トイレを減らすためできるだけ飲まない",
    "q.t04#1.e" to "渇きを感じた時点で、すでに体重の 1〜2% の水分が失われ、判断力と持久力が落ち始めています。決まった間隔で少量ずつ飲むほうが、一度に 1 L より吸収しやすいのです。",
    "q.t04#2.p" to "行動中のエネルギー補給として、より有効なのはどれですか。",
    "q.t04#2.o0" to "1 時間あたり 30〜60 g の炭水化物を、少量ずつ何回も",
    "q.t04#2.o1" to "空腹になってから一度にたくさん食べる",
    "q.t04#2.o2" to "スポーツドリンクだけ",
    "q.t04#2.o3" to "気力でキャンプまで持たせる",
    "q.t04#2.e" to "体が 1 時間に吸収できる炭水化物には限りがあり、一度に詰め込むと胃が張るだけです。歩きながら食べる（ナッツ、エナジーバー、パン）ほうが、止まってどか食いするより安定します。",
    "q.t04#3.p" to "低血糖の初期サインには何が含まれますか。",
    "q.t04#3.o0" to "手の震え、冷や汗",
    "q.t04#3.o1" to "急な不機嫌や反応の鈍さ",
    "q.t04#3.o2" to "視界が白っぽくなる、ふらつく",
    "q.t04#3.o3" to "急に元気になる",
    "q.t04#3.e" to "こうしたサインが出たら、まず止まって 15〜20 g の速効性炭水化物（飴、ジュース）をとります。10 分で明らかに楽になります。押し切ると倒れることがあります。",
    "q.t04#4.p" to "休憩が 10 分を超えないほうがよいのはなぜですか。",
    "q.t04#4.o0" to "体が冷えて筋肉が固まり、再出発に余計に力が要るから",
    "q.t04#4.o1" to "同行者に文句を言われるから",
    "q.t04#4.o2" to "時間の無駄だから",
    "q.t04#4.o3" to "根拠はない",
    "q.t04#4.e" to "長時間止まると心拍が下がり筋温も落ちて、歩き出しの最初の 1 km がひどく重くなります。短い休憩を何度も取るほうが、一度の長い休憩より総時間が短く済みます。",
    "q.t04#5.p" to "トレッキングでの「ガス欠（ハンガーノック）」は通常どんなとき起きますか。",
    "q.t04#5.o0" to "出発して 2〜3 時間でグリコーゲンが尽き、それまでほとんど補給していないとき",
    "q.t04#5.o1" to "1 日目の出発前",
    "q.t04#5.o2" to "下山のとき",
    "q.t04#5.o3" to "睡眠不足のとき",
    "q.t04#5.e" to "グリコーゲンの備蓄は中強度の運動でおよそ 90〜120 分分です。それを超えて炭水化物を補わないと、急に力が出ない、頭がふらつく、話したくなくなる、といった状態になります。",
    "q.t04#6.p" to "ペースが適切かどうかを判断する、最も実用的な主観的指標はどれですか。",
    "q.t04#6.o0" to "「トークテスト」——完全な文で話せるか",
    "q.t04#6.o1" to "心拍数の数字",
    "q.t04#6.o2" to "汗の量",
    "q.t04#6.o3" to "歩幅",
    "q.t04#6.e" to "完全な文で話せるなら、まだ有酸素の範囲です。話せないなら強度が高すぎて、長距離では早く尽きます。",
    "q.t04#7.p" to "暑い日の電解質補給で、最も見落とされやすいタイミングはどれですか。",
    "q.t04#7.o0" to "出発前と行程の前半。足がつってから補うのではない",
    "q.t04#7.o1" to "下山した後",
    "q.t04#7.o2" to "寝る前",
    "q.t04#7.o3" to "食事のとき",
    "q.t04#7.e" to "足がつった時点では、すでに不足しています。少量を、早めに、行程を通じて補うほうが、後からまとめて飲むより効きます。",
    "q.t15#0.p" to "入山前にスマホの地図について必ずすべきことは何ですか。",
    "q.t15#0.o0" to "オフライン地図をダウンロードし、オフラインで現在地が取れることを確認する",
    "q.t15#0.o1" to "キャッシュを消す",
    "q.t15#0.o2" to "ダークモードにする",
    "q.t15#0.o3" to "省電力モードをオンにする",
    "q.t15#0.e" to "「電池はあるが電波がない」とき、オフラインの地図＋オフラインの軌跡だけが使えます。",
    "q.t15#1.p" to "1:50,000 の地図で、2 cm は実際の何 m ですか。",
    "q.t15#1.o0" to "1,000 m",
    "q.t15#1.o1" to "100 m",
    "q.t15#1.o2" to "500 m",
    "q.t15#1.o3" to "2,000 m",
    "q.t15#1.e" to "1 cm = 500 m なので、2 cm は 1,000 m です。縮尺を間違えると、その後の計算はすべて狂います。",
    "q.t15#2.p" to "等高線が混んでいるほど、何を意味しますか。",
    "q.t15#2.o0" to "傾斜が急",
    "q.t15#2.o1" to "傾斜が緩い",
    "q.t15#2.o2" to "標高が高い",
    "q.t15#2.o3" to "道が広い",
    "q.t15#2.e" to "同じ水平距離の中で高低差が大きいということです。「この区間はきついか」はここで判断します。",
    "q.t15#3.p" to "野外で方角を判断する、最も確実で電子機器に頼らない方法はどれですか。",
    "q.t15#3.o0" to "コンパス＋地図",
    "q.t15#3.o1" to "木の育ち方を見る",
    "q.t15#3.o2" to "雲の流れを見る",
    "q.t15#3.o3" to "勘で決める",
    "q.t15#3.e" to "植生や雲の傾向は補助にしかならず、誤差が大きいです。コンパスと地図の組み合わせだけが安定しています。",
    "q.t15#4.p" to "道を間違えたかもしれないと気づいたとき、まず何をすべきですか。",
    "q.t15#4.o0" to "立ち止まり、目立つ地形を三つ振り返って位置を確認する",
    "q.t15#4.o1" to "そのまま進んで道を探す",
    "q.t15#4.o2" to "速度を上げて先へ進む",
    "q.t15#4.o3" to "友人に電話する",
    "q.t15#4.e" to "立ち止まって振り返ることが、「違う気がする」を「違うと確認した」に変える唯一の方法です。歩き続ければ誤差は広がるだけです。",
    "q.t15#5.p" to "オフラインのナビ一式として、事前に用意すべきものはどれですか。",
    "q.t15#5.o0" to "オフライン地図",
    "q.t15#5.o1" to "ルートの軌跡（GPX）",
    "q.t15#5.o2" to "予備の電源",
    "q.t15#5.o3" to "SNS アプリ",
    "q.t15#5.e" to "前三者が「電波がなくても使える」ことを保証します。SNS は山にネットがないので役に立ちません。",
    "q.t15#6.p" to "1 回の位置確認を正しい順序に並べてください。",
    "q.t15#6.o0" to "オフライン地図を開いて現在地を出す",
    "q.t15#6.o1" to "地形と照らし、自分がいる斜面と等高線の形を確認する",
    "q.t15#6.o2" to "次の目立つ地形を決める",
    "q.t15#6.o3" to "進行方向と残りの距離を確認する",
    "q.t15#6.e" to "位置確認は「青い点を見る」ことではなく、「青い点と地形が合う」ことです。二番目が要点になります。",
    "q.t15#7.p" to "同行者が「人の流れについていけば間違えない」と言いました。最も妥当な返答はどれですか。",
    "q.t15#7.o0" to "人流は別の目的地へ向かうこともある。まずルートを照合してからついていく",
    "q.t15#7.o1" to "ついていくのが一番楽",
    "q.t15#7.o2" to "人が多ければ必ず安全",
    "q.t15#7.o3" to "誰かに聞けば済む",
    "q.t15#7.e" to "分岐点の「人流」は別のルートであることがよくあります。地図を一度確認するコストは 10 秒です。",
    "q.t05#0.p" to "数日にわたるルートを組むとき、最初に決めるべきは何ですか。",
    "q.t05#0.o0" to "1 日あたりの距離と登攀量の上限、そして補給点と撤退点",
    "q.t05#0.o1" to "沿途にどんな見どころがあるか",
    "q.t05#0.o2" to "どの宿に泊まるか",
    "q.t05#0.o3" to "どんな写真を撮るか",
    "q.t05#0.e" to "まず「1 日に最大どれだけ歩くか」の線を引き、その中にルートを入れます。逆にすると歩き切れない行程になり、途中で夜間歩行を強いられます。",
    "q.t05#1.p" to "予備日の役割は何ですか。",
    "q.t05#1.o0" to "天候や傷病で遅れたとき、夜間歩行に圧縮せずに済む",
    "q.t05#1.o1" to "少し長く寝るため",
    "q.t05#1.o2" to "写真の時間を作るため",
    "q.t05#1.o3" to "実際の効果はない",
    "q.t05#1.e" to "数日のルートでは、遅れがほぼ必ず出ます。予備日があれば遅れは「一部を歩かない」で済み、なければ夜間歩行か危険区間の強行になります。",
    "q.t05#2.p" to "見積もりで最も過小評価しやすい時間はどれですか。",
    "q.t05#2.o0" to "道探しと修正",
    "q.t05#2.o1" to "水汲みと濾過",
    "q.t05#2.o2" to "設営・炊事・片づけ",
    "q.t05#2.o3" to "平地の歩行",
    "q.t05#2.e" to "地図上の距離は「歩く」ことだけに対応します。実際の一日には道探し、水汲み、テント設営、炊事、荷造りがあり、合計でたいてい 1.5〜2 時間かかります。",
    "q.t05#3.p" to "撤退点の密度として勧められるのはどれですか。",
    "q.t05#3.o0" to "少なくとも 1 日ごとに、下山できる分岐か集落がある",
    "q.t05#3.o1" to "全行程で一つあれば足りる",
    "q.t05#3.o2" to "不要",
    "q.t05#3.o3" to "5 日に一つ",
    "q.t05#3.e" to "撤退点が疎らだと、「必ず歩き切る」を計画に書き込んだのと同じです。各区間で最寄りの下山口を知っていて初めて、選択権が生まれます。",
    "q.t05#4.p" to "最も長い一日を初日に置くべきでないのはなぜですか。",
    "q.t05#4.o0" to "初日は体調も判断も最も悪く、荷物と標高にまだ慣れていないから",
    "q.t05#4.o1" to "初日は景色がよくないから",
    "q.t05#4.o2" to "初日は雨が多いから",
    "q.t05#4.o3" to "違いはない",
    "q.t05#4.e" to "体には一〜二日の順応が要ります。肩と背中が荷に慣れ、足が靴に慣れ、人もリズムに慣れます。最もきつい一日を中盤に置くと、成功率が上がり故障も減ります。",
    "q.t05#5.p" to "行程表に「到着予定 6 時間」と書いたとき、さらに加えるべきは何ですか。",
    "q.t05#5.o0" to "最新到着時刻。それを超えたら代替案を実行する",
    "q.t05#5.o1" to "予想気温",
    "q.t05#5.o2" to "同行者の電話番号",
    "q.t05#5.o3" to "追加は不要",
    "q.t05#5.e" to "予定時刻は期待値、最新時刻は判断の線です。最新時刻に着かなければ、予備のキャンプ地を使うか引き返す。賭けて進むのではありません。",
    "q.t05#6.p" to "数日の行程で「予備日」を設けるのはなぜですか。",
    "q.t05#6.o0" to "天候・傷病・交通の遅れが時間を食う。予備日がなければ安全の余裕が削られるから",
    "q.t05#6.o1" to "休むため",
    "q.t05#6.o2" to "写真のため",
    "q.t05#6.o3" to "費用を抑えるため",
    "q.t05#6.e" to "予備日は「計画の一部」です。無駄と考えると、最後に削られるのは休息と安全になります。",
    "q.t05#7.p" to "数日の行程で、毎日のキャンプ到着時刻はどう組むべきですか。",
    "q.t05#7.o0" to "設営と炊事のために、明るいうちの 1〜2 時間を残す",
    "q.t05#7.o1" to "暗くなる直前",
    "q.t05#7.o2" to "遅いほど涼しい",
    "q.t05#7.o3" to "どうでもよい",
    "q.t05#7.e" to "暗くなってからの設営は効率が極端に悪く、キャンプ地の危険も見落とします。「到着時刻」を行程に書くのは規律です。",
    "q.t06#0.p" to "キャンプ地と水源の距離は、通常どれくらい離すべきですか。",
    "q.t06#0.o0" to "5 m",
    "q.t06#0.o1" to "60 m",
    "q.t06#0.o2" to "200 m",
    "q.t06#0.o3" to "近ければ近いほどよい",
    "q.t06#0.e" to "60 m は多くの保護区の最低基準です。近すぎると水源を汚し、夜に水を飲みに来る動物とも遭遇します。洗面や食器洗いも水から 60 m 以上離します。",
    "q.t06#1.p" to "キャンプ地を選ぶとき、避けるべき場所はどれですか。",
    "q.t06#1.o0" to "急斜面の真下の落石地帯",
    "q.t06#1.o1" to "涸れた河床",
    "q.t06#1.o2" to "孤立した大木の下",
    "q.t06#1.o3" to "獣道が通るところ",
    "q.t06#1.e" to "四つとも「普段は平気、起きれば重大」な場所です。落石、鉄砲水、落雷、動物。キャンプ地は一晩動かない場所なので、こうしたリスクには余地がありません。",
    "q.t06#2.p" to "キャンプ地の地面に少し傾斜があるほうがよいのはなぜですか。",
    "q.t06#2.o0" to "水はけがよく、雨でも水が溜まらないから",
    "q.t06#2.o1" to "よく眠れるから",
    "q.t06#2.o2" to "見た目が整うから",
    "q.t06#2.o3" to "テントの変形を防ぐから",
    "q.t06#2.e" to "完全な平地は暴雨で水が溜まります。2〜3 度の緩い傾斜なら水が抜け、頭を高く足を低くすれば寝ている間にずり落ちません。",
    "q.t06#3.p" to "テントの向きはどうすると安定しますか。",
    "q.t06#3.o0" to "入口を風下に、長辺を風上に向ける",
    "q.t06#3.o1" to "入口を風上に向ける",
    "q.t06#3.o2" to "適当でよい",
    "q.t06#3.o3" to "日当たりに合わせる",
    "q.t06#3.e" to "入口が風下なら、出入りのたびに風が吹き込まず雨も入りにくくなります。長辺を風上に向けると受風面積が最小になり、ポールの負担も均一になります。",
    "q.t06#4.p" to "尾根の上にテントを張らないのはなぜですか。",
    "q.t06#4.o0" to "風が強く、落雷のリスクも高いから",
    "q.t06#4.o1" to "景色が開けすぎているから",
    "q.t06#4.o2" to "地面が硬いから",
    "q.t06#4.o3" to "水源に近すぎるから",
    "q.t06#4.e" to "尾根は地形の最高点で、風を遮るものがありません。雷雨時には最も雷撃を受けやすい位置でもあります。キャンプ地は尾根の風下側の少し低い所へ下げます。",
    "q.t06#5.p" to "撤収後にすべきことは何ですか。",
    "q.t06#5.o0" to "地面を戻し、ゴミをすべて持ち帰り、忘れ物がないか確認する",
    "q.t06#5.o1" to "そのまま立ち去る",
    "q.t06#5.o2" to "ゴミを土に埋める",
    "q.t06#5.o3" to "次の人のために薪を残す",
    "q.t06#5.e" to "キャンプ地は他の人も使う場所です。ペグ、包装、食べこぼしを確認し、踏み固めた草をできるだけ戻すのが最低限の礼儀です。",
    "q.t07#0.p" to "燃料の粗い見積もりはどれですか。",
    "q.t07#0.o0" to "1 人 1 日あたり 30〜50 g のガス",
    "q.t07#0.o1" to "1 人 1 日 200 g",
    "q.t07#0.o2" to "1 隊 1 日 50 g",
    "q.t07#0.o3" to "見積もりは不要",
    "q.t07#0.e" to "湯を沸かす中心の通常行程なら、1 人 1 日 30〜50 g が目安です。低温、雪解け、炊飯が多い場合は増やし、予備の一本も持つのが安全です。",
    "q.t07#1.p" to "食品計画で優先すべき性質はどれですか。",
    "q.t07#1.o0" to "熱量密度が高い",
    "q.t07#1.o1" to "保存が効き、傷みにくい",
    "q.t07#1.o2" to "洗い物が少なく、鍋を洗わずに済む",
    "q.t07#1.o3" to "長時間煮込む必要がある",
    "q.t07#1.e" to "ザックの 1 g は体力で払い、鍋の 1 分は燃料で払います。脱水食、ナッツ、オートミール、パンなど「水を加えれば食べられる」ものが最も割に合います。",
    "q.t07#2.p" to "高所で炭水化物が勧められるのはなぜですか。",
    "q.t07#2.o0" to "消化の酸素消費が少なく変換が速く、早く使えるエネルギーになるから",
    "q.t07#2.o1" to "炭水化物のほうが安いから",
    "q.t07#2.o2" to "炭水化物のほうが軽いから",
    "q.t07#2.o3" to "違いはない",
    "q.t07#2.e" to "脂肪は 1 g あたりの熱量は高いものの、代謝に多くの酸素を要します。酸素が乏しい環境では、炭水化物のほうが「酸素を食わない」燃料源です。",
    "q.t07#3.p" to "テント内でストーブを使うとき、最も重要な注意は何ですか。",
    "q.t07#3.o0" to "換気を保ち、一酸化炭素中毒を防ぐ",
    "q.t07#3.o1" to "火を弱めにする",
    "q.t07#3.o2" to "話さない",
    "q.t07#3.o3" to "先にロウソクで温める",
    "q.t07#3.e" to "一酸化炭素中毒の初期症状（頭痛、眠気）は高山病や疲労とほとんど区別がつかず、眠ってから事故になることが多いのです。テントには換気口を必ず残します。",
    "q.t07#4.p" to "野外で汲んだ水の、最も確実な処理はどれですか。",
    "q.t07#4.o0" to "1 分間煮沸する",
    "q.t07#4.o1" to "布で濾過する",
    "q.t07#4.o2" to "静置して沈殿させる",
    "q.t07#4.o3" to "砂糖を加える",
    "q.t07#4.e" to "煮沸は細菌・ウイルス・寄生虫を死滅させます。フィルターはウイルスへの効果が限られ、薬剤は待ち時間が要ります。高所は沸点が低いので、煮沸時間を適宜延ばします。",
    "q.t07#5.p" to "食品の小分けの最良の方法はどれですか。",
    "q.t07#5.o0" to "日ごとに分けて日付を書き、取り出すときに袋全体を探らなくて済むようにする",
    "q.t07#5.o1" to "全部を一つの大きな袋にまとめる",
    "q.t07#5.o2" to "元の包装のままザックに詰める",
    "q.t07#5.o3" to "味ごとに分ける",
    "q.t07#5.e" to "日ごとの小分けは消費のペースを管理でき、「前半で食べすぎ、後半で足りない」を避けられます。日付を書くのは、どれから使うかを知るためでもあります。",
    "q.t08#0.p" to "出発前に見るべき天気の情報三点はどれですか。",
    "q.t08#0.o0" to "24〜48 時間の傾向、降水確率、風力と体感温度",
    "q.t08#0.o1" to "その日の最高気温",
    "q.t08#0.o2" to "昨日の天気",
    "q.t08#0.o3" to "湿度",
    "q.t08#0.e" to "「今日は何度」だけでは情報量が乏しいのです。傾向は計画を変えるかを決め、降水確率は何を持つかを決め、風力は体感温度と開けた場所で立てるかを決めます。",
    "q.t08#1.p" to "積乱雲の頂部がかなとこ状に広がったら、何を意味しますか。",
    "q.t08#1.o0" to "雷雨が成熟し、強い降水・雹・落雷を伴い得る",
    "q.t08#1.o1" to "天気が回復に向かう",
    "q.t08#1.o2" to "ただの高雲で影響はない",
    "q.t08#1.o3" to "雪になる",
    "q.t08#1.e" to "かなとこ雲は上昇気流が対流圏界面まで達し、雲が最も発達した段階を示します。このときは尾根、開けた場所、孤立した木から速やかに離れます。",
    "q.t08#2.p" to "雷雨の前に現れ得る兆候はどれですか。",
    "q.t08#2.o0" to "遠くで雷鳴が聞こえる",
    "q.t08#2.o1" to "雲底が黒くなり、下がってくる",
    "q.t08#2.o2" to "風向が急に変わり、気温が急に下がる",
    "q.t08#2.o3" to "髪が逆立ち、皮膚がちりちりする",
    "q.t08#2.e" to "最後の一つは電荷がすでに強いサインで、落雷が近いことを意味します。ただちに高さを下げ、両足をそろえてしゃがみます。伏せて寝てはいけません。",
    "q.t08#3.p" to "雷雨に遭ったとき、正しい行動はどれですか。",
    "q.t08#3.o0" to "尾根と孤立した木から離れ、高さを下げ、隊員どうし約 50 m 離れる",
    "q.t08#3.o1" to "最も高い木の下に避難する",
    "q.t08#3.o2" to "尾根沿いを速く通過し続ける",
    "q.t08#3.o3" to "全員で抱き合って暖をとる",
    "q.t08#3.e" to "落雷は最も高い点を選びます。分散するのは、誰かが被雷したときに他が救助できるようにするためです。固まると、一発の落雷が複数の負傷者になります。",
    "q.t08#4.p" to "低体温症の最も早く確実な現れはどれですか。",
    "q.t08#4.o0" to "震えが続き、動作がぎこちなくなり、話し方が不明瞭になる",
    "q.t08#4.o1" to "皮膚が赤くなる",
    "q.t08#4.o2" to "大量に汗をかく",
    "q.t08#4.o3" to "心拍が遅くなる",
    "q.t08#4.e" to "震えは体が熱を産んで自救している状態です。震えが止まるのは改善ではなく、より重いサインのことがあります。処置は風を避ける、乾いた衣類に替える、断熱を足す、温かい飲み物。",
    "q.t08#5.p" to "同じ気温でも風があると寒く感じるのはなぜですか。",
    "q.t08#5.o0" to "風が皮膚表面からの熱の放出を速め、体感温度が気温より下がるから",
    "q.t08#5.o1" to "風が冷たい空気を服の中へ送るから",
    "q.t08#5.o2" to "心理的なものだから",
    "q.t08#5.o3" to "湿度が変わるから",
    "q.t08#5.e" to "これが風冷効果です。0 ℃ で 40 km/h の風なら、体感は −10 ℃ 近くになります。着る量は気温の数字ではなく体感温度で判断します。",
    "q.t16#0.p" to "キャンプの三区の基本的な分け方はどれですか。",
    "q.t16#0.o0" to "睡眠、炊事、トイレを分ける",
    "q.t16#0.o1" to "男性、女性、共用",
    "q.t16#0.o2" to "テント、車、火",
    "q.t16#0.o3" to "分ける必要はない",
    "q.t16#0.e" to "区を分けることで三つの問題を解きます。裸火のリスク、においが動物を呼ぶこと、衛生面の交差汚染です。",
    "q.t16#1.p" to "キャットホールの深さと水源からの距離として妥当なのはどれですか。",
    "q.t16#1.o0" to "深さ 15〜20 cm、水源から 60 m 以上",
    "q.t16#1.o1" to "深さ 5 cm、水から 5 m",
    "q.t16#1.o2" to "深ければ深いほど、遠ければ遠いほどよい",
    "q.t16#1.o3" to "掘る必要はない",
    "q.t16#1.e" to "浅すぎると分解されず、近すぎると水源を汚します。60 m が標準的な距離です。",
    "q.t16#2.p" to "トイレットペーパーの正しい処理はどれですか。",
    "q.t16#2.o0" to "袋に入れて持ち帰る",
    "q.t16#2.o1" to "燃やす",
    "q.t16#2.o2" to "キャットホールに埋める",
    "q.t16#2.o3" to "草むらに捨てる",
    "q.t16#2.e" to "紙を燃やすのは乾燥期に火災のリスクがあり、埋めても雪解けや動物の掘り返しで露出します。持ち帰るのが最もきれいです。",
    "q.t16#3.p" to "食器洗いの水の正しい処理はどれですか。",
    "q.t16#3.o0" to "残渣をこし取ってから撒き、残渣は持ち帰る",
    "q.t16#3.o1" to "そのまま沢に流す",
    "q.t16#3.o2" to "テントの脇に捨てる",
    "q.t16#3.o3" to "キャットホールに捨てる",
    "q.t16#3.e" to "残渣は汚染と動物を招く原因なのでこし取って持ち帰り、残りの水は一点に集めず分散して撒きます。",
    "q.t16#4.p" to "トレッキング中の足のケアで最も重要な三つはどれですか。",
    "q.t16#4.o0" to "毎日足を洗い、乾いた靴下に替え、靴を乾かす",
    "q.t16#4.o1" to "たくさん歩く",
    "q.t16#4.o2" to "厚い靴下を履く",
    "q.t16#4.o3" to "軟膏を塗る",
    "q.t16#4.e" to "水疱も浸軟も「湿り＋摩擦」から来ます。乾燥を保つことが、どんな軟膏より効きます。",
    "q.t16#5.p" to "キャンプの衛生で避けるべき行為はどれですか。",
    "q.t16#5.o0" to "テントの中で物を食べる",
    "q.t16#5.o1" to "食べ残しをキャンプに残す",
    "q.t16#5.o2" to "水源のそばで食器を洗う",
    "q.t16#5.o3" to "寝る前に靴を前室に入れる",
    "q.t16#5.e" to "前三者は動物と汚染を睡眠区へ招きます。靴を前室に置くのはよくあるやり方ですが、まず土を払ってからにします。",
    "q.t16#6.p" to "朝の撤収の順序を並べてください。",
    "q.t16#6.o0" to "まずシュラフを畳んで防水袋に入れる",
    "q.t16#6.o1" to "テント内の小物とゴミを片づける",
    "q.t16#6.o2" to "テントを畳み、露と霜を払う",
    "q.t16#6.o3" to "キャンプ地を見回し、忘れ物がないか確認する",
    "q.t16#6.e" to "最後の一段が最も抜けやすいところです。キャンプ地の忘れ物は、無痕（Leave No Trace）で最もよくある失点です。",
    "q.t16#7.p" to "キャンプ地の近くに動物の痕跡（糞、掘り返し）がありました。どうすべきですか。",
    "q.t16#7.o0" to "食べ物を高い所に吊るすか密閉して、睡眠区から離して置く",
    "q.t16#7.o1" to "そのままそこで料理を続ける",
    "q.t16#7.o2" to "少し与える",
    "q.t16#7.o3" to "食べ物をテントに入れる",
    "q.t16#7.e" to "動物はにおいに引き寄せられます。食べ物をテントに入れるのは最も危険なやり方で、動物を寝ている場所へ直接招くことになります。",
    "q.t09#0.p" to "3,000 m 以上では、睡眠標高の上げ方をどう抑えるのが勧められますか。",
    "q.t09#0.o0" to "1 日 500 m 以内",
    "q.t09#0.o1" to "1 日 1,000 m",
    "q.t09#0.o2" to "1 日 1,500 m",
    "q.t09#0.o3" to "制限はない",
    "q.t09#0.e" to "「高く歩き、低く寝る」がよく使われる戦略です。日中はより高くまで上がってよいのですが、寝る高さは 1 日 500 m を超えないようにします。上がりすぎが AMS の最大の誘因です。",
    "q.t09#1.p" to "急性高山病（AMS）の最も典型的な症状の組はどれですか。",
    "q.t09#1.o0" to "頭痛に、吐き気または食欲低下、さらにめまいと倦怠感",
    "q.t09#1.o1" to "関節痛と発疹",
    "q.t09#1.o2" to "血の混じる咳が続く",
    "q.t09#1.o3" to "39 ℃ の発熱",
    "q.t09#1.e" to "三つが揃って初めて意味を持ちます。頭痛だけなら脱水や疲労のこともありますが、食欲低下と倦怠感が加われば AMS らしくなります。",
    "q.t09#2.p" to "AMS の症状が出た後の正しい対応はどれですか。",
    "q.t09#2.o0" to "上昇を止め、その場で順応するか下降する",
    "q.t09#2.o1" to "薬を飲んで計画どおり上がり続ける",
    "q.t09#2.o2" to "水を多く飲んで歩き続け、やり過ごす",
    "q.t09#2.o3" to "速度を上げてキャンプに着いてから休む",
    "q.t09#2.e" to "原則は「症状を抱えたまま上へ行かない」です。軽く、条件が許せばその場でもう一日滞在します。悪化すれば必ず下降します。",
    "q.t09#3.p" to "ただちに下降すべき危険なサインはどれですか。",
    "q.t09#3.o0" to "安静にしていても息が苦しい",
    "q.t09#3.o1" to "歩行が不安定で、酔ったようになる",
    "q.t09#3.o2" to "意識がもうろうとする、行動が異常になる",
    "q.t09#3.o3" to "軽い頭痛",
    "q.t09#3.e" to "前三者は HAPE や HACE に入っている可能性を示します。処置の方向は一つだけで、下降しながら酸素を投与し、医療支援を求めます。",
    "q.t09#4.p" to "「低い所で寝る」ことが勧められるのはなぜですか。",
    "q.t09#4.o0" to "夜間は呼吸が浅くなり低酸素が最も強く、低い所で寝ると夜の低酸素が軽くなるから",
    "q.t09#4.o1" to "低い所のほうが静かだから",
    "q.t09#4.o2" to "低い所のほうが暖かいから",
    "q.t09#4.o3" to "低い所の景色がよいから",
    "q.t09#4.e" to "睡眠中は換気量が落ち、酸素飽和度は覚醒時より低くなります。その日の最高点より数百 m 低い所にキャンプを置くのは、夜の自分に余裕を残すことです。",
    "q.t09#5.p" to "体力のある人は高山病になりにくいですか。",
    "q.t09#5.o0" to "そうとは限らない。主に上昇速度と個人差で決まる",
    "q.t09#5.o1" to "はい。体力があるほど安全",
    "q.t09#5.o2" to "いいえ。体力があるほどなりやすい",
    "q.t09#5.o3" to "年齢だけで決まる",
    "q.t09#5.e" to "体力のある人は速く歩き高くまで上がりやすく、かえって問題を起こしがちです。体力と順応力を分けて見ることが、高所ではとても重要です。",
    "q.t10#0.p" to "高所トレッキングの服装は、通常いくつの層に分けますか。",
    "q.t10#0.o0" to "汗を逃がす層、保温の層、防風の層",
    "q.t10#0.o1" to "下着と上着",
    "q.t10#0.o2" to "綿の服、セーター、レインウェア",
    "q.t10#0.o3" to "多ければ多いほどよい",
    "q.t10#0.e" to "層に分けるのは着込むためではなく、いつでも調整できるようにするためです。歩いて暑くなれば外を脱ぎ、止まったらすぐ着る。冷えは休憩のその 10 分に起きやすいのです。",
    "q.t10#1.p" to "標高が 1,000 m 上がるごとに、紫外線はおよそどれだけ増えますか。",
    "q.t10#1.o0" to "10〜12%",
    "q.t10#1.o1" to "2%",
    "q.t10#1.o2" to "50%",
    "q.t10#1.o3" to "変わらない",
    "q.t10#1.e" to "空気が薄くなり、紫外線を遮る力が減ります。さらに雪面が約 80% を反射するため、顔や鼻は「二回焼かれる」に近い曝露になります。",
    "q.t10#2.p" to "高所の日焼け対策に含めるべきものはどれですか。",
    "q.t10#2.o0" to "UV400 のサングラス",
    "q.t10#2.o1" to "SPF50+ の日焼け止めを 2〜3 時間ごとに塗り直す",
    "q.t10#2.o2" to "UV カットのリップクリーム",
    "q.t10#2.o3" to "帽子かバンダナ",
    "q.t10#2.e" to "四つがそれぞれ目、皮膚、唇、顔を担当します。唇はメラニンの防御がなく、最も焼けて割れやすく、最も見落とされやすい部位です。",
    "q.t10#3.p" to "手足が最初に冷えるのはなぜですか。",
    "q.t10#3.o0" to "体が深部体温を優先し、四肢の血管を収縮させるから",
    "q.t10#3.o1" to "手足は脂肪が少ないから",
    "q.t10#3.o2" to "手足は動きが少ないから",
    "q.t10#3.o3" to "心理的なものだから",
    "q.t10#3.e" to "これは正常な身を守る仕組みです。だから保温の要点は体幹にあります。体幹が暖かければ手足に血流が戻ります。手袋だけ足しても効果は限られます。",
    "q.t10#4.p" to "手袋と靴下が濡れたときはどうすべきですか。",
    "q.t10#4.o0" to "すぐ取り替える。濡れた肌着は熱を奪い続ける",
    "q.t10#4.o1" to "そのまま使い、歩いて温まれば乾く",
    "q.t10#4.o2" to "絞ればよい",
    "q.t10#4.o3" to "翌日まで待って替える",
    "q.t10#4.e" to "濡れた織物は乾いたものより何倍も熱を伝えます。手足が凍えて動きが鈍ると、装備の操作も歩行も誤りやすくなります。",
    "q.t10#5.p" to "雪目（スノーブラインドネス）とは何ですか。",
    "q.t10#5.o0" to "紫外線による角膜のやけど。通常 6〜12 時間後に激痛、羞明、流涙が起きる",
    "q.t10#5.o1" to "雪の照り返しで目が疲れること",
    "q.t10#5.o2" to "低温で眼球が凍ること",
    "q.t10#5.o3" to "ビタミン A の不足",
    "q.t10#5.e" to "雪目には遅れがあり、日中は平気で夜に痛み出します。予防はほぼサングラスだけに頼ります。曇天や雪霧の日も同じように必要です。",
    "q.t11#0.p" to "高所で食事が喉を通らないとき、どうすべきですか。",
    "q.t11#0.o0" to "自分から少量ずつ何回も食べる。炭水化物を優先する",
    "q.t11#0.o1" to "食べずに食欲が出るのを待つ",
    "q.t11#0.o2" to "お湯だけ飲む",
    "q.t11#0.o3" to "コーヒーで乗り切る",
    "q.t11#0.e" to "高所ではエネルギーの不足が順応を直接遅らせます。一度の大餐を数回の小食に分けるほうが、一食分を無理に食べ切るより実行しやすいのです。",
    "q.t11#1.p" to "水分が足りているかを判断する最も簡単な指標はどれですか。",
    "q.t11#1.o0" to "尿の色が淡い黄色を保っていること",
    "q.t11#1.o1" to "毎日 3 L 飲むこと",
    "q.t11#1.o2" to "喉が渇かないこと",
    "q.t11#1.o3" to "体重が変わらないこと",
    "q.t11#1.e" to "尿の色は最も直接的な水分指標です。濃い黄色はすでに不足気味、完全に透明なら飲みすぎの可能性があり、電解質を少し補います。",
    "q.t11#2.p" to "高所で夜よく眠れない、最もよくある原因は何ですか。",
    "q.t11#2.o0" to "低酸素による周期性呼吸が、浅い眠りから何度も覚まさせるから",
    "q.t11#2.o1" to "テントが快適でないから",
    "q.t11#2.o2" to "静かすぎるから",
    "q.t11#2.o3" to "日中に歩く量が少ないから",
    "q.t11#2.e" to "これは生理的なもので、「8 時間眠れていない」と焦る必要はありません。注意すべきは頭痛や吐き気を伴う不眠で、それは AMS の可能性があります。",
    "q.t11#3.p" to "高所でよく眠るのに役立つ方法はどれですか。",
    "q.t11#3.o0" to "寝る前に食べすぎない",
    "q.t11#3.o1" to "酒を飲まない",
    "q.t11#3.o2" to "寝る前に適量の水分をとる",
    "q.t11#3.o3" to "医師の指導のもとでアセタゾラミドを使う",
    "q.t11#3.e" to "前三者は自分でできること、最後は医師の評価が必要です。薬は医療上の判断であり、同行者同士で勧め合うものではありません。",
    "q.t11#4.p" to "高所で酒がいつもより危険なのはなぜですか。",
    "q.t11#4.o0" to "アルコールが呼吸を抑えて低酸素を強め、しかも AMS の症状を隠すから",
    "q.t11#4.o1" to "アルコールで脱水になるから",
    "q.t11#4.o2" to "アルコールで眠れなくなるから",
    "q.t11#4.o3" to "アルコールは高カロリーだから",
    "q.t11#4.e" to "高所では呼吸の駆動そのものが弱まっており、アルコールはさらに抑え込みます。厄介なのは、酔った状態が HACE の初期とよく似ていて誤判断を招くことです。",
    "q.t11#5.p" to "高所でカフェインは使えますか。",
    "q.t11#5.o0" to "適量なら使えるが、休息と水分補給の代わりにはならない",
    "q.t11#5.o1" to "まったく摂ってはいけない",
    "q.t11#5.o2" to "多ければ多いほどよい",
    "q.t11#5.o3" to "朝だけならよい",
    "q.t11#5.e" to "コーヒー一杯で高山病になるわけでも、疲労が治るわけでもありません。頭痛には少し効きますが、それで押し切ると問題を先送りするだけです。",
    "q.t12#0.p" to "出発前に整えておくべき心の準備はどれですか。",
    "q.t12#0.o0" to "「着けないかもしれない」を受け入れ、撤退を計画の一部にしておく",
    "q.t12#0.o1" to "絶対に諦めないと決意する",
    "q.t12#0.o2" to "目標を手の甲に書く",
    "q.t12#0.o3" to "家族に行程を伝えない",
    "q.t12#0.e" to "撤退を計画に書き込んでこそ、人は止まるべきときに止まれます。逆に「必ず達成する」を目標にすると、危険なサインを無視してでも達成しようとします。",
    "q.t12#1.p" to "隊のペースについていけないと気づいたとき、最良の対応はどれですか。",
    "q.t12#1.o0" to "正直に伝え、最も遅い人のペースで歩いてもらう",
    "q.t12#1.o1" to "歯を食いしばってついていき、足を引っ張らない",
    "q.t12#1.o2" to "黙って少しずつ遅れる",
    "q.t12#1.o3" to "誰にも言わずに一人で下山する",
    "q.t12#1.e" to "無理について行くと数時間で使い果たし、その後のミスや受傷につながります。最も遅い人に合わせるのは、効率でもあり安全でもあります。",
    "q.t12#2.p" to "露出感や高所恐怖への対処として有効な方法はどれですか。",
    "q.t12#2.o0" to "足元を区切って見て、遠くを凝視しない",
    "q.t12#2.o1" to "呼吸をゆっくりし、意識を動作に向ける",
    "q.t12#2.o2" to "三点支持を保ち、動作を小さくする",
    "q.t12#2.o3" to "目を閉じて速く通過する",
    "q.t12#2.e" to "恐怖は呼吸を浅くし動作を硬くします。そして硬さこそがミスの源です。意識を「次の足場」に戻すのが最も効きます。",
    "q.t12#3.p" to "「ここまで来たのだから、無駄にはできない」という考えの問題はどこですか。",
    "q.t12#3.o0" to "すでに払った時間を、危険を続ける理由にしてしまっている",
    "q.t12#3.o1" to "前向きさが足りない",
    "q.t12#3.o2" to "歩くのが遅くなる",
    "q.t12#3.o3" to "問題はない",
    "q.t12#3.e" to "払った時間は歩き続けても戻ってきませんが、歩き続けることで新たに取り返しのつかない代価を払うことがあります。判断は前を見て行い、後ろは見ません。",
    "q.t12#4.p" to "出発前に隊で決めておくべきことは何ですか。",
    "q.t12#4.o0" to "誰に止める権限があるか、はぐれたときの集合地点、何時間で通報するか",
    "q.t12#4.o1" to "誰が写真を撮るか",
    "q.t12#4.o2" to "誰が一番速いか",
    "q.t12#4.o3" to "誰が一番重い荷物を背負うか",
    "q.t12#4.e" to "「止める」を個人の勇気ではなく、あらかじめ与えた権限にします。そうして初めて、人は止まるべきときに口を開けます。集合地点と通報の計画も同じです。",
    "q.t12#5.p" to "急に気分が落ち込み、話したくなくなり、動作が鈍くなりました。まず何を考えるべきですか。",
    "q.t12#5.o0" to "エネルギーや水分の不足かもしれず、高山病や低体温症の初期かもしれない",
    "q.t12#5.o1" to "ただ機嫌が悪いだけ",
    "q.t12#5.o2" to "性格の問題",
    "q.t12#5.o3" to "一人で静かにする時間が必要",
    "q.t12#5.e" to "野外では、感情の変化が生理的な問題の最初の顔になることがよくあります。まず食べ物、水分、衣類、状態の確認。気分の話はその後にします。",
    "q.t13#0.p" to "長距離ルートの補給点の密度として勧められるのはどれですか。",
    "q.t13#0.o0" to "3〜5 日ごとに一つ",
    "q.t13#0.o1" to "全行程で一つ",
    "q.t13#0.o2" to "毎日一つ",
    "q.t13#0.o3" to "補給は不要",
    "q.t13#0.e" to "補給点は長いルートを小区間に分け、各区間を独立して評価し退出できるようにします。間隔が長すぎると、一度の天候の遅れが全行程に波及します。",
    "q.t13#1.p" to "脱水食品の 1 日あたりの重量は、おおよそどれくらいですか。",
    "q.t13#1.o0" to "600〜800 g",
    "q.t13#1.o1" to "200 g",
    "q.t13#1.o2" to "1.5 kg",
    "q.t13#1.o3" to "3 kg",
    "q.t13#1.e" to "脱水主食は 1 日 600〜800 g で、およそ 2,500〜3,000 kcal になります。ナッツや油脂など高カロリーの補給を足すと、総重量はもう少し増えます。",
    "q.t13#2.p" to "長距離ルートの出発前に確認すべき規定はどれですか。",
    "q.t13#2.o0" to "入園や保護区の許可",
    "q.t13#2.o1" to "野外での焚き火が認められるか",
    "q.t13#2.o2" to "ゴミをすべて持ち出す義務があるか",
    "q.t13#2.o3" to "ドローンを飛ばせるか",
    "q.t13#2.e" to "どれも軽い話ではありません。無許可の入山は退去を求められ、違反の火は乾燥期に山火事を招き、ドローンは多くの保護区で完全に禁止されています。",
    "q.t13#3.p" to "現金を一部持って行くのはなぜですか。",
    "q.t13#3.o0" to "山間の補給点や集落、交通は現金しか受け付けないことが多く、通信が切れて決済できないこともあるから",
    "q.t13#3.o1" to "専門家らしく見えるから",
    "q.t13#3.o2" to "テーブルの脚に挟めるから",
    "q.t13#3.o3" to "重さを量りやすいから",
    "q.t13#3.e" to "奥まった場所ほど現金に頼ります。小額紙幣が最も実用的で、非常用の分は日常の出費と混ぜずに別にしておきます。",
    "q.t13#4.p" to "長距離ルートの緊急通信はどう準備すべきですか。",
    "q.t13#4.o0" to "衛星通信機器かビーコン、加えて紙の地図と計画書を連絡相手に渡しておく",
    "q.t13#4.o1" to "携帯電話だけ",
    "q.t13#4.o2" to "笛だけ",
    "q.t13#4.o3" to "不要",
    "q.t13#4.e" to "長距離ルートの多くは全行程で電波がありません。機器はメッセージを送れ、地図と計画書は留守を預かる人に「どこへ行き、いつ通報すべきか」を伝えます。",
    "q.t13#5.p" to "計画に 20% の余裕を残すとは、具体的に何を指しますか。",
    "q.t13#5.o0" to "食料、燃料、時間、現金を、理論値より二割多く用意する",
    "q.t13#5.o1" to "水だけ多く持つ",
    "q.t13#5.o2" to "時間だけ余分にとる",
    "q.t13#5.o3" to "必要ない",
    "q.t13#5.e" to "余裕は不意の事態のための空間です。天候で一日遅れ、ストーブが二食分多く燃え、道中で余分な交通費がかかる。それで行程が一気に苦しくなるのは避けたいところです。",
    "q.t14#0.p" to "足首を捻挫した直後の、現場での処置の基本はどれですか。",
    "q.t14#0.o0" to "安静、冷却、圧迫、挙上（RICE）",
    "q.t14#0.o1" to "すぐ温めて揉む",
    "q.t14#0.o2" to "歩き続けて動かせば治る",
    "q.t14#0.o3" to "内出血を力強く揉み出す",
    "q.t14#0.e" to "急性期の温熱とマッサージは出血と腫れを悪化させます。48 時間は冷却・圧迫・挙上を中心にし、その後に状態を見て徐々に動かします。",
    "q.t14#1.p" to "低体温症の人の処置の順序として正しいのはどれですか。",
    "q.t14#1.o0" to "風を避け、乾いた衣類に替え、地面から断熱し、意識のある人には温かい飲み物、ゆっくり復温する",
    "q.t14#1.o1" to "まず温かい飲み物を飲ませ、その後に着替えさせる",
    "q.t14#1.o2" to "手足をさすって循環を促す",
    "q.t14#1.o3" to "歩かせて熱を産ませる",
    "q.t14#1.e" to "まず熱の喪失を止め、その後に復温です。四肢を揉んだり歩かせたりすると冷えた血が体幹へ戻り、かえって危険が増します。",
    "q.t14#2.p" to "熱中症が疑われるとき、最初にすべきことは何ですか。",
    "q.t14#2.o0" to "速やかに日陰の風通しのよい所へ移し、衣服を緩めて冷却を始める",
    "q.t14#2.o1" to "白湯を大量に飲ませる",
    "q.t14#2.o2" to "歩き続けて汗をかけばよい",
    "q.t14#2.o3" to "冷えないよう衣類をかける",
    "q.t14#2.e" to "熱中症の核心は放熱の失敗で、まず冷やし、その後に補液です。意識がはっきりしないときは無理に飲ませず、誤嚥を避けます。",
    "q.t14#3.p" to "救助要請に必ず含めるべき内容はどれですか。",
    "q.t14#3.o0" to "正確な位置または座標",
    "q.t14#3.o1" to "人数とけがの状態",
    "q.t14#3.o2" to "手持ちの装備と補給",
    "q.t14#3.o3" to "連絡先と電池の残量",
    "q.t14#3.e" to "救助側がまず知りたいのは「どこで、何人で、どれくらい重傷で、いつまで持つか」です。情報が欠けると、確認に数時間余計にかかります。",
    "q.t14#4.p" to "連絡不通時の計画はどう決めるべきですか。",
    "q.t14#4.o0" to "決まった確認時刻を決め、何時間遅れたら誰が誰に連絡し、いつ通報するかを定める",
    "q.t14#4.o1" to "そのときになって考える",
    "q.t14#4.o2" to "家族に「だいたいどこへ行く」とだけ伝える",
    "q.t14#4.o3" to "計画は不要",
    "q.t14#4.e" to "計画は時刻と行動まで具体化します。何時に連絡がなければ電話し、さらに何時間後に地元の救助へ連絡する。「何かあったら連絡して」では、計画がないのと同じです。",
    "q.t14#5.p" to "自分で対処を続けず、必ず救助を求めるべきなのはどんなときですか。",
    "q.t14#5.o0" to "自力で動けない、意識が変化している、状況が悪化し続けている",
    "q.t14#5.o1" to "少し疲れただけ",
    "q.t14#5.o2" to "靴が擦れる",
    "q.t14#5.o3" to "行程が予定より 2 時間遅れた",
    "q.t14#5.e" to "救助を求める基準は前もって考えておきます。歩ける、意識がある、良くなっているなら自分で撤退できます。歩けない、意識がない、悪化しているなら、早く助けを求めるべきです。",
    "q.t17#0.p" to "ハイキングで最も実用的な水分補給の指標はどれですか。",
    "q.t17#0.o0" to "尿の色が淡い黄色を保つこと",
    "q.t17#0.o1" to "口渇感",
    "q.t17#0.o2" to "汗の量",
    "q.t17#0.o3" to "体重",
    "q.t17#0.e" to "口渇を感じた時点で水分は足りていません。尿の色は最も安価な毎日のセルフチェックです。",
    "q.t17#1.p" to "熱射病の判定の核心はどれですか。",
    "q.t17#1.o0" to "深部体温が 40 ℃ を超え、意識変化がある",
    "q.t17#1.o1" to "汗を大量にかく",
    "q.t17#1.o2" to "皮膚が赤くなる",
    "q.t17#1.o3" to "心拍が速い",
    "q.t17#1.e" to "意識変化が決め手です。現場に体温計がなければ意識状態で判断し、直ちに冷やします。",
    "q.t17#2.p" to "熱中症の処置の正しい順序はどれですか。",
    "q.t17#2.o0" to "日陰へ移動 → 衣服を緩める → 冷やす → 電解質を補う",
    "q.t17#2.o1" to "まず輸液してから冷やす",
    "q.t17#2.o2" to "まず四肢をマッサージする",
    "q.t17#2.o3" to "まず水を飲ませる",
    "q.t17#2.e" to "冷却が優先です。補液が効き始めるには時間がかかりますが、高温による臓器の障害は即座に進みます。",
    "q.t17#3.p" to "足首を捻挫した直後、48 時間以内にすべきことはどれですか。",
    "q.t17#3.o0" to "冷却・圧迫・挙上を行い、温めることと強く揉むことは避ける",
    "q.t17#3.o1" to "温めてマッサージする",
    "q.t17#3.o2" to "そのまま歩き続ける",
    "q.t17#3.o3" to "内出血を強く揉みほぐす",
    "q.t17#3.e" to "急性期に温めたり揉んだりすると出血と腫れが悪化します。RICE の四つは一つも欠かせません。",
    "q.t17#4.p" to "熱中症で意識がはっきりしない人への対応はどれですか。",
    "q.t17#4.o0" to "無理に水を飲ませず、濡れタオルで冷やして早急に救助を求める",
    "q.t17#4.o1" to "水を流し込む",
    "q.t17#4.o2" to "塩分タブレットを飲ませる",
    "q.t17#4.o3" to "自分で飲ませる",
    "q.t17#4.e" to "嚥下反射が不確かなときに飲ませると誤嚥します。この状況で有効なのは冷却と専門の救助だけです。",
    "q.t17#5.p" to "水疱が歩行に支障をきたすとき、正しい処置はどれですか。",
    "q.t17#5.o0" to "消毒して縁から排液し、表皮を残して被覆する",
    "q.t17#5.o1" to "皮ごと剥がす",
    "q.t17#5.o2" to "中央に穴を開ける",
    "q.t17#5.o3" to "何もしない",
    "q.t17#5.e" to "残した表皮が最良の被覆になります。中央に穴を開けると裂けやすくなります。",
    "q.t17#6.p" to "ハイキング中の熱中症リスクを高めるものはどれですか。",
    "q.t17#6.o0" to "湿度が高く風がない",
    "q.t17#6.o1" to "正午に登り続ける",
    "q.t17#6.o2" to "水だけを補い、電解質を補わない",
    "q.t17#6.o3" to "淡色で通気性のよい服を着る",
    "q.t17#6.e" to "前三つはいずれも放熱や電解質のバランスを損ないます。淡色で通気性のよい服はむしろ冷却策です。",
    "q.t17#7.p" to "ハイキングの救急キットに最低限入れておくべきものはどれですか。",
    "q.t17#7.o0" to "水疱用パッドと被覆材",
    "q.t17#7.o1" to "鎮痛・解熱薬",
    "q.t17#7.o2" to "弾性包帯",
    "q.t17#7.o3" to "抗生物質",
    "q.t17#7.e" to "前三つはハイキングで最も多いトラブル——足、痛み、捻挫——に対応します。抗生物質は医師の判断が必要です。",
    "q.t17#8.p" to "熱疲労への対応を正しい順に並べてください。",
    "q.t17#8.o0" to "運動を中止し、日陰へ移動する",
    "q.t17#8.o1" to "衣服を緩め、体を冷やし始める",
    "q.t17#8.o2" to "電解質を含む液体を補う",
    "q.t17#8.o3" to "意識と状態を観察し、必要なら救助を求める",
    "q.t17#8.e" to "順序の核心は「まず熱暴露を止める」ことです。歩き続けると熱疲労は熱射病へ進みます。",
    "q.t17#9.p" to "正午の登坂中に、同行者が突然の頭痛と吐き気、皮膚の冷たい汗を訴えました。まずすべきはどれですか。",
    "q.t17#9.o0" to "直ちに中止して冷やし、電解質を補って観察する",
    "q.t17#9.o1" to "キャンプまで歩き続ける",
    "q.t17#9.o2" to "鎮痛薬を飲ませて歩き続ける",
    "q.t17#9.o3" to "厚着をさせる",
    "q.t17#9.e" to "これは熱疲労の典型的な現れです。歩き続けると急速に悪化し、熱射病は数十分で命に関わります。",
    "q.t20#0.p" to "長距離ハイキングで最も多い装備の故障はどれですか。",
    "q.t20#0.o0" to "靴底の剥がれとエアマットの空気漏れ",
    "q.t20#0.o1" to "バックパックのベルト切れ",
    "q.t20#0.o2" to "テントの穴",
    "q.t20#0.o3" to "ストックの折損",
    "q.t20#0.e" to "どちらも「歩けない」「眠れない」に直結します。出発前の点検ではここを優先します。",
    "q.t20#1.p" to "靴底が剥がれ始めたとき、現場で最も適切なのはどれですか。",
    "q.t20#1.o0" to "まずテープで固定してこれ以上の裂けを防ぎ、町で専用の接着剤を使う",
    "q.t20#1.o1" to "火で溶かして接着する",
    "q.t20#1.o2" to "ロープで縛ればよい",
    "q.t20#1.o3" to "そのまま歩き、取れてから考える",
    "q.t20#1.e" to "テープの役割は「損傷の拡大を止める」ことで、修理ではありません。裂けが広がると靴底が丸ごと外れ、本当に歩けなくなります。",
    "q.t20#2.p" to "ポールが折れたとき、現場で最も実用的なのはどれですか。",
    "q.t20#2.o0" to "補修用スリーブを断口に被せて使い続ける",
    "q.t20#2.o1" to "テープで団子状に巻く",
    "q.t20#2.o2" to "テントを捨てる",
    "q.t20#2.o3" to "木の枝を 1 本のポールの代わりにする",
    "q.t20#2.e" to "スリーブは強度の大半を取り戻せます。テープ巻きは 1〜2 晩の応急にすぎず、断口はさらに悪化します。",
    "q.t20#3.p" to "ダウンジャケットに小さな穴が開きました。正しい処置はどれですか。",
    "q.t20#3.o0" to "パッチを貼って押さえる。叩かない",
    "q.t20#3.o1" to "出てきた羽毛を叩き落とす",
    "q.t20#3.o2" to "火で炙って塞ぐ",
    "q.t20#3.o3" to "糸で縫い閉じる",
    "q.t20#3.e" to "叩くと羽毛が針穴から出続けます。パッチと軽い圧迫が最も確実な損傷の抑制です。",
    "q.t20#4.p" to "エアマットの空気漏れの原因として当てはまらないものはどれですか。",
    "q.t20#4.o0" to "日光に当たったこと",
    "q.t20#4.o1" to "地面の尖った石",
    "q.t20#4.o2" to "バルブが閉まっていない",
    "q.t20#4.o3" to "縫い目の疲労",
    "q.t20#4.e" to "日光が気室を直接破ることはありません。前三つに加えて最も多いのは、地面をきれいにしていないことです。",
    "q.t20#5.p" to "ハイキングの補修キットに入れておく価値があるものはどれですか。",
    "q.t20#5.o0" to "Dyneema テープ",
    "q.t20#5.o1" to "パンクパッチと接着剤",
    "q.t20#5.o2" to "予備のバックル",
    "q.t20#5.o3" to "ドライバー一式",
    "q.t20#5.e" to "前三つはテント生地、気室、バックルという 3 大故障をカバーします。ドライバーは「使わない重さ」です。",
    "q.t20#6.p" to "毎日キャンプに着いてから 5 分かけて確認する価値があるのはどれですか。",
    "q.t20#6.o0" to "靴の中に砂や小石が入っていないか",
    "q.t20#6.o1" to "靴下が濡れ切っていないか",
    "q.t20#6.o2" to "バックパックの縫い目とバックル",
    "q.t20#6.o3" to "ストックの長さ",
    "q.t20#6.e" to "前の二つが足の状態を決め、三つ目が翌日のベルト切れを防ぎます。ストックの長さはいつでも調整できるので毎日見る必要はありません。",
    "q.t20#7.p" to "装備の「寿命」について正しい考え方はどれですか。",
    "q.t20#7.o0" to "使用頻度と外観で判断する。購入年では決めない",
    "q.t20#7.o1" to "新しく買えば必ずよい",
    "q.t20#7.o2" to "壊れてから替える",
    "q.t20#7.o3" to "古いほど信頼できる",
    "q.t20#7.e" to "同じ装備でも使用頻度で寿命は大きく変わります。摩耗（靴底、バックル、コーティング）を見るほうが、日付を見るより確実です。",
    "q.t18#0.p" to "渡渉できるかどうかを決める最も重要な量はどれですか。",
    "q.t18#0.o0" to "水深 × 流速",
    "q.t18#0.o1" to "水深",
    "q.t18#0.o2" to "川幅",
    "q.t18#0.o3" to "水温",
    "q.t18#0.e" to "同じ深さでも流速が倍なら衝撃は倍になります。水深だけを測るのがハイキングで最も多い誤判断です。",
    "q.t18#1.p" to "渡渉の工学的な安全上限はどれですか。",
    "q.t18#1.o0" to "水深 × 流速 > 1.0 m²/s は渡渉不可とみなす",
    "q.t18#1.o1" to "水深 > 0.5 m",
    "q.t18#1.o2" to "流速 > 3 m/s",
    "q.t18#1.o3" to "川幅 > 20 m",
    "q.t18#1.e" to "1.0 は健康な成人、短距離、軽装という条件での値です。隊の内部基準を 0.8 にするのは保守的な運用で、標準ではありません。",
    "q.t18#2.p" to "枝を流して流速を測るときの判断基準はどれですか。",
    "q.t18#2.o0" to "小走りでないと追いつけないなら、すでに歩行速度を超えている",
    "q.t18#2.o1" to "枝が沈むかどうか",
    "q.t18#2.o2" to "枝が回るかどうか",
    "q.t18#2.o3" to "水面に泡があるか",
    "q.t18#2.e" to "岸を並んで追いかけるのが最も直感的な測り方です。小走りになれば流速はすでに大きすぎます。",
    "q.t18#3.p" to "水深がどこを超えたら別の点を選ぶべきですか。",
    "q.t18#3.o0" to "隊で最も背の低い人の太腿",
    "q.t18#3.o1" to "リーダーの腰",
    "q.t18#3.o2" to "膝",
    "q.t18#3.o3" to "胸",
    "q.t18#3.e" to "最も強い人ではなく最も低い人を基準にします。隊は最も弱い人に制限される——渡渉の鉄則です。",
    "q.t18#4.p" to "「ランナウト」とは何ですか。",
    "q.t18#4.o0" to "足を滑らせたとき、流れが人を運んでいく下流の区域",
    "q.t18#4.o1" to "川岸の急斜面",
    "q.t18#4.o2" to "河床の勾配",
    "q.t18#4.o3" to "上流の集水域",
    "q.t18#4.e" to "ランナウトに滝、流木、切り立った岸があれば、目の前の水が浅くてもその点は使えません。",
    "q.t18#5.p" to "渡渉点を選ぶとき、優先して探すのはどれですか。",
    "q.t18#5.o0" to "広くて浅い区間",
    "q.t18#5.o1" to "狭くて深い区間",
    "q.t18#5.o2" to "曲がりの外側",
    "q.t18#5.o3" to "流木の近く",
    "q.t18#5.e" to "川幅が広いほど浅く緩やかなのが普通です。曲がりの外側は深く流れが速く、流木はフットエントラップの致命的な原因になります。",
    "q.t18#6.p" to "水位がどれだけ上がると、もとの安全な点が危険になりますか。",
    "q.t18#6.o0" to "15 cm",
    "q.t18#6.o1" to "1 m",
    "q.t18#6.o2" to "50 cm",
    "q.t18#6.o3" to "その程度では変わらない",
    "q.t18#6.e" to "15 cm でも流速と水深は目に見えて変わります。氷河融水の流域では特に顕著です。",
    "q.t18#7.p" to "次のうち、その渡渉点をすぐにあきらめるべきなのはどれですか。",
    "q.t18#7.o0" to "川底が見えず、水が濁っている",
    "q.t18#7.o1" to "下流に流木や切り立った岸がある",
    "q.t18#7.o2" to "上流で豪雨があったばかり",
    "q.t18#7.o3" to "河床が緩やかな砂利の河原",
    "q.t18#7.e" to "前三つは「評価できない、または失敗を許容できない」状態です。砂利の河原はむしろよい河床です。",
    "q.t18#8.p" to "渡渉前に必ず済ませる装備の処理はどれですか。",
    "q.t18#8.o0" to "チェストベルトを外す",
    "q.t18#8.o1" to "ショルダーベルトを緩める",
    "q.t18#8.o2" to "外付けを締めて水をすくいにくくする",
    "q.t18#8.o3" to "携帯と薬を防水袋に入れる",
    "q.t18#8.e" to "前の二つはザックを脱げるようにするため、後の二つは重要な物資を失わないためです。四つとも水に入る前に済ませます。",
    "q.t18#9.p" to "一度の渡渉の判断順序を並べてください。",
    "q.t18#9.o0" to "まず「渡らなければならないのか」を問う（迂回、橋、水位が下がるのを待つ）",
    "q.t18#9.o1" to "点を選び、水深と流速を測る",
    "q.t18#9.o2" to "隊全員のザックと服装の扱いが同じであることを確認する",
    "q.t18#9.o3" to "編隊または単独の方法で通過する",
    "q.t18#9.e" to "最初の問いがリスクの大半を消します。多くの人がこれを飛ばして「どう渡るか」から考え始めます。",
    "q.t18#10.p" to "午後の川が朝より明らかに増水している主な理由はどれですか。",
    "q.t18#10.o0" to "氷河融水の日変化で、午後に流量が最大になる",
    "q.t18#10.o1" to "午後は雨が多い",
    "q.t18#10.o2" to "上流のダムが放流する",
    "q.t18#10.o3" to "蒸発",
    "q.t18#10.e" to "融水型の川の日変化は規則的で、明け方に最低、午後に最高になります。渡渉は午前中に組むのが基本です。",
    "q.t19#0.p" to "三角隊形の正しいやり方はどれですか。",
    "q.t19#0.o0" to "三人が内側を向いて肩かザックをつかみ、一度に一人が片脚だけ動かす",
    "q.t19#0.o1" to "三人が横に並んで手をつなぎ、一緒に歩く",
    "q.t19#0.o2" to "三人が前後に並ぶ",
    "q.t19#0.o3" to "二人が一人を担ぐ",
    "q.t19#0.e" to "一緒に踏み出すと編隊全体が同時に支えを失います。腕をつかむのは疲れやすく外れやすいので、肩かザックをつかみます。",
    "q.t19#1.p" to "横列編隊で最も強い人はどこに立つべきですか。",
    "q.t19#1.o0" to "両端（特に上流側）",
    "q.t19#1.o1" to "中央",
    "q.t19#1.o2" to "最後尾",
    "q.t19#1.o3" to "どこでもよい",
    "q.t19#1.e" to "上流側が流れの衝撃を主に受け、下流側が受け止め役になります。初心者は中央に置き、両側に強い人を配置します。",
    "q.t19#2.p" to "編隊で進むときの声かけのリズムはどれですか。",
    "q.t19#2.o0" to "「一歩、止まれ、一歩」",
    "q.t19#2.o1" to "「いち、に、いち」で続けて歩く",
    "q.t19#2.o2" to "声を出さない",
    "q.t19#2.o3" to "それぞれのペースで歩く",
    "q.t19#2.e" to "リズムをそろえるのは「一度に一人しか動かない」ようにするためです。同時に踏み出すのが編隊で最も多い失敗です。",
    "q.t19#3.p" to "転倒した直後の第一原則はどれですか。",
    "q.t19#3.o0" to "立ち上がらない",
    "q.t19#3.o1" to "すぐ立ち上がる",
    "q.t19#3.o2" to "ロープをつかむ",
    "q.t19#3.o3" to "流木をつかむ",
    "q.t19#3.e" to "足が石の隙間や流木に挟まっていることがあり、流れが人を水中に押しつけて「フットエントラップ」になります。これが渡渉死亡の最も典型的な機序です。",
    "q.t19#4.p" to "転倒後の正しい姿勢はどれですか。",
    "q.t19#4.o0" to "仰向けで足を下流に向け、水面に近づけ、頭を上げる",
    "q.t19#4.o1" to "うつ伏せで泳ぐ",
    "q.t19#4.o2" to "直立して立ち泳ぎする",
    "q.t19#4.o3" to "膝を抱える",
    "q.t19#4.e" to "仰向け＋足を下流にすると、底を踏まずに足で障害物を押せますし、頭も守れます。",
    "q.t19#5.p" to "渡渉時のザックのヒップベルトについて正しいのはどれですか。",
    "q.t19#5.o0" to "米国系は外して捨てやすくし、NZ の MSC は締めて浮力にする。要は隊全員で統一すること",
    "q.t19#5.o1" to "必ず外す",
    "q.t19#5.o2" to "必ず締める",
    "q.t19#5.o3" to "どちらでもよい",
    "q.t19#5.e" to "どちらの立場にも前提があります。本当に危険なのは「半分が外し、半分が締めている」状態で、救助時に息が合いません。",
    "q.t19#6.p" to "ザックが岩に挟まったときはどうすべきですか。",
    "q.t19#6.o0" to "両腕を上げてショルダーベルトから抜ける。ザックは捨ててよい",
    "q.t19#6.o1" to "力いっぱい引っ張る",
    "q.t19#6.o2" to "潜って外す",
    "q.t19#6.o3" to "仲間を待つ",
    "q.t19#6.e" to "ザックが挟まると体が流れに押さえ込まれます。腕を上げて脱ぐのが最速の離脱動作です。",
    "q.t19#7.p" to "岸に上がる直前の正しい動作はどれですか。",
    "q.t19#7.o0" to "まずヒップベルトを外し、次に上流側のショルダーベルトを外して、ザックを前に浮かせて支えにしながら立ち上がる",
    "q.t19#7.o1" to "先に立ち上がってからザックを外す",
    "q.t19#7.o2" to "ザックを岸へ投げる",
    "q.t19#7.o3" to "そのままよじ登る",
    "q.t19#7.e" to "ザックの浮力は支えになりますが、順序を誤ると支えを失います。ヒップベルト、次に上流側のショルダーベルトが標準です。",
    "q.t19#8.p" to "編隊渡渉の前に済ませておく準備はどれですか。",
    "q.t19#8.o0" to "陸上でつかみ方と声かけを練習する",
    "q.t19#8.o1" to "誰が上流側に立つかを決める",
    "q.t19#8.o2" to "ヒップベルトとチェストベルトの扱いを統一する",
    "q.t19#8.o3" to "各自が自分のやり方で渡ると決める",
    "q.t19#8.e" to "編隊は連携に依存し、連携は事前の統一でしか作れません。ばらばらだと水中で編隊が崩れます。",
    "q.t19#9.p" to "ロープによる援護渡渉について正しいのはどれですか。",
    "q.t19#9.o0" to "多くの隊は熟練しておらず、リスクが利益を上回りうる",
    "q.t19#9.o1" to "ロープは岸に固定し、人に結んではならない",
    "q.t19#9.o2" to "ロープの下流側を通る",
    "q.t19#9.o3" to "急流にまっすぐ張ったロープが最も安全",
    "q.t19#9.e" to "張った横ロープは人を水中に押しつけます。ロープは専門技術で、その場で思いついて始めるものではありません。",
    "q.t19#10.p" to "一度の編隊渡渉を正しい順に並べてください。",
    "q.t19#10.o0" to "点を選び、ランナウトが安全か確認する",
    "q.t19#10.o1" to "全員がチェストベルトを外し、ヒップベルトの扱いを統一する",
    "q.t19#10.o2" to "陸上で編隊と声かけを練習する",
    "q.t19#10.o3" to "声に合わせて編隊ごと横に移動し、一度に一人が踏み出す",
    "q.t19#10.o4" to "上がったら乾いた服に着替え、温かい飲み物をとる",
    "q.t19#10.e" to "最後の段が最も忘れられます。冷水による低体温は、転倒よりよく起きます。",
    "q.t19#11.p" to "仲間が水中で急に立ち止まりました。最も疑うべきはどれですか。",
    "q.t19#11.o0" to "足が挟まっている。直ちに助け、仰向けのままにさせる",
    "q.t19#11.o1" to "休んでいる",
    "q.t19#11.o2" to "景色を見ている",
    "q.t19#11.o3" to "合図を待っている",
    "q.t19#11.e" to "突然動かなくなるのはフットエントラップの典型的な現れです。このとき必要なのは「もがかない、仰向けを保つ、上流から近づく人がいる」ことです。",
    "q.t21#0.p" to "夜行について最も合理的な姿勢はどれですか。",
    "q.t21#0.o0" to "必要がなければ歩かない。歩くならペースを落とし、隊形の管理を強める",
    "q.t21#0.o1" to "夜は涼しいので歩くのに向く",
    "q.t21#0.o2" to "夜行のほうが安全",
    "q.t21#0.o3" to "ヘッドランプさえあればよい",
    "q.t21#0.e" to "夜間は地形判断とナビゲーションの難度が倍増し、事故率も上がります。夜行は「仕方ないときの選択」で、戦略ではありません。",
    "q.t21#1.p" to "夜行の照明構成として正しいのはどれですか。",
    "q.t21#1.o0" to "ヘッドランプ＋予備電池＋予備光源（小型ライトか二台目のヘッドランプ）",
    "q.t21#1.o1" to "携帯のライトだけ",
    "q.t21#1.o2" to "ヘッドランプだけ",
    "q.t21#1.o3" to "ろうそく",
    "q.t21#1.e" to "明かりを失うことは、夜には行動能力を失うことと同じです。予備光源はロープ系統の冗長性と同じ考え方の「冗長」です。",
    "q.t21#2.p" to "夜行時の隊の間隔はどうすべきですか。",
    "q.t21#2.o0" to "間隔を詰め、先頭が後続を頻繁に確認し、分岐では人を残す",
    "q.t21#2.o1" to "間隔を広げて各自で歩く",
    "q.t21#2.o2" to "体力に任せて自然に散開する",
    "q.t21#2.o3" to "後続が自分でルートを探す",
    "q.t21#2.e" to "夜は視野が狭く、遅れた人が見つかりにくくなります。分岐に人を残すのが最も安価な保険です。",
    "q.t21#3.p" to "雷雨が近いことを示す初期サインに当てはまらないものはどれですか。",
    "q.t21#3.o0" to "気温が少しずつ上がる",
    "q.t21#3.o1" to "積乱雲が急速に発達する",
    "q.t21#3.o2" to "遠くで鈍い雷鳴",
    "q.t21#3.o3" to "髪が逆立ち、皮膚がしびれる",
    "q.t21#3.e" to "雷雨の接近時はふつう気温が下がります。髪が逆立つのは電荷が集まっているサインで、ただちに高い場所を離れます。",
    "q.t21#4.p" to "山で雷雨に遭ったとき、まずすべきはどれですか。",
    "q.t21#4.o0" to "速やかに低い場所へ下がり、尾根・水辺・孤立した大木から離れる",
    "q.t21#4.o1" to "山頂の大きな岩の下に隠れる",
    "q.t21#4.o2" to "木の下に立つ",
    "q.t21#4.o3" to "歩き続ける",
    "q.t21#4.e" to "高点、水辺、孤立した木、金属はいずれも落雷の通り道になりやすい。低所へ下がって散開するのが唯一有効な対策です。",
    "q.t21#5.p" to "避雷のときの正しい姿勢はどれですか。",
    "q.t21#5.o0" to "散開してしゃがみ、両足をそろえる。伏せない",
    "q.t21#5.o1" to "地面に伏せる",
    "q.t21#5.o2" to "まっすぐ立つ",
    "q.t21#5.o3" to "木に抱きつく",
    "q.t21#5.e" to "両足をそろえると跨歩電圧が減ります。伏せると体と地面の接触面積が増え、かえって危険です。",
    "q.t21#6.p" to "雷雨のときに同時に警戒すべきものはどれですか。",
    "q.t21#6.o0" to "急な降温による低体温",
    "q.t21#6.o1" to "豪雨による鉄砲水",
    "q.t21#6.o2" to "視界の急減による道迷い",
    "q.t21#6.o3" to "紫外線によるやけど",
    "q.t21#6.e" to "雷雨は降温・豪雨・霧を伴います。単一のリスクではなく「リスクの組」です。",
    "q.t21#7.p" to "出発前に行程を連絡担当者へ伝えておくことは、夜行や雷雨の場面でどんな役割を果たしますか。",
    "q.t21#7.o0" to "隊が時間どおりに着かなかったとき、外部が速やかに捜索を始められる",
    "q.t21#7.o1" to "礼儀のため",
    "q.t21#7.o2" to "保険金の請求のため",
    "q.t21#7.o3" to "役に立たない",
